window.SDT_LESSONS=window.SDT_LESSONS||{};window.SDT_LESSONS["L3"]={"deck":"L3","slides":[{"p":1,"title":"표지: #4 경량철골공사","terms":["경량철골","Metal Stud","Dry-Wall"],"pass1":[{"kind":"say","lines":["이번 강의는 #4 경량철골공사예요. **경량철골**은 얇은 철로 만든 뼈대 재료예요.","현장 작업 순서로 보면 가설, 철거 다음에 오는 세 번째 칸이에요.","주문처럼 외워요. 가설, 철거, 경량철골, 마감.","벽 뼈대는 **메탈 스터드(Metal Stud)**, 천장 뼈대는 위에 매다는 천장틀이에요."]},{"kind":"analogy","head":"뼈대에 살 붙이기","scene":"벽을 사람 몸이라고 생각해 봐요. 얇은 철 기둥이 뼈, 양쪽에 붙는 판이 살, 사이에 채우는 솜이 속이에요.","map":[["뼈","**메탈 스터드(Metal Stud)**와 런너"],["살","**석고보드(Gypsum Board)**"],["속","**흡음충진재**나 **단열재(INSULATION)**"]]}],"pass2":[{"kind":"points","head":"이 범위(1~16쪽)에서 볼 것","items":["**경량철골**이 무엇이고 왜 쓰는지, 그리고 장점 다섯 가지","벽 뼈대 부재: **C-스터드(C-Stud)**, **CH-스터드(CH-Stud)**, **E-스터드(E-Stud)**","잡아 주는 부재: **스틸런너(Steel Runner)**, **J 런너(J Runner)**, **퍼링 채널(Furring Channel)**","보호하고 보강하는 부재: **보강 채널(Brace Channel)**, **메탈 트림(Metal Trim)**, **케이싱 비드(Casing Bead)**, **코너 비드(Corner Bead)**","**건식벽체(Dry-Wall)**의 벽 두께 계산과 시공 순서"]},{"kind":"say","lines":["표지 아래에 참고문헌 네 권이 적혀 있어요. 인테리어 디자인 시공 실무, 실내건축재료,","실내건축실무, 다시 인테리어 도면 이해하기예요.","표지 사진은 아연 도금된 철 부재와 비계예요. 이 과목의 재료가 무엇인지 보여 주는 사진이에요."]}],"pass3":[]},{"p":2,"title":"경량철골공사와 강재벽체의 구성","terms":["경량철골","Metal Stud","Dry-Wall","Light Gauge Structure","아연 도금","Gypsum Board"],"pass1":[{"kind":"say","lines":["**경량철골**은 나무로 짜던 벽틀, 천장틀을 철재로 바꾼 소재 또는 제품이에요.","불에 안 타고 건물이 가벼워지는 것이 바꾼 가장 큰 이유예요.","크게 벽체 틀 만들기와 천장 틀 만들기, 두 갈래로 나뉘어요."]},{"kind":"compare","head":"두 갈래로 갈리는 지도","cols":["어디","뼈대 이름"],"rows":[["벽","**메탈 스터드(Metal Stud)**"],["천장","**LGS(Light Gauge Structure)** 경량천장틀"]]}],"pass2":[{"kind":"points","head":"**경량철골**의 정의(슬라이드 그대로)","items":["목재를 이용하여 벽체틀이나 천장틀을 구성하였던 작업을 철재 등의 재료로 바꾼 것이에요.","불연성을 확보하여 안전을 도모하고, 건물의 자체 중량을 줄이는 역할을 해요.","벽체 틀의 기본 소재는 **메탈 스터드(Metal Stud)**예요.","천장 틀은 일반적으로 **LGS(Light Gauge Structure)**라고 불리는 경량천장틀을 기본으로 해요."]},{"kind":"points","head":"**경량철골** 공사의 장점 다섯 가지 (서술 단골)","items":["1. 불연 확보","2. 건물의 자중(중량) 감소","3. 공기 단축 효과","4. 구성부재 조합에 따라 다양한 기능과 내화, 차음 성능 구현 가능","5. 전기 배선 및 배관 등의 설비 설치가 간단함"]},{"kind":"compare","head":"구분 및 사용 자재","cols":["구분","구성 부재","더 쓰는 것"],"rows":[["벽체 틀","**메탈 스터드(Metal Stud)**, 런너 등","필요시 각형강관으로 보강"],["천장 틀","캐링채널, 행거, 행거볼트 등","M-Bar, T-Bar 등 천장틀 시스템"]]},{"kind":"points","head":"여기서 나오는 이름 두 개","items":["**건식벽체(Dry-Wall)**: 스터드에 의한 골조와 **석고보드(Gypsum Board)**로 구성된 벽체예요.","**메탈 스터드(Metal Stud)**의 기본 구성은 스터드와 런너(Runner), 보강용 채널이에요.","경량 형강은 표면에 녹 방지를 위해 일반적으로 **아연 도금**이 되어 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**경량철골** 공사의 장점으로 슬라이드에 제시되지 않은 것은?","choices":["공기 단축 효과","불연 확보","습식공법이라 마감 강도가 높다","건물의 자중 감소"],"a":2,"why":"장점은 불연, 자중 감소, 공기 단축, 내화와 차음 성능 구현, 설비 설치 간단이에요. 경량철골 벽은 물을 안 쓰는 **건식공법**이에요."},{"kind":"check","q":"경량철골 천장 틀을 일반적으로 부르는 이름은?","choices":["HPL","**LGS(Light Gauge Structure)**","SGP","FRP"],"a":1,"why":"벽체 틀은 **메탈 스터드(Metal Stud)**, 천장 틀은 **LGS(Light Gauge Structure)** 경량천장틀이에요."},{"kind":"check","q":"경량 형강 표면에 녹 방지를 위해 일반적으로 하는 처리는?","choices":["**아연 도금**","HPL 접착","FRP 코팅","유성 페인트 도장"],"a":0,"why":"슬라이드 오른쪽 위 참고 문장에 적혀 있어요."},{"kind":"english","head":"서술 답안: 경량철골공사의 장점 다섯 가지","en":"경량철골공사는 불연성을 확보하고, 건물의 자중을 줄이며, 공기를 단축하고, 구성부재 조합에 따라 내화와 차음 성능을 구현할 수 있으며, 전기 배선과 배관 등 설비 설치가 간단하다.","ko":"불, 무게, 시간, 성능, 설비 다섯 칸으로 나눠 적으면 빠짐이 없어요.","tip":"앞 글자만 모아 불, 무, 시, 성, 설 로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**경량철골** 벽은 물을 쓰지 않는 **건식공법**이에요. 습식이라고 하면 틀려요.","벽 뼈대는 **메탈 스터드(Metal Stud)**, 천장 뼈대는 **LGS(Light Gauge Structure)**. 둘을 바꿔 쓰지 마세요.","**아연 도금**은 녹 방지용이에요. 불연과 헷갈리지 마세요."]}],"walk":{"head":null,"parts":[{"b":[0.03,0.1,0.72,0.17],"c":[0,0.084,0.792,0.202],"r":6.9703,"img":"img/L3/walk/p002_24_01.jpg","say":"위 본문: 경량철골의 정의와, 벽체 틀과 천장 틀로 나뉜다는 설명이에요."},{"b":[0.037,0.3,0.34,0.29],"c":[0.02,0.284,0.374,0.322],"r":2.0649,"img":"img/L3/walk/p002_24_02.jpg","say":"왼쪽 박스: 경량철골공사의 장점 다섯 가지예요. 번호까지 그대로 외워요."},{"b":[0.385,0.3,0.6,0.29],"c":[0.34,0.284,0.66,0.322],"r":3.6439,"img":"img/L3/walk/p002_24_03.jpg","say":"오른쪽 사진 세 장: 세로로 선 스터드 벽틀과, 천장에 매달린 천장틀 현장이에요."},{"b":[0.03,0.66,0.68,0.1],"c":[0,0.6344,0.748,0.1511],"r":8.8006,"img":"img/L3/walk/p002_24_04.jpg","say":"4.1 강재벽체의 구성. 메탈 스터드 + 런너 + 보강용 채널 = 건식벽체(Dry-Wall)."},{"b":[0.037,0.775,0.5,0.14],"c":[0.012,0.759,0.55,0.172],"r":5.6848,"img":"img/L3/walk/p002_24_05.jpg","say":"아래 박스: 벽체 틀과 천장 틀에 각각 무슨 자재를 쓰는지 정리한 칸이에요."},{"b":[0.67,0.03,0.32,0.04],"c":[0.648,0,0.352,0.11],"r":5.6889,"img":"img/L3/walk/p002_24_06.jpg","say":"오른쪽 위 작은 글씨: 경량 형강은 녹 방지를 위해 일반적으로 아연 도금이 되어 있어요."}]}},{"p":3,"title":"메탈 스터드의 종류 1: C-스터드","terms":["C-Stud","Metal Stud","Gypsum Board","먹매김"],"pass1":[{"kind":"say","lines":["**C-스터드(C-Stud)**는 벽 뼈대의 세로 기둥이에요. 가장 많이 쓰는 스터드예요.","단면이 알파벳 C처럼 한쪽이 트인 모양이라 이런 이름이 붙었어요.","책장으로 치면 세로로 선 칸막이판 자리예요."]},{"kind":"analogy","head":"벽의 갈비뼈","scene":"일정한 간격으로 세워 둔 갈비뼈를 떠올려 보세요. 그 위에 판을 대면 벽이 돼요.","map":[["갈비뼈 한 대","**C-스터드(C-Stud)** 한 개"],["갈비뼈 사이 간격","스터드 설치 간격"],["바깥을 덮는 살","**석고보드(Gypsum Board)**"]]}],"pass2":[{"kind":"points","head":"**C-스터드(C-Stud)**의 정체와 자리","items":["내연 강판을 기본 소재로 한 세로 기둥 부재예요.","칸막이벽, 내화피복기둥 및 보 등 비내력 건식벽의 기본적인 재료예요.","비내력이란 건물 무게를 받지 않는다는 뜻이에요. 벽을 나누는 역할만 해요.","공사 순서로는 **먹매김**과 런너 설치가 끝난 다음에 세우고, 그 뒤에 **석고보드(Gypsum Board)**를 붙여요."]},{"kind":"points","head":"**C-스터드(C-Stud)** 숫자 네 가지 (시험 단골)","items":["설치 간격은 300mm와 450mm로 해요. 슬라이드 메모에 450을 주로 사용한다고 적혀 있어요.","일반적으로 65mm **메탈 스터드(Metal Stud)**가 시공 현장에서 적용되고 있어요.","길이는 2,400~5,000mm로 비규격제품이에요.","비규격이라 현장에서 천장고를 실측한 뒤에 발주해요."]},{"kind":"compare","head":"슬라이드 규격표에서 보이는 값","cols":["항목","표에 적힌 값"],"rows":[["품명","Stud (K.S품), 아래 칸은 M-Stud"],["두께 THK","0.8 (괄호로 1.0)"],["폭 A","50, 65, 75, 90, 100, 150"],["다리 B","45"],["길이 C","주문생산 (made-to-order)"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**C-스터드(C-Stud)**에 대한 설명으로 옳지 않은 것은?","choices":["일반적으로 65mm가 적용된다","길이는 규격품이라 실측 없이 발주한다","설치 간격은 300mm와 450mm로 한다","비내력 건식벽의 기본 재료이다"],"a":1,"why":"길이 2,400~5,000mm의 비규격제품이라 천장고 실측 후에 발주해요."},{"kind":"exam","src":"문제은행 l23","q":"현장에서 일반적으로 적용되는 C-스터드의 폭은 몇 mm인가? (숫자만)","qko":"현장에서 제일 많이 쓰는 스터드 폭이 몇 mm인지 묻는 문제예요.","solve":["슬라이드 본문에 일반적으로 65mm 메탈 스터드가 시공 현장에서 적용된다고 적혀 있어요.","규격표에서도 65가 분홍으로 표시돼 있어요.","이 65mm는 뒤에 나오는 벽 두께 계산(103mm, 115mm)에서 그대로 다시 쓰여요."],"answer":"65"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["간격 300mm와 450mm 중 현장에서 주로 쓰는 것은 450mm예요.","길이 2,400~5,000mm는 비규격이에요. 규격품이라고 하면 틀려요.","M-stud(B.S품)는 영국 표준이고 잘 사용하지 않아요. 가장 많이 쓴다고 하면 틀려요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1584,0.1453],"c":[0,0.0208,0.2,0.1773],"r":2.0054,"img":"img/L3/walk/p003_h.jpg"},"parts":[{"b":[0.035,0.185,0.3,0.05],"c":[0.02,0.155,0.33,0.11],"r":5.3333,"img":"img/L3/walk/p003_23_01.jpg","say":"제목: 1) C-스터드 (C-Stud), 가장 일반적으로 사용."},{"b":[0.03,0.23,0.47,0.23],"c":[0.0065,0.214,0.517,0.262],"r":3.5081,"img":"img/L3/walk/p003_23_02.jpg","say":"본문 다섯 줄. 소재, 쓰이는 곳, 간격, 폭, 길이 순서로 읽어요."},{"b":[0.265,0.3,0.1,0.032],"c":[0.215,0.261,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p003_23_03.jpg","say":"분홍 메모: 450을 주로 사용. 시험에서 450이 답이 되는 이유예요."},{"b":[0.5,0.29,0.28,0.22],"c":[0.486,0.274,0.308,0.252],"r":2.1728,"img":"img/L3/walk/p003_23_04.jpg","say":"오른쪽 사진: C자로 트인 단면이 보여요. 안쪽에 나사가 물리는 홈이 있어요."},{"b":[0.03,0.565,0.46,0.19],"c":[0.007,0.549,0.506,0.222],"r":4.0521,"img":"img/L3/walk/p003_23_05.jpg","say":"왼쪽 아래 표: Stud(K.S품) 줄에 폭 50, 65, 100이 분홍으로 표시돼 있어요."},{"b":[0.49,0.815,0.24,0.045],"c":[0.478,0.7825,0.264,0.11],"r":4.2667,"img":"img/L3/walk/p003_23_06.jpg","say":"메모: M-stud(B.S품)는 영국 표준이라 잘 사용하지 않아요."}]}},{"p":4,"title":"메탈 스터드의 종류 2: CH-스터드","terms":["CH-Stud","C-Stud","E-Stud","J Runner","Gypsum Board"],"pass1":[{"kind":"say","lines":["**CH-스터드(CH-Stud)**는 한쪽에서만 작업할 수 있는 곳에 쓰는 스터드예요.","엘리베이터 통로처럼 반대편에 발 디딜 바닥이 없는 자리를 떠올리면 돼요.","옆에 홈이 있어서 **석고보드(Gypsum Board)**를 옆으로 밀어 끼울 수 있어요."]},{"kind":"compare","head":"한 줄로 구별하기","cols":["스터드","쓰는 자리"],"rows":[["**C-스터드(C-Stud)**","양쪽에서 작업할 수 있는 보통 칸막이벽"],["**CH-스터드(CH-Stud)**","한쪽 면에서만 시공할 수 있는 자리"]]}],"pass2":[{"kind":"points","head":"**CH-스터드(CH-Stud)**의 정체","items":["수직하중에 견딜 수 있도록 고안된 비내력 강제 받침대예요.","단면이 C에 홈(H)이 하나 더 있는 모양이라 보드를 끼워 세울 수 있어요.","바닥 슬라브가 없어서 한쪽 면 방향에서만 시공 가능한 경우에 사용해요.","슬라이드 메모의 OPEN공간이 바로 그 뚫린 공간을 뜻해요."]},{"kind":"points","head":"쓰는 곳 (내화와 차음이 필요한 곳)","items":["계단실","대형 통풍구, 덕트시설","고층건물의 수직 샤프트","이런 곳은 반대편에 사람이 설 바닥이 없어서 한쪽에서만 작업해요."]},{"kind":"points","head":"짝으로 같이 나오는 부재","items":["바닥과 천장에서 잡아 주는 것은 **J 런너(J Runner)**예요.","끝을 마무리할 때는 **E-스터드(E-Stud)**를 써요.","보드는 25mm 방화석고보드를 홈에 끼워 넣어요(다음 쪽 시공 그림)."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"바닥 슬라브가 없어 한쪽 면 방향에서만 시공 가능한 계단실, 샤프트 등에 사용하는 스터드는?","choices":["**E-스터드(E-Stud)**","**C-스터드(C-Stud)**","M-스터드","**CH-스터드(CH-Stud)**"],"a":3,"why":"**CH-스터드(CH-Stud)**는 내화, 차음이 요구되는 수직 샤프트 등에 써요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**CH-스터드(CH-Stud)**는 비내력이에요. 수직하중에 견디도록 고안됐다는 말과 내력벽은 다른 말이에요.","짝은 **J 런너(J Runner)**예요. **스틸런너(Steel Runner)**가 아니에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1584,0.1412],"c":[0,0.0208,0.2,0.1732],"r":2.0529,"img":"img/L3/walk/p004_h.jpg"},"parts":[{"b":[0.03,0.225,0.56,0.12],"c":[0.002,0.209,0.616,0.152],"r":7.2047,"img":"img/L3/walk/p004_23_01.jpg","say":"본문 세 줄: 비내력 강제 받침대, 쓰는 곳, 한쪽 면에서만 시공."},{"b":[0.415,0.25,0.09,0.032],"c":[0.36,0.211,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p004_23_02.jpg","say":"분홍 메모: OPEN공간. 반대편이 뚫려 있는 공간이라는 뜻이에요."},{"b":[0.065,0.38,0.31,0.36],"c":[0.0495,0.362,0.341,0.396],"r":1.5309,"img":"img/L3/walk/p004_23_03.jpg","say":"왼쪽 사진: 구멍이 뚫린 CH-스터드 실물이에요."},{"b":[0.415,0.36,0.18,0.36],"c":[0.403,0.342,0.204,0.396],"r":0.9158,"img":"img/L3/walk/p004_23_04.jpg","say":"가운데 사진: CH-스터드가 J 런너 안에 서 있는 모습이에요."},{"b":[0.6,0.2,0.21,0.5],"c":[0.588,0.175,0.234,0.55],"r":0.7564,"img":"img/L3/walk/p004_23_05.jpg","say":"가운데 그림: CH-스터드 홈에 석고보드를 옆으로 끼워 넣은 단면이에요."},{"b":[0.81,0.18,0.18,0.37],"c":[0.796,0.1615,0.204,0.407],"r":0.8911,"img":"img/L3/walk/p004_23_06.jpg","say":"오른쪽 상세: 홈 깊이 35, 폭 A. 양쪽에 석고보드가 물려 있어요."}]}},{"p":5,"title":"CH-스터드 시공 여섯 장면","terms":["CH-Stud","J Runner","Gypsum Board","INSULATION","먹매김"],"pass1":[{"kind":"say","lines":["이 쪽은 글이 없고 **CH-스터드(CH-Stud)** 시공 사진 여섯 장이에요.","선 긋고, 첫 스터드 세우고, 보드 끼우고, 스터드 끼우고, 솜 넣고, 보드 붙이기예요.","한쪽에서만 작업하니까 보드를 옆으로 끼워 넣는다는 점만 기억하면 돼요."]}],"pass2":[{"kind":"steps","head":"**CH-스터드(CH-Stud)** 시공 여섯 단계 (슬라이드 사진 순서)","steps":["1. **먹매김** 및 러너시공","2. 시작 CH 스터드 시공","3. 25mm 방화석고보드 끼우기","4. CH 스터드 끼우기","5. **단열재(INSULATION)** 시공(필요시)","6. **석고보드(Gypsum Board)** 시공"],"answer":"보드를 먼저 끼우고 그다음 스터드를 끼우는 것이 보통 벽과 다른 점이에요."},{"kind":"points","head":"사진에서 봐야 할 것","items":["3번과 4번이 번갈아 반복돼요. 보드, 스터드, 보드, 스터드로 옆으로 이어 나가요.","**J 런너(J Runner)**가 바닥에 깔려 있어서 보드와 스터드를 함께 잡아 줘요.","오른쪽 아이소메트릭 그림에 CH-STUD와 J-RUNNER 이름표가 붙어 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**CH-스터드(CH-Stud)** 시공에서 3번 단계는?","choices":["단열재 시공","25mm 방화석고보드 끼우기","상부 런너 고정","조인트 처리"],"a":1,"why":"먹매김과 러너 → 시작 CH 스터드 → 25mm 방화석고보드 끼우기 → CH 스터드 끼우기 순서예요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1796,0.1898],"c":[0,0.0208,0.2036,0.2218],"r":1.6319,"img":"img/L3/walk/p005_h.jpg"},"parts":[{"b":[0.039,0.265,0.18,0.3],"c":[0.027,0.249,0.204,0.332],"r":1.0924,"img":"img/L3/walk/p005_22_01.jpg","say":"1번: 먹매김 및 러너시공. 바닥에 먹선을 놓고 런너를 깔아요."},{"b":[0.243,0.265,0.18,0.3],"c":[0.231,0.249,0.204,0.332],"r":1.0924,"img":"img/L3/walk/p005_22_02.jpg","say":"2번: 시작 CH 스터드 시공. 벽에 붙는 첫 스터드를 세워요."},{"b":[0.443,0.265,0.19,0.3],"c":[0.431,0.249,0.214,0.332],"r":1.1459,"img":"img/L3/walk/p005_22_03.jpg","say":"3번: 25mm 방화석고보드 끼우기. 보드를 옆으로 밀어 넣어요."},{"b":[0.043,0.608,0.18,0.3],"c":[0.031,0.592,0.204,0.332],"r":1.0924,"img":"img/L3/walk/p005_22_04.jpg","say":"4번: CH 스터드 끼우기. 끼운 보드 옆에 다음 스터드를 끼워요."},{"b":[0.239,0.608,0.18,0.3],"c":[0.227,0.592,0.204,0.332],"r":1.0924,"img":"img/L3/walk/p005_22_05.jpg","say":"5번: 단열재 시공(필요시)."},{"b":[0.439,0.608,0.19,0.3],"c":[0.427,0.592,0.214,0.332],"r":1.1459,"img":"img/L3/walk/p005_22_06.jpg","say":"6번: 석고보드 시공. 마지막에 바깥 면을 덮어요."}]}},{"p":6,"title":"메탈 스터드의 종류 3: E-스터드","terms":["E-Stud","CH-Stud","J Runner","Corner Bead","Gypsum Board"],"pass1":[{"kind":"say","lines":["**E-스터드(E-Stud)**는 벽이 끝나거나 다른 벽과 만나는 자리에 쓰는 마무리용 스터드예요.","공책 옆에 덧대는 책갈피처럼, 벽의 끝을 깔끔하게 닫아 주는 역할이에요."]}],"pass2":[{"kind":"points","head":"**E-스터드(E-Stud)**를 쓰는 세 자리","items":["주로 외벽과의 접합부위에 사용돼요.","**CH-스터드(CH-Stud)**의 마무리용 스터드로 사용돼요.","칸막이 벽의 2중 스터드로 사용돼요."]},{"kind":"points","head":"정체와 자리","items":["단면이 알파벳 E를 눕힌 것처럼 홈이 하나 있는 얇은 부재예요.","혼자 벽을 지탱하는 것이 아니라, 끝부분에서 **석고보드(Gypsum Board)**를 물어 주는 역할이에요.","슬라이드 오른쪽 아래 그림에서는 외부모서리, 내부모서리, 벽 접합부위에 **E-스터드(E-Stud)** 또는 **J 런너(J Runner)**를 쓰라고 표시돼 있어요.","같은 그림에 외부모서리는 **코너 비드(Corner Bead)**라고도 적혀 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"주로 외벽과의 접합부위에 사용하고 **CH-스터드(CH-Stud)**의 마무리용으로 쓰는 스터드는?","choices":["**J 런너(J Runner)**","**C-스터드(C-Stud)**","**E-스터드(E-Stud)**","**스틸런너(Steel Runner)**"],"a":2,"why":"**E-스터드(E-Stud)**는 칸막이 벽의 2중 스터드로도 사용돼요."},{"kind":"english","head":"단답 답안: E-스터드의 용도 세 가지","en":"E-스터드는 외벽과의 접합부위, CH-스터드의 마무리용, 칸막이 벽의 2중 스터드로 사용된다.","ko":"외벽, 마무리, 2중. 세 칸으로 외워요.","tip":"E를 끝(End)으로 연결해서 끝나는 자리라고 외우면 쉬워요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1584,0.1312],"c":[0,0.0208,0.2,0.1632],"r":2.1786,"img":"img/L3/walk/p006_h.jpg"},"parts":[{"b":[0.03,0.23,0.4,0.12],"c":[0.01,0.214,0.44,0.152],"r":5.1462,"img":"img/L3/walk/p006_22_01.jpg","say":"본문 세 줄: 외벽 접합부, CH-스터드 마무리용, 칸막이 벽 2중 스터드."},{"b":[0.09,0.37,0.31,0.36],"c":[0.0745,0.352,0.341,0.396],"r":1.5309,"img":"img/L3/walk/p006_22_02.jpg","say":"왼쪽 사진: E-스터드 실물. 가운데가 한 번 접혀 있어요."},{"b":[0.6,0.17,0.31,0.36],"c":[0.5845,0.152,0.341,0.396],"r":1.5309,"img":"img/L3/walk/p006_22_03.jpg","say":"오른쪽 위 단면: 벽(WALL)에 붙인 E-스터드 높이가 19로 표시돼 있어요."},{"b":[0.03,0.745,0.53,0.19],"c":[0.0035,0.729,0.583,0.222],"r":4.6687,"img":"img/L3/walk/p006_22_04.jpg","say":"아래 표: E-STUD 규격. 높이 19, 25.4, 두께 0.8(0.5, 1.0), 주문생산."},{"b":[0.57,0.66,0.41,0.28],"c":[0.549,0.644,0.451,0.312],"r":2.5698,"img":"img/L3/walk/p006_22_05.jpg","say":"오른쪽 아래: 외부모서리, 내부모서리, 벽 접합부위 세 가지 파티션 설치 그림이에요."}]}},{"p":7,"title":"메탈 스터드의 종류 4: 스틸런너","terms":["Steel Runner","Metal Stud","C-Stud","Gypsum Board"],"pass1":[{"kind":"say","lines":["**스틸런너(Steel Runner)**는 바닥과 천장에 눕혀 고정하는 레일이에요.","세로 기둥인 스터드가 넘어지지 않게 위아래에서 잡아 줘요.","책장으로 치면 위판과 아래판 자리예요."]},{"kind":"analogy","head":"커튼 레일","scene":"커튼 레일을 천장에 붙이고 그 안에 고리를 끼우듯, 런너를 붙이고 그 안에 스터드를 끼워요.","map":[["레일","**스틸런너(Steel Runner)**"],["레일에 끼우는 고리","**C-스터드(C-Stud)**"],["커튼 천","**석고보드(Gypsum Board)**"]]}],"pass2":[{"kind":"points","head":"**스틸런너(Steel Runner)**의 정체와 자리","items":["용융 강판을 기본소재로 하고 있어요.","천장(위)과 바닥(아래)면에 고정하여 스터드를 고정하는 역할을 해요.","단면은 U자처럼 생겨서 그 안에 **메탈 스터드(Metal Stud)**가 쏙 들어가요.","공사 순서로는 먹선을 놓은 바로 다음, 스터드를 세우기 바로 전에 설치해요."]},{"kind":"compare","head":"슬라이드 규격표","cols":["항목","표에 적힌 값"],"rows":[["품명","Runner (K.S품)"],["두께 THK","0.8 (괄호로 1.0)"],["폭 A","50, 65, 75, 90, 100"],["다리 B","40"],["길이 C","3000 또는 주문생산"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**스틸런너(Steel Runner)**의 기본 소재는?","choices":["용융 강판","내연 강판","알루미늄 압출재","합판"],"a":0,"why":"**C-스터드(C-Stud)**는 내연 강판, **스틸런너(Steel Runner)**는 용융 강판이라고 적혀 있어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["소재 짝: **C-스터드(C-Stud)**는 내연 강판, **스틸런너(Steel Runner)**는 용융 강판이에요.","런너는 눕고 스터드는 서요. 방향을 바꿔 쓰면 틀려요."]}],"walk":{"head":null,"parts":[{"b":[0.03,0.235,0.38,0.08],"c":[0.011,0.219,0.418,0.112],"r":6.6349,"img":"img/L3/walk/p007_22_01.jpg","say":"본문 두 줄: 용융 강판 소재, 천장과 바닥면에 고정해 스터드를 고정."},{"b":[0.07,0.4,0.44,0.29],"c":[0.048,0.384,0.484,0.322],"r":2.6722,"img":"img/L3/walk/p007_22_02.jpg","say":"왼쪽 사진: U자로 열린 런너 실물. 스터드보다 다리가 짧아요."},{"b":[0.63,0.03,0.26,0.33],"c":[0.617,0.0135,0.286,0.363],"r":1.4007,"img":"img/L3/walk/p007_22_03.jpg","say":"오른쪽 위 단면: 바닥(FL)에 런너를 못으로 박고 그 안에 스터드가 서 있어요."},{"b":[0.045,0.73,0.6,0.2],"c":[0.015,0.714,0.66,0.232],"r":5.0575,"img":"img/L3/walk/p007_22_04.jpg","say":"아래 표: Runner(K.S품) 폭 50, 65, 100이 표시. 길이 3000 또는 주문생산."},{"b":[0.68,0.4,0.28,0.55],"c":[0.666,0.3725,0.308,0.605],"r":0.9051,"img":"img/L3/walk/p007_22_05.jpg","say":"오른쪽 아래: METAL-RUNNER와 METAL-STUD가 어떻게 맞물리는지 보여 주는 그림이에요."}]}},{"p":8,"title":"메탈 스터드의 종류 5: J 런너","terms":["J Runner","CH-Stud","Steel Runner","Gypsum Board"],"pass1":[{"kind":"say","lines":["**J 런너(J Runner)**는 한쪽 다리가 더 긴 런너예요. 단면이 알파벳 J처럼 짝짝이예요.","**CH-스터드(CH-Stud)**와 짝으로 다니며, 긴 쪽을 뚫린 공간 쪽으로 돌려 세워요."]}],"pass2":[{"kind":"points","head":"**J 런너(J Runner)**의 정체와 자리","items":["바닥과 천장에 고정하고, 수직으로 세울 스터드를 설치하고 고정할 수 있도록 잡아 줘요.","**CH-스터드(CH-Stud)**와 같이 OPEN공간, 샤프트공간, 엘리베이터 공간 등에 주로 사용해요.","높이가 높은 쪽을 OPEN공간 방향으로 설치해요. 이 한 줄이 시험에 그대로 나와요.","긴 다리가 뚫린 쪽을 막아 줘야 **석고보드(Gypsum Board)**가 밖으로 빠지지 않아요."]},{"kind":"points","head":"슬라이드 그림 속 숫자","items":["오른쪽 시공 그림에 고정못 최대 600mm 간격이라고 적혀 있어요.","바닥 런너도 600mm 간격으로 못을 박는 모습이에요.","아래 규격표의 J-RUNNER는 한쪽 25, 반대쪽 45로 높이가 달라요. 이 차이가 J 모양이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**J 런너(J Runner)** 설치 방법으로 옳은 것은?","choices":["**C-스터드(C-Stud)**와만 함께 쓴다","높이가 높은 쪽을 OPEN공간 방향으로 설치한다","높이가 낮은 쪽을 OPEN공간 방향으로 설치한다","벽 중간 높이에 가로로 끼운다"],"a":1,"why":"**J 런너(J Runner)**는 **CH-스터드(CH-Stud)**와 같이 OPEN공간, 샤프트, 엘리베이터 공간에 써요."},{"kind":"warn","head":"헷갈리는 짝: 스틸런너와 J 런너","items":["**스틸런너(Steel Runner)**는 바닥, 천장에서 스터드를 고정하는 보통 런너예요.","**J 런너(J Runner)**는 **CH-스터드(CH-Stud)**와 짝이고, 높은 쪽을 OPEN공간으로 돌려요.","낮은 쪽을 OPEN공간으로라고 적힌 보기는 함정이에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1584,0.1898],"c":[0,0.0208,0.2,0.2218],"r":1.603,"img":"img/L3/walk/p008_h.jpg"},"parts":[{"b":[0.03,0.23,0.52,0.12],"c":[0.004,0.214,0.572,0.152],"r":6.6901,"img":"img/L3/walk/p008_22_01.jpg","say":"본문 세 줄. 마지막 줄 높이가 높은 쪽을 OPEN공간 방향으로가 핵심이에요."},{"b":[0.07,0.38,0.18,0.36],"c":[0.058,0.362,0.204,0.396],"r":0.9158,"img":"img/L3/walk/p008_22_02.jpg","say":"왼쪽 사진: CH-스터드가 J 런너 안에 꽂혀 있는 모습이에요."},{"b":[0.07,0.76,0.52,0.18],"c":[0.044,0.744,0.572,0.212],"r":4.7966,"img":"img/L3/walk/p008_22_03.jpg","say":"아래 표: J-RUNNER 단면 25와 45. 양쪽 다리 길이가 다른 것이 보여요."},{"b":[0.55,0.28,0.34,0.42],"c":[0.533,0.259,0.374,0.462],"r":1.4392,"img":"img/L3/walk/p008_22_04.jpg","say":"오른쪽 그림: 고정못 최대 600mm 간격, 바닥도 600mm 간격으로 박고 있어요."}]}},{"p":9,"title":"메탈 스터드의 종류 6: 퍼링 채널 시스템","terms":["Furring Channel","Gypsum Board","조인트 컴파운드"],"pass1":[{"kind":"say","lines":["**퍼링 채널(Furring Channel)**은 모자처럼 생긴 납작한 채널이에요.","콘크리트 외벽에 **석고보드(Gypsum Board)**를 바로 붙이고 싶을 때 벽에 먼저 붙이는 받침대예요.","스터드로 벽을 새로 세우는 것이 아니라, 있는 벽에 덧대는 방식이에요."]},{"kind":"analogy","head":"액자 걸이 레일","scene":"벽에 얇은 레일을 먼저 붙이고 그 위에 판을 대는 모습이에요. 벽과 판 사이에 얇은 공간이 생겨요.","map":[["벽에 붙이는 레일","**퍼링 채널(Furring Channel)**"],["레일 위에 대는 판","방수 처리된 **석고보드(Gypsum Board)**"]]}],"pass2":[{"kind":"points","head":"**퍼링 채널(Furring Channel)**의 정체와 자리","items":["주로 외벽에 바로 석고보드를 설치할 때 사용해요.","모자 형태로, 외벽이나 천장에 설치한 후 석고보드를 대고 나사못으로 부착하도록 설계됐어요.","외벽 내부 마감에 사용할 때는 외벽 안쪽 면에 610mm 간격으로 수직으로 설치해요.","그다음 방수 처리된 **석고보드(Gypsum Board)**로 마감해요."]},{"kind":"points","head":"슬라이드 그림 속 숫자","items":["610: 퍼링 채널을 세우는 간격이에요. 이 숫자는 뒤에 나오는 T-Bar 간격과 같아요.","400: 그림에서 벽 아래쪽 채널 고정 간격으로 표시된 값이에요.","오른쪽 아래 단면 치수는 폭 70, 윗면 35, 높이 22, 날개 12로 적혀 있어요.","가운데 그림에는 보드 이음매를 **조인트 컴파운드**로 메운다고 표시돼 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"문제은행 l23","q":"외벽에 바로 석고보드를 설치할 때 610mm 간격으로 수직 설치하는 모자 형태의 부재는?","qko":"콘크리트 외벽에 보드를 바로 붙일 때 쓰는 납작한 채널 이름을 묻는 문제예요.","solve":["보기에 퍼링, 보강, 마이너, 캐링 채널이 나란히 나와요.","610mm와 모자 형태가 나오면 **퍼링 채널(Furring Channel)**이에요.","설치 후에는 방수 처리된 **석고보드(Gypsum Board)**로 마감해요."],"answer":"퍼링 채널 (Furring Channel), 간격 610mm"},{"kind":"warn","head":"610이라는 숫자 조심","items":["610mm는 **퍼링 채널(Furring Channel)** 간격이면서 뒤에 배울 일반 T-Bar 간격과 같아요.","스터드 간격 450mm, 캐링 채널 900mm와 섞이지 않게 따로 외워요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.2997,0.1898],"c":[0,0.0208,0.3297,0.2218],"r":2.6426,"img":"img/L3/walk/p009_h.jpg"},"parts":[{"b":[0.03,0.23,0.65,0.13],"c":[0,0.214,0.715,0.162],"r":7.8464,"img":"img/L3/walk/p009_22_01.jpg","say":"본문 세 줄. 셋째 줄의 610mm 간격, 방수 처리된 석고보드가 핵심이에요."},{"b":[0.05,0.41,0.28,0.44],"c":[0.036,0.388,0.308,0.484],"r":1.1313,"img":"img/L3/walk/p009_22_02.jpg","say":"왼쪽 그림: 외벽 안쪽에 퍼링 채널을 610 간격으로 세운 모습이에요."},{"b":[0.35,0.51,0.27,0.24],"c":[0.3365,0.494,0.297,0.272],"r":1.9412,"img":"img/L3/walk/p009_22_03.jpg","say":"가운데 단면: 채널 위에 PLASTER BOARD를 대고 JOINT COMPOUND로 메워요."},{"b":[0.64,0.42,0.33,0.18],"c":[0.6235,0.404,0.363,0.212],"r":3.044,"img":"img/L3/walk/p009_22_04.jpg","say":"오른쪽 사진: 모자(햇) 모양 단면이 그대로 보이는 실물이에요."},{"b":[0.645,0.69,0.16,0.19],"c":[0.625,0.674,0.2,0.222],"r":1.6016,"img":"img/L3/walk/p009_22_05.jpg","say":"오른쪽 아래 치수: 폭 70, 윗면 35, 높이 22, 날개 12."}]}},{"p":10,"title":"기타 보강재 1: 보강 채널","terms":["Brace Channel","Metal Stud","C-Stud"],"pass1":[{"kind":"say","lines":["**보강 채널(Brace Channel)**은 세로로 선 스터드들을 가로로 꿰어 묶는 막대예요.","높은 벽일수록 스터드가 흔들리니까, 가로로 한 줄 꿰어 흔들림을 잡아 줘요.","사다리의 가로 발판을 떠올리면 돼요."]}],"pass2":[{"kind":"points","head":"**보강 채널(Brace Channel)**의 정체와 자리","items":["**메탈 스터드(Metal Stud)**가 설치되는 장소가 높을 때 스터드의 흔들림을 잡아 주려고 써요.","스터드에 가로로 끼워서 설치해요. 덧대는 것이 아니라 스터드 옆구리 홈을 통과시켜요.","**C-스터드(C-Stud)**를 다 세운 다음, 보드를 붙이기 전에 끼워요.","슬라이드 오른쪽 그림에 스터드의 홈 높이가 같아야 보강 채널을 끼울 수 있다고 적혀 있어요."]},{"kind":"compare","head":"슬라이드 규격표","cols":["항목","표에 적힌 값"],"rows":[["품명","보강찬넬 (K.S품)"],["두께 THK","1.2 (괄호로 1.0)"],["폭 A","19, 25"],["다리 B","10"],["길이 C","4000 또는 주문생산"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**보강 채널(Brace Channel)**의 설치 방법은?","choices":["스터드에 세로로 덧댄다","스터드에 가로로 끼워서 설치한다","바닥에 눕혀 고정한다","천장에 매단다"],"a":1,"why":"가로로 끼워서 설치해요. 세로로 덧댄다는 보기는 O/X 함정으로 자주 나와요."},{"kind":"warn","head":"같이 외울 숫자","items":["스터드 설치 높이가 4m 이상이면 1,800mm 간격으로 보강해요(16쪽).","보강은 **보강 채널(Brace Channel)**로 하고, 문과 창 자리 보강은 **스터드 2겹치기**예요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.2105,0.2365],"c":[0,0.0208,0.2345,0.2685],"r":1.5527,"img":"img/L3/walk/p010_h.jpg"},"parts":[{"b":[0.03,0.28,0.66,0.05],"c":[0,0.2317,0.726,0.1467],"r":8.798,"img":"img/L3/walk/p010_22_01.jpg","say":"본문 한 줄: 높은 곳에서 스터드의 흔들림을 잡아 주고, 가로로 끼워서 설치해요."},{"b":[0.035,0.33,0.19,0.47],"c":[0.023,0.3065,0.214,0.517],"r":0.7359,"img":"img/L3/walk/p010_22_02.jpg","say":"왼쪽 그림: 캐링채널과 마이너채널 이름표가 붙어 있어요. 천장에서도 같은 모양을 써요."},{"b":[0.25,0.39,0.16,0.39],"c":[0.23,0.3705,0.2,0.429],"r":0.8288,"img":"img/L3/walk/p010_22_03.jpg","say":"가운데 사진: 스터드 옆구리 홈에 채널이 꽂힌 실물이에요."},{"b":[0.46,0.35,0.17,0.46],"c":[0.445,0.327,0.2,0.506],"r":0.7027,"img":"img/L3/walk/p010_22_04.jpg","say":"오른쪽 O와 X 그림: 스터드 홈 높이가 같아야 끼울 수 있다는 설명이에요."},{"b":[0.035,0.82,0.6,0.09],"c":[0.005,0.7983,0.66,0.1333],"r":8.8022,"img":"img/L3/walk/p010_22_05.jpg","say":"아래 표: 보강찬넬 폭 19, 25, 두께 1.2, 길이 4000 또는 주문생산."}]}},{"p":11,"title":"기타 보강재 2: 메탈 트림과 케이싱 비드","terms":["Metal Trim","Casing Bead","Gypsum Board","조인트 컴파운드"],"pass1":[{"kind":"say","lines":["**메탈 트림(Metal Trim)**과 **케이싱 비드(Casing Bead)**는 보드 끝을 감싸는 테두리예요.","종이 모서리에 끼우는 클립처럼, 잘린 보드 끝이 깨지지 않게 보호해요.","둘의 차이는 딱 하나, 끼우기만 하느냐 끼우고 고정까지 하느냐예요."]},{"kind":"compare","head":"한 줄 구별","cols":["부재","붙이는 방법"],"rows":[["**케이싱 비드(Casing Bead)**","단순히 삽입만 해요"],["**메탈 트림(Metal Trim)**","삽입한 뒤 나사못으로 고정하고 메워서 마감해요"]]}],"pass2":[{"kind":"points","head":"둘이 함께 쓰이는 자리","items":["창호와 문설주 부위","천장 모서리 부위","**석고보드(Gypsum Board)**가 다른 벽체와 접하는 부위","공통 목적은 석고보드의 끝단 부분을 보호하는 것이에요."]},{"kind":"points","head":"차이를 정확히","items":["**케이싱 비드(Casing Bead)**는 단순히 삽입하여 사용해요.","**메탈 트림(Metal Trim)**은 삽입 후 나사못으로 고정한 후 **조인트 컴파운드**로 메우고 마감해요.","그래서 **메탈 트림(Metal Trim)** 쪽이 손이 한 번 더 가고 더 단단해요."]},{"kind":"points","head":"슬라이드 그림 속 치수","items":["메탈 트림: 두께 0.5t, 높이 12, 길이 방향 27, 내측 12.5/15.5.","케이싱 비드: 두께 0.5t, 높이 12, 폭 25, 내측 9.5/12.5/15.5/19.","내측 치수가 보드 두께에 맞춰 여러 가지로 나온다는 뜻이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"석고보드 끝단 보호재 중 삽입 후 나사못으로 고정하고 **조인트 컴파운드**로 메워 마감하는 것은?","choices":["**보강 채널(Brace Channel)**","**메탈 트림(Metal Trim)**","**케이싱 비드(Casing Bead)**","**코너 비드(Corner Bead)**"],"a":1,"why":"**케이싱 비드(Casing Bead)**는 단순히 삽입하여 사용해요."},{"kind":"warn","head":"슬라이드 오타 주의","items":["슬라이드 제목에 메탈 트림 (Matal Trim) 이라고 적혀 있어요. 바른 철자는 Metal Trim 이에요.","본문에서도 캐싱비드라고 붙여 쓴 곳이 있는데, 바른 표기는 케이싱 비드예요.","시험에는 슬라이드대로 나올 수 있으니 표기는 그대로 두고, 뜻만 정확히 알아 두세요."]},{"kind":"english","head":"단답 답안: 케이싱 비드와 메탈 트림의 차이","en":"케이싱 비드는 단순히 삽입하여 사용하고, 메탈 트림은 삽입 후 나사못으로 고정한 다음 조인트 컴파운드로 메우고 마감한다.","ko":"끼우기만 vs 끼우고 고정하고 메우기.","tip":"메탈 트림의 트림(trim)은 다듬는다는 뜻이라 손이 더 간다고 외워요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1584,0.1898],"c":[0,0.0208,0.2,0.2218],"r":1.603,"img":"img/L3/walk/p011_h.jpg"},"parts":[{"b":[0.035,0.23,0.36,0.045],"c":[0.017,0.1975,0.396,0.11],"r":6.4,"img":"img/L3/walk/p011_23_01.jpg","say":"제목 줄: (2) 메탈 트림 (Matal Trim) & 케이싱 비드(Casing Bead)."},{"b":[0.03,0.275,0.67,0.09],"c":[0,0.2456,0.737,0.1489],"r":8.7993,"img":"img/L3/walk/p011_23_02.jpg","say":"본문 두 줄: 쓰는 자리와, 끼우기만 하느냐 고정하느냐의 차이예요."},{"b":[0.06,0.39,0.32,0.25],"c":[0.044,0.374,0.352,0.282],"r":2.2191,"img":"img/L3/walk/p011_23_03.jpg","say":"위 그림 [메탈 트림]: 0.5t, 12, 27, 내측 12.5/15.5가 적혀 있어요."},{"b":[0.06,0.66,0.32,0.26],"c":[0.044,0.644,0.352,0.292],"r":2.1431,"img":"img/L3/walk/p011_23_04.jpg","say":"아래 그림 [케이싱 비드]: 0.5t, 12, 25, 내측 9.5/12.5/15.5/19."},{"b":[0.68,0.54,0.19,0.37],"c":[0.668,0.5215,0.214,0.407],"r":0.9348,"img":"img/L3/walk/p011_23_05.jpg","say":"오른쪽 사진: 석고보드 끝단에 끼운 실물 모습이에요."}]}},{"p":12,"title":"기타 보강재 3: 코너 비드","terms":["Corner Bead","Gypsum Board","조인트 컴파운드"],"pass1":[{"kind":"say","lines":["**코너 비드(Corner Bead)**는 벽이 직각으로 꺾이는 모서리에 씌우는 각진 테두리예요.","책상 모서리에 끼우는 보호대와 똑같은 생각이에요.","모서리는 부딪히기 쉬워서 **석고보드(Gypsum Board)**만 있으면 금방 깨져요."]}],"pass2":[{"kind":"points","head":"**코너 비드(Corner Bead)**의 정체와 자리","items":["석고보드로 벽체를 시공할 경우 벽체가 직각으로 꺾어지는 부분의 코너 파손을 막아 주는 제품이에요.","**조인트 컴파운드** 처리를 한 후 도장이나 도배 등의 마감재로 마감을 해요.","공사 순서로는 보드를 다 붙인 다음, 퍼티와 도장 앞에 오는 작업이에요.","슬라이드에는 그물(라스) 모양 제품과 종이가 붙은 제품 사진이 함께 나와요."]},{"kind":"steps","head":"오른쪽 아래 시공 네 장면","steps":["1. 코너에 본드를 일정한 두께로 바른다","2. 코너비드를 붙여 눌러 준다","3. 수평대를 이용하여 수평과 수직을 조절한다","4. 석고보드를 붙여 나간다"],"answer":"본드, 붙이기, 수평 잡기, 보드 순서예요."},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"벽체가 직각으로 꺾어지는 부분의 코너 파손을 막아 주는 제품은?","choices":["**케이싱 비드(Casing Bead)**","**코너 비드(Corner Bead)**","**메탈 트림(Metal Trim)**","**보강 채널(Brace Channel)**"],"a":1,"why":"**코너 비드(Corner Bead)**는 컴파운드 처리 후 도장이나 도배로 마감해요."},{"kind":"warn","head":"세 형제 구별","items":["**케이싱 비드(Casing Bead)**는 끼우기만, 끝단 보호.","**메탈 트림(Metal Trim)**은 끼우고 나사 고정하고 메우기, 끝단 보호.","**코너 비드(Corner Bead)**는 직각 모서리 보호. 자리가 다르다는 점이 핵심이에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1584,0.1412],"c":[0,0.0208,0.2,0.1732],"r":2.0529,"img":"img/L3/walk/p012_h.jpg"},"parts":[{"b":[0.03,0.275,0.56,0.09],"c":[0.002,0.2578,0.616,0.1245],"r":8.7961,"img":"img/L3/walk/p012_22_01.jpg","say":"본문 두 줄: 직각으로 꺾어지는 부분의 코너 파손을 막고, 컴파운드 후 도장이나 도배."},{"b":[0.04,0.38,0.18,0.22],"c":[0.028,0.364,0.204,0.252],"r":1.4392,"img":"img/L3/walk/p012_22_02.jpg","say":"왼쪽 위 사진: 그물(라스)이 달린 코너 비드예요. 미장에 물려요."},{"b":[0.04,0.645,0.38,0.3],"c":[0.021,0.629,0.418,0.332],"r":2.2383,"img":"img/L3/walk/p012_22_03.jpg","say":"왼쪽 아래 그림: 모서리 단면과 마감 바름 기준선을 보여 줘요."},{"b":[0.62,0.18,0.33,0.32],"c":[0.6035,0.164,0.363,0.352],"r":1.8333,"img":"img/L3/walk/p012_22_04.jpg","say":"오른쪽 위: 스터드용 인아웃 코너비드, 집본드용 인코너비드, 아웃코너비드."},{"b":[0.585,0.52,0.36,0.42],"c":[0.567,0.499,0.396,0.462],"r":1.5238,"img":"img/L3/walk/p012_22_05.jpg","say":"오른쪽 아래: 본드 바르기, 붙여 누르기, 수평 잡기, 보드 붙이기 네 장면."}]}},{"p":13,"title":"코너 비드 실물과 컴파운드 마감","terms":["Corner Bead","조인트 컴파운드","Gypsum Board"],"pass1":[{"kind":"say","lines":["앞 쪽과 같은 설명에 **코너 비드(Corner Bead)** 실물 사진이 붙은 쪽이에요.","슬라이드 아래에 최근에는 매우 얇은 형태의 제품이 나오고 있다는 메모가 있어요."]}],"pass2":[{"kind":"points","head":"사진에서 봐야 할 것","items":["왼쪽 두 장: 얇은 금속을 직각으로 접은 **코너 비드(Corner Bead)** 실물이에요. 구멍이 뚫려 있어요.","구멍은 **조인트 컴파운드**가 물려서 잘 떨어지지 않게 하는 구멍이에요.","오른쪽 사진: 모서리에 코너 비드를 붙이고 헤라로 컴파운드를 발라 메우는 장면이에요.","컴파운드가 마르면 **석고보드(Gypsum Board)** 면과 모서리가 하나처럼 평평해져요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**코너 비드(Corner Bead)** 시공 후 이어지는 작업 순서로 옳은 것은?","choices":["컴파운드 처리 후 도장이나 도배","도장 후 컴파운드 처리","단열재 충진 후 컴파운드","코너 비드 위에 바로 벽지"],"a":0,"why":"**조인트 컴파운드** 처리를 한 후 도장이나 도배 등의 마감재로 마감해요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1941,0.2362],"c":[0,0.0208,0.2181,0.2682],"r":1.4457,"img":"img/L3/walk/p013_h.jpg"},"parts":[{"b":[0.03,0.275,0.56,0.09],"c":[0.002,0.2578,0.616,0.1245],"r":8.7961,"img":"img/L3/walk/p013_21_01.jpg","say":"본문 두 줄은 앞 쪽과 같은 정의예요."},{"b":[0.095,0.455,0.275,0.34],"c":[0.0812,0.438,0.3025,0.374],"r":1.4379,"img":"img/L3/walk/p013_21_02.jpg","say":"왼쪽 사진: 직각으로 접힌 얇은 코너 비드."},{"b":[0.383,0.455,0.235,0.34],"c":[0.371,0.438,0.259,0.374],"r":1.2311,"img":"img/L3/walk/p013_21_03.jpg","say":"가운데 사진: 옆에서 본 모습. 날개에 구멍이 뚫려 있어요."},{"b":[0.26,0.815,0.23,0.045],"c":[0.248,0.7825,0.254,0.11],"r":4.1051,"img":"img/L3/walk/p013_21_04.jpg","say":"캡션: 최근에는 매우 얇은 형태의 제품이 나오고 있다."},{"b":[0.637,0.37,0.23,0.53],"c":[0.625,0.3435,0.254,0.583],"r":0.7745,"img":"img/L3/walk/p013_21_05.jpg","say":"오른쪽 사진: 붙인 코너 비드 위에 컴파운드를 바르는 실제 작업이에요."}]}},{"p":14,"title":"스터드 벽체 시공: 건식공법과 벽 두께","terms":["건식공법","Dry-Wall","Gypsum Board","Metal Stud","흡음충진재","2ply","아연 도금","Steel Runner"],"pass1":[{"kind":"say","lines":["물과 시멘트로 쌓는 벽은 무겁고 마르는 데 오래 걸려요.","그 단점을 보완한 것이 물을 쓰지 않는 **건식공법**이에요.","**건식벽체(Dry-Wall)**의 기본 구성은 스터드에 솜, 보드, 마감재예요."]},{"kind":"compare","head":"습식과 건식","cols":["구분","특징"],"rows":[["습식","물을 쓴다, 건물이 무거워진다, 공사기간이 길어진다"],["**건식공법**","물을 안 쓴다, 가볍다, 빠르다"]]}],"pass2":[{"kind":"points","head":"**건식공법**과 **건식벽체(Dry-Wall)**의 정의","items":["습식공사로 생기는 건물의 중량화와 공사기간 장기화를 보완하려는 공법이 **건식공법**이에요.","**건식벽체(Dry-Wall)**는 물을 사용하지 않고 벽체를 조성하는 공법이에요.","대표 방법 둘: 스틸계 금속 프레임에 유리와 보드류로 마감하는 방법, 스터드 구조에 **석고보드(Gypsum Board)**와 합판을 쓰는 벽체시공.","기본 구성은 스터드 + **흡음충진재** + 석고보드 + 마감재예요.","방음 성능을 높이려고 차음재와 공기층을 두기도 해요."]},{"kind":"points","head":"스터드 벽체 공사의 일반적인 고려사항 다섯 가지","items":["**스틸런너(Steel Runner)**와 스터드는 KS 기준에 맞는 **아연 도금** 강제 제품을 쓰고, 규격과 두께는 설계도서와 요구 성능에 따라 정해요.","**석고보드(Gypsum Board)**는 KS 기준에 맞는 제품을 쓰고, 내화, 차음, 내습 등 요구 성능에 맞는 종류를 골라요.","보드의 두께와 겹수는 벽체 용도와 요구 성능에 따라 정해요. 일반적으로 9.5mm나 12.5mm를 2겹으로 시공해요.","보드는 수직, 수평, 평활도를 확보해 시공하고 이음부에 단차나 돌출이 없게 해요.","벽걸이 TV, 상부장, 선반 등 중량물이 설치되는 위치는 스터드나 합판, 철판으로 사전에 보강해요."]},{"kind":"steps","head":"벽 두께 계산 (오른쪽 그림)","steps":["한쪽 **석고보드(Gypsum Board)** **2ply** + **메탈 스터드(Metal Stud)** + 반대쪽 보드 **2ply**를 더해요.","9.5mm 보드: 9.5 + 9.5 + 65 + 9.5 + 9.5 = 103mm","12.5mm 보드: 12.5 + 12.5 + 65 + 12.5 + 12.5 = 115mm","가운데 65는 스터드 폭이에요. 보드는 양면에 두 겹씩 모두 네 겹이에요."],"answer":"9.5mm면 103mm, 12.5mm면 115mm"},{"kind":"points","head":"석고보드 부착 시 주의사항 다섯 가지","items":["설치 위치의 치수에 맞게 재단해야 해요.","이음이 무리하게 밀착되지 않도록 부착해요.","시공 방향이 일정하게 시공되도록 해요.","보드의 가장자리는 반드시 스터드와 연결 고정되어야 해요.","절단해 시공할 경우 절단면을 깨끗이 손질한 후 시공해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"문제은행 l23","q":"석고보드 9.5mm를 스터드 65mm 양면에 2겹씩 붙인 벽의 두께는?","qko":"9.5mm 보드를 양쪽에 두 겹씩 붙였을 때 벽이 몇 mm가 되는지 묻는 계산 문제예요.","solve":["보드는 양면에 2겹씩이므로 모두 네 겹이에요.","9.5 x 4 = 38mm","가운데 스터드 65mm를 더해요. 38 + 65 = 103mm"],"answer":"103mm"},{"kind":"check","q":"석고보드 12.5mm를 스터드 65mm 양면에 **2ply**씩 붙인 벽의 두께는?","choices":["90mm","103mm","125mm","115mm"],"a":3,"why":"12.5 x 4 = 50, 50 + 65 = 115mm예요."},{"kind":"check","q":"**건식벽체(Dry-Wall)**의 기본 구성으로 옳은 것은?","choices":["스터드 + **흡음충진재** + **석고보드(Gypsum Board)** + 마감재","조적 + 미장 + 도장","스터드 + 콘크리트 + 타일","합판 + 시멘트 + 벽지"],"a":0,"why":"방음 성능을 높일 때 차음재와 공기층을 더 두기도 해요."},{"kind":"warn","head":"시험에서 잘 걸리는 함정","items":["**건식공법**은 습식의 중량화와 공기 장기화를 보완하는 공법이에요. 반대로 쓰면 틀려요.","중량물 자리는 미리 스터드나 합판, 철판으로 보강해요. 나중에 보드에 못을 박으면 빠져요.","103mm와 115mm를 바꿔 쓰지 마세요. 9.5는 103, 12.5는 115예요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1477,0.1453],"c":[0,0.0208,0.2,0.1773],"r":2.0054,"img":"img/L3/walk/p014_h.jpg"},"parts":[{"b":[0.03,0.185,0.9,0.12],"c":[0,0.145,0.99,0.2],"r":8.8,"img":"img/L3/walk/p014_24_01.jpg","say":"위 본문 세 줄: 건식공법의 이유, 건식벽체의 정의, 기본 구성."},{"b":[0.036,0.33,0.67,0.3],"c":[0.0025,0.314,0.737,0.332],"r":3.9465,"img":"img/L3/walk/p014_24_02.jpg","say":"위 박스: 스터드 벽체 공사의 일반적인 고려사항 다섯 줄이에요."},{"b":[0.036,0.645,0.67,0.29],"c":[0.0025,0.629,0.737,0.322],"r":4.069,"img":"img/L3/walk/p014_24_03.jpg","say":"아래 박스: 석고보드 부착 시 주의사항 다섯 줄이에요."},{"b":[0.755,0.33,0.18,0.38],"c":[0.743,0.311,0.204,0.418],"r":0.8676,"img":"img/L3/walk/p014_24_04.jpg","say":"오른쪽 그림 [벽 두께]: 보드 2겹, 스터드, 보드 2겹 순서가 색으로 구분돼 있어요."},{"b":[0.72,0.72,0.27,0.09],"c":[0.703,0.704,0.297,0.122],"r":4.3279,"img":"img/L3/walk/p014_24_05.jpg","say":"계산식 두 줄: 103mm와 115mm. 시험에 그대로 나와요."}]}},{"p":15,"title":"1ply와 2ply, 석고보드와 스터드 배열","terms":["1ply","2ply","Gypsum Board","C-Stud","Steel Runner","조인트 테이프","조인트 컴파운드"],"pass1":[{"kind":"say","lines":["**석고보드(Gypsum Board)**를 한 겹 붙이면 **1ply**, 두 겹 붙이면 **2ply**예요.","보통은 양쪽에 두 겹씩 붙여요.","두 겹을 붙일 때는 벽돌 쌓듯이 이음매를 엇갈리게 놓는 것이 핵심이에요."]},{"kind":"analogy","head":"벽돌 쌓기","scene":"벽돌을 쌓을 때 위아래 줄눈을 일부러 어긋나게 놓죠. 같은 자리에 줄눈이 겹치면 그 선을 따라 갈라져요.","map":[["아래 줄 벽돌","**1ply** 바탕 **석고보드(Gypsum Board)**"],["위 줄 벽돌","**2ply** 마감 석고보드"],["어긋난 줄눈","엇갈리게 시공한 보드 경계선"]]}],"pass2":[{"kind":"points","head":"용어 먼저","items":["경량벽체틀의 양면에 나사못을 이용하여 **석고보드(Gypsum Board)**를 붙여요.","1겹만 붙이는 경우가 **1ply**예요. 원플라이, 원피라고도 읽어요.","2겹을 붙이는 경우가 **2ply**예요. 투플라이, 투피라고도 읽어요.","**석고보드(Gypsum Board)**는 **1ply**와 **2ply**의 경계선이 엇갈리게 시공해요."]},{"kind":"steps","head":"도면에 내벽 두께를 100mm로 그리는 이유","steps":["석고보드 9.5mm를 4겹 쓰면 9.5 x 4 = 38mm예요.","여기에 **C-스터드(C-Stud)** 65mm를 더해요.","38 + 65 = 103mm가 실제 두께예요.","도면에서는 그리기 쉽게 반올림해 100mm로 그려요."],"answer":"실제 103mm, 도면 표기 100mm"},{"kind":"points","head":"왼쪽 배열 그림의 숫자","items":["**석고보드(Gypsum Board)** 가로 900, 세로 1800 규격이에요.","**C-스터드(C-Stud)** 간격은 450이에요. 900을 반으로 나눈 값이에요.","그래서 보드 한 장 폭 안에 스터드가 세 개(양 끝과 가운데) 걸쳐요.","보드 가장자리가 반드시 스터드 위에 놓여야 하기 때문이에요."]},{"kind":"points","head":"오른쪽 그림의 숫자와 메모","items":["상부런너와 바닥런너는 600mm 간격으로 고정한다고 적혀 있어요.","스터드 간격은 450mm 간격으로 표시돼 있어요.","석고보드 2겹 = **2ply**, 바탕석고보드와 마감 석고보드가 이름표로 구분돼 있어요.","모든 마감면의 이음매는 **조인트 테이프**와 **조인트 컴파운드**로 마감해야 한다고 적혀 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**석고보드(Gypsum Board)**를 2겹 붙이는 경우를 무엇이라 하는가?","choices":["**1ply**","**2ply**","3ply","0ply"],"a":1,"why":"1겹은 **1ply**(원플라이, 원피), 2겹은 **2ply**(투플라이, 투피)예요."},{"kind":"check","q":"**1ply**와 **2ply**의 경계선은 어떻게 시공하는가?","choices":["같은 위치에 정확히 맞춘다","엇갈리게 시공한다","위아래로 겹쳐 붙인다","테이프 없이 벌려 둔다"],"a":1,"why":"같은 자리에 경계선이 겹치면 그 선을 따라 금이 가기 쉬워요."},{"kind":"english","head":"단답 답안: 도면에 내벽을 100mm로 그리는 이유","en":"석고보드 9.5mm 4겹 38mm와 스터드 65mm를 더하면 103mm가 되므로, 도면에서는 이를 반올림해 100mm로 표기한다.","ko":"38 + 65 = 103, 도면은 100.","tip":"9.5 곱하기 4는 38. 38 더하기 65는 103. 숫자 세 개만 외우면 돼요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.18,0.4,0.22],"c":[0.01,0.164,0.44,0.252],"r":3.1041,"img":"img/L3/walk/p015_24_01.jpg","say":"왼쪽 본문: 1ply와 2ply의 뜻, 그리고 도면 100mm의 이유(103mm)."},{"b":[0.04,0.43,0.34,0.52],"c":[0.023,0.404,0.374,0.572],"r":1.1624,"img":"img/L3/walk/p015_24_02.jpg","say":"왼쪽 그림: 보드 가로 900, 세로 1800, 스터드 간격 450."},{"b":[0.585,0.055,0.11,0.065],"c":[0.54,0.0325,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p015_24_03.jpg","say":"오른쪽 위: 상부런너 (600mm 간격으로 고정)."},{"b":[0.59,0.36,0.12,0.055],"c":[0.55,0.3325,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p015_24_04.jpg","say":"가운데 라벨: 450mm 간격. 스터드 사이 거리예요."},{"b":[0.865,0.13,0.13,0.055],"c":[0.8,0.1025,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p015_24_05.jpg","say":"오른쪽 위 라벨: 석고보드 2겹 = 2ply."},{"b":[0.735,0.555,0.16,0.075],"c":[0.715,0.5375,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p015_24_06.jpg","say":"오른쪽 라벨: 석고보드는 1ply와 2ply의 경계선이 엇갈리게 시공!"}]}},{"p":16,"title":"건식벽체 시공 순서 (원문)","terms":["Dry-Wall","먹매김","Steel Runner","C-Stud","CH-Stud","Brace Channel","스터드 2겹치기","Gypsum Board","1ply","2ply","INSULATION","조인트 테이프","조인트 컴파운드"],"pass1":[{"kind":"say","lines":["이 쪽은 **건식벽체(Dry-Wall)** 시공 순서를 글로 풀어 쓴 원문이에요.","뼈대를 먼저 세우고, 한쪽 살을 붙이고, 속을 채우고, 반대쪽 살을 붙여요.","주문으로 외워요. 먹, 아래, 시작, 위, 기둥으로 뼈대. 보드, 솜, 보드, 보드로 살."]},{"kind":"analogy","head":"샌드위치 만들기","scene":"빵 한 장을 깔고 속을 올린 다음 나머지 빵을 덮죠. 한쪽을 먼저 막아야 속을 넣을 수 있어요.","map":[["아래 빵","한쪽 **석고보드(Gypsum Board)**"],["속 재료","**단열재(INSULATION)** 충진"],["위 빵","반대쪽 석고보드"]]}],"pass2":[{"kind":"steps","head":"슬라이드 원문 순서","steps":["설계도서에 따라 메탈 스터드의 설치 부위에 **먹매김**을 해요.","바닥과 천장에 상부, 하부 **스틸런너(Steel Runner)**를 설치하고 견고하게 고정해요.","**C-스터드(C-Stud)** 또는 **CH-스터드(CH-Stud)**를 상하 런너 사이에 300mm~450mm 간격으로 설치하고 수직을 정확히 잡아 고정해요.","바탕보드로 **석고보드(Gypsum Board)** 1겹을 나사못으로 스터드에 부착해요.","한 면 붙이기가 끝나면 스터드 사이사이에 **단열재(INSULATION)**를 충진해요.","나머지 면에 같은 방법으로 석고보드 2겹을 시공하고 이음매를 메워요."],"answer":"뼈대 → 한쪽 살 → 속 → 반대쪽 살 → 이음매 마감"},{"kind":"points","head":"꼭 외울 숫자와 조건","items":["스터드 설치 간격은 300mm~450mm예요.","스터드 설치 높이가 4m 이상이면 1,800mm 간격으로 보강해요(**보강 채널(Brace Channel)**).","도어 또는 창이 설치되는 부분은 **스터드 2겹치기**로 보강해 개폐 충격을 흡수해요.","**조인트 컴파운드**로 이음매를 메우고 24시간 정도 경화시킨 후 후속 작업을 해요."]},{"kind":"points","head":"글에 숨은 주의사항","items":["스터드의 날개 방향은 한쪽 방향으로 동일하게 해요. 오른쪽 그림이 이 이야기예요.","1겹은 바탕보드, 2겹은 치장보드예요. 2겹은 나사못 또는 타카핀을 쓰고 본드를 충분히 도포해요.","벽체에 들어가는 전기, 통신, 방송 케이블 위치를 파악하고 손상되지 않게 해요.","이음매에는 **조인트 테이프**를 부풀음이나 공기층 없이 정밀하게 붙여요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"문제은행 l23","q":"건식벽체 시공 순서로 옳은 것은?","qko":"아홉 단계 중 앞부분 순서를 고르는 문제예요.","solve":["뼈대가 먼저예요. **먹매김** → 하부 런너 → 시작 스터드 → 상부 런너 → 스터드.","그다음이 살이에요. 바탕 보드 → **단열재(INSULATION)** → 반대쪽 바탕 **1ply** → 마감 **2ply**.","보드를 먼저 붙이고 스터드를 세운다는 보기는 전부 오답이에요."],"answer":"먹매김 → 하부 런너 → 시작 스터드 → 상부 런너 → 스터드 → 바탕 보드 → 단열재 → 반대쪽 바탕 1ply → 마감 2ply"},{"kind":"check","q":"스터드 설치 높이가 4m 이상일 때의 조치는?","choices":["900mm 간격으로 보강","1,800mm 간격으로 보강","**스터드 2겹치기**","**퍼링 채널(Furring Channel)**로 교체"],"a":1,"why":"4m 이상이면 1,800mm 간격으로 보강해요. **스터드 2겹치기**는 도어, 창 부위 보강이에요."},{"kind":"check","q":"**조인트 테이프**와 **조인트 컴파운드** 시공 뒤 후속 작업 전 경화 시간은?","choices":["12시간 정도","72시간 정도","24시간 정도","1시간 정도"],"a":2,"why":"24시간 정도 경화시킨 후 후속 작업을 실시해요."},{"kind":"warn","head":"시험에서 잘 걸리는 함정","items":["**단열재(INSULATION)**는 한쪽 보드를 붙인 뒤에 충진해요. 마지막에 넣는다는 보기는 틀려요.","1,800mm는 높이 4m 이상일 때의 보강 간격이에요. 스터드 설치 간격 450mm와 다릅니다.","문과 창 보강은 **스터드 2겹치기**, 높은 벽 보강은 **보강 채널(Brace Channel)**이에요."]},{"kind":"english","head":"서술 답안: 건식벽체 시공 순서 아홉 단계","en":"먹매김, 하부 런너 고정, 시작 스터드 시공, 상부 런너 고정, 스터드 시공, 바탕 석고보드 시공, 단열재 고정, 반대쪽 바탕 석고보드 시공(1ply), 마감 석고보드 시공(2ply) 순서로 한다.","ko":"뼈대 다섯 단계, 살 네 단계로 나눠 적으면 빠짐이 없어요.","tip":"먹, 아래, 시작, 위, 기둥 으로 뼈대. 보드, 솜, 보드, 보드 로 살."}],"walk":{"head":{"b":[0.0092,0.0368,0.8474,0.2201],"c":[0,0.0208,0.9322,0.2521],"r":6.5738,"img":"img/L3/walk/p016_h.jpg"},"parts":[{"b":[0.035,0.265,0.6,0.085],"c":[0.005,0.2408,0.66,0.1333],"r":8.8022,"img":"img/L3/walk/p016_23_01.jpg","say":"1, 2줄: 먹매김을 하고, 바닥과 천장에 상하부 런너를 고정해요."},{"b":[0.035,0.355,0.63,0.09],"c":[0.0035,0.33,0.693,0.14],"r":8.8,"img":"img/L3/walk/p016_23_02.jpg","say":"3줄: C 또는 CH 스터드를 300mm~450mm 간격으로, 날개 방향은 한쪽으로 동일하게."},{"b":[0.035,0.45,0.45,0.045],"c":[0.0125,0.4175,0.495,0.11],"r":8.0,"img":"img/L3/walk/p016_23_03.jpg","say":"4줄: 스터드 설치 높이가 4m 이상이면 1,800mm 간격으로 보강."},{"b":[0.035,0.5,0.66,0.045],"c":[0.002,0.4492,0.726,0.1467],"r":8.798,"img":"img/L3/walk/p016_23_04.jpg","say":"5줄: 도어 또는 창 부분은 스터드 2겹치기로 보강해 개폐 충격을 흡수."},{"b":[0.035,0.548,0.6,0.135],"c":[0.005,0.532,0.66,0.167],"r":7.0259,"img":"img/L3/walk/p016_23_05.jpg","say":"6줄 묶음: 바탕보드 1겹, 2겹은 치장보드, 2겹째는 본드를 충분히 도포."},{"b":[0.035,0.688,0.6,0.215],"c":[0.005,0.672,0.66,0.247],"r":4.7503,"img":"img/L3/walk/p016_23_06.jpg","say":"나머지: 단열재 충진, 케이블, 반대쪽 2겹, 조인트 테이프와 컴파운드 24시간 경화."}]}},{"p":17,"title":"건식벽체 시공 순서 (간략 버전 여섯 장면)","terms":["Dry-Wall","먹매김","Steel Runner","Gypsum Board","INSULATION","조인트 테이프","조인트 컴파운드"],"pass1":[{"kind":"say","lines":["글은 없고 **건식벽체(Dry-Wall)** 시공 사진 여섯 장만 있는 쪽이에요.","선 긋고, 기둥 세우고, 한쪽 덮고, 솜 넣고, 반대쪽 덮고, 이음매 메우기예요.","한쪽을 먼저 막아야 솜을 넣을 수 있다는 순서만 기억하면 돼요."]},{"kind":"analogy","head":"샌드위치","scene":"빵 한 장을 깔고 속을 올린 다음 나머지 빵을 덮듯이, 한쪽 보드를 먼저 붙이고 속을 채워요.","map":[["아래 빵","한쪽 **석고보드(Gypsum Board)**"],["속 재료","**단열재(INSULATION)**"],["위 빵","반대쪽 석고보드"]]}],"pass2":[{"kind":"steps","head":"간략 버전 여섯 단계 (슬라이드 사진 순서)","steps":["1. **먹매김** 및 러너시공","2. 스터드 시공","3. 한쪽 **석고보드(Gypsum Board)** 시공","4. **단열재(INSULATION)** 시공(필요 시)","5. 반대쪽 석고보드 시공","6. 조인트 처리 및 마감"],"answer":"뼈대, 한쪽 살, 속, 반대쪽 살, 이음매 순서예요."},{"kind":"points","head":"각 장면에서 볼 것","items":["1번 사진에서 쓰는 공구는 타정총이에요. 바닥에 **스틸런너(Steel Runner)**를 총으로 박아 고정해요.","4번의 노란 재료가 **단열재(INSULATION)**예요. 스터드 사이를 채워요.","6번은 **조인트 테이프**를 붙이고 **조인트 컴파운드**로 메우는 장면이에요.","다음 쪽(18쪽)부터는 같은 순서를 아홉 단계로 더 잘게 쪼갠 상세 버전이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**건식벽체(Dry-Wall)** 간략 시공 순서에서 **단열재(INSULATION)** 시공은 몇 번째인가?","choices":["두 번째","세 번째","네 번째","여섯 번째"],"a":2,"why":"먹매김과 러너, 스터드, 한쪽 보드 다음 네 번째예요. 반대쪽 보드보다 먼저예요."},{"kind":"warn","head":"간략 버전과 상세 버전","items":["간략 버전은 여섯 단계, 상세 버전은 아홉 단계예요.","상세 버전은 런너를 하부와 상부로 나누고, 시작 스터드를 따로 세며, 보드를 **1ply**와 **2ply**로 나눠요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.2104,0.1898],"c":[0,0.0208,0.2344,0.2218],"r":1.8788,"img":"img/L3/walk/p017_h.jpg"},"parts":[{"b":[0.085,0.265,0.175,0.3],"c":[0.0725,0.249,0.2,0.332],"r":1.071,"img":"img/L3/walk/p017_22_01.jpg","say":"1번: 먹매김 및 러너시공. 바닥 먹선 위에 런너를 박고 있어요."},{"b":[0.278,0.265,0.175,0.3],"c":[0.2655,0.249,0.2,0.332],"r":1.071,"img":"img/L3/walk/p017_22_02.jpg","say":"2번: 스터드 시공. 런너 사이에 세로 기둥을 세워요."},{"b":[0.47,0.265,0.18,0.3],"c":[0.458,0.249,0.204,0.332],"r":1.0924,"img":"img/L3/walk/p017_22_03.jpg","say":"3번: 한쪽 석고보드 시공. 아직 반대쪽은 뼈대가 보여요."},{"b":[0.67,0.265,0.18,0.3],"c":[0.658,0.249,0.204,0.332],"r":1.0924,"img":"img/L3/walk/p017_22_04.jpg","say":"4번: 단열재 시공(필요 시). 노란 솜을 스터드 사이에 채워요."},{"b":[0.085,0.635,0.175,0.3],"c":[0.0725,0.619,0.2,0.332],"r":1.071,"img":"img/L3/walk/p017_22_05.jpg","say":"5번: 반대쪽 석고보드 시공. 이제 벽이 닫혀요."},{"b":[0.278,0.635,0.175,0.3],"c":[0.2655,0.619,0.2,0.332],"r":1.071,"img":"img/L3/walk/p017_22_06.jpg","say":"6번: 조인트 처리 및 마감. 통에 든 컴파운드를 헤라로 발라요."}]}},{"p":18,"title":"상세 순서 1~4: 먹매김, 하부 런너, 시작 스터드, 상부 런너","terms":["먹매김","Steel Runner","C-Stud","Dry-Wall"],"pass1":[{"kind":"say","lines":["상세 버전 아홉 단계 중 앞 네 단계, 즉 뼈대의 시작 부분이에요.","바닥에 선을 긋고, 아래 레일을 깔고, 첫 기둥을 세우고, 위 레일을 붙여요.","주문으로는 먹, 아래, 시작, 위 까지예요."]}],"pass2":[{"kind":"steps","head":"1~4단계","steps":["1. **먹매김**: 런너를 고정할 먹선을 바닥에 놓아요.","2. 하부 런너 고정: 바닥 **스틸런너(Steel Runner)**를 600mm 간격으로 고정해요.","3. 시작 스터드 시공: 벽에 붙는 첫 **C-스터드(C-Stud)**를 600mm 이내 간격으로 고정해요.","4. 상부 런너 고정: 천장 쪽 런너를 붙여요."],"answer":"먹, 아래, 시작, 위"},{"kind":"points","head":"그림 속 숫자와 메모","items":["2번 그림: 600mm 간격으로 타정총을 쏴 하부 런너를 고정해요.","3번 그림: 시작 스터드를 벽에 붙일 때 고정 간격이 600mm 이내라고 두 군데 적혀 있어요.","4번 그림: 일반적으로 칸막이는 천장상부 슬라브까지 시공합니다 라고 적혀 있어요.","이 메모는 뒤에 나오는 방음 공사(25쪽)와 그대로 이어지는 이야기예요."]},{"kind":"points","head":"왜 시작 스터드를 따로 세울까","items":["벽에 붙는 첫 기둥은 기준이 되는 기둥이라 따로 한 단계로 뺐어요.","이 기둥이 기울면 뒤에 세우는 스터드가 전부 따라 기울어요.","그래서 **먹매김** 선과 시작 스터드가 **건식벽체(Dry-Wall)** 품질을 좌우해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"상세 순서에서 3단계는 무엇인가?","choices":["스터드 시공","시작 스터드 시공","바탕 석고보드 시공","상부 런너 고정"],"a":1,"why":"**먹매김**, 하부 런너 고정, 시작 스터드 시공, 상부 런너 고정 순서예요."},{"kind":"check","q":"슬라이드 그림에서 하부 런너 고정 간격은?","choices":["450mm","600mm","900mm","1,800mm"],"a":1,"why":"그림에 600mm간격이라고 표시돼 있어요. 15쪽 그림에도 상부런너, 바닥런너 600mm 간격이 적혀 있어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1477,0.1017],"c":[0,0.0208,0.2,0.1337],"r":2.6594,"img":"img/L3/walk/p018_h.jpg"},"parts":[{"b":[0.244,0.148,0.288,0.295],"c":[0.2296,0.132,0.3168,0.327],"r":1.7223,"img":"img/L3/walk/p018_23_01.jpg","say":"1. 먹매김. 바닥에 러너 고정 먹선을 튕겨 놓는 장면이에요."},{"b":[0.534,0.148,0.252,0.295],"c":[0.5214,0.132,0.2772,0.327],"r":1.507,"img":"img/L3/walk/p018_23_02.jpg","say":"2. 하부 런너 고정. 위에 600mm간격이라고 적혀 있어요."},{"b":[0.244,0.465,0.288,0.435],"c":[0.2296,0.4433,0.3168,0.4785],"r":1.177,"img":"img/L3/walk/p018_23_03.jpg","say":"3. 시작 스터드 시공. 600mm이내가 세로와 가로 두 군데 적혀 있어요."},{"b":[0.539,0.465,0.275,0.435],"c":[0.5253,0.4433,0.3025,0.4785],"r":1.1239,"img":"img/L3/walk/p018_23_04.jpg","say":"4. 상부 런너 고정. 칸막이는 천장상부 슬라브까지 시공한다는 메모가 있어요."}]}},{"p":19,"title":"상세 순서 5: 스터드 시공","terms":["C-Stud","Steel Runner","Gypsum Board"],"pass1":[{"kind":"say","lines":["다섯 번째 단계는 남은 **C-스터드(C-Stud)**를 줄줄이 세우는 일이에요.","위아래 런너 사이에 끼우기만 하면 되도록 스터드를 조금 짧게 잘라요.","여기까지가 뼈대예요. 다음부터는 살을 붙여요."]}],"pass2":[{"kind":"points","head":"그림에 적힌 숫자와 규칙","items":["스터드를 층고보다 10mm 짧게 잘라 설치해요. 딱 맞게 자르면 끼울 수가 없어요.","그림 아래 치수는 450mm, 450mm로 스터드 간격을 보여 줘요.","**석고보드(Gypsum Board)**의 폭이 1200mm이면 600mm 간격으로 설치해요.","스터드는 동일방향으로 설치해요. 날개가 전부 같은 쪽을 보게 해요."]},{"kind":"points","head":"왜 같은 방향이어야 할까","items":["스터드 단면은 C자라 한쪽에만 날개가 있어요.","방향이 섞이면 보드를 대는 면의 높이가 들쭉날쭉해져요.","그러면 보드 이음매에 단차가 생기고, 나사 위치도 일정하지 않아요.","보드 폭과 스터드 간격이 맞아야 보드 가장자리가 스터드 위에 정확히 놓여요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"스터드를 자를 때 기준으로 옳은 것은?","choices":["층고보다 10mm 짧게","층고와 똑같이","층고보다 10mm 길게","층고의 절반"],"a":0,"why":"짧게 잘라야 런너 사이에 끼워 넣을 수 있고 건물 움직임도 받아 줘요."},{"kind":"check","q":"**석고보드(Gypsum Board)** 폭이 1200mm일 때 **C-스터드(C-Stud)** 간격은?","choices":["300mm","450mm","600mm","900mm"],"a":2,"why":"보드 폭을 반으로 나눈 값이에요. 900 폭이면 450, 1200 폭이면 600이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["10mm는 스터드를 짧게 자르는 값, 5~10mm는 보드를 바닥에서 띄우는 값이에요.","스터드 방향을 한쪽으로 동일하게 한다는 규칙은 16쪽 원문에도 적혀 있어요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1477,0.1012],"c":[0,0.0208,0.2,0.1332],"r":2.6693,"img":"img/L3/walk/p019_h.jpg"},"parts":[{"b":[0.25,0.3,0.3,0.58],"c":[0.235,0.271,0.33,0.638],"r":0.9195,"img":"img/L3/walk/p019_22_01.jpg","say":"왼쪽 큰 그림: 런너 사이에 스터드를 줄줄이 세운 모습이에요."},{"b":[0.395,0.14,0.155,0.15],"c":[0.3725,0.124,0.2,0.182],"r":1.9536,"img":"img/L3/walk/p019_22_02.jpg","say":"확대 원: 스터드를 층고보다 10mm 짧게 잘라 설치합니다."},{"b":[0.25,0.81,0.1,0.045],"c":[0.2,0.7775,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p019_22_03.jpg","say":"아래 치수: 450mm, 450mm. 스터드 간격이에요."},{"b":[0.59,0.3,0.2,0.24],"c":[0.578,0.284,0.224,0.272],"r":1.4641,"img":"img/L3/walk/p019_22_04.jpg","say":"오른쪽 위: 스터드는 동일방향으로 설치합니다."},{"b":[0.59,0.56,0.33,0.3],"c":[0.5735,0.544,0.363,0.332],"r":1.9438,"img":"img/L3/walk/p019_22_05.jpg","say":"오른쪽 아래: 석고보드의 폭이 1200mm이면 600mm간격으로 설치합니다."}]}},{"p":20,"title":"상세 순서 6~7: 바탕 석고보드와 단열재","terms":["Gypsum Board","INSULATION","Steel Runner","C-Stud","1ply"],"pass1":[{"kind":"say","lines":["여섯 번째는 한쪽에 바탕 **석고보드(Gypsum Board)**를 붙이는 일이에요.","일곱 번째는 그 안쪽에 **단열재(INSULATION)**를 채우는 일이에요.","한쪽을 막아야 솜이 흘러내리지 않고 제자리에 있어요."]}],"pass2":[{"kind":"points","head":"6. 바탕 **석고보드(Gypsum Board)** 시공","items":["바탕보드는 **1ply**, 즉 한 겹이에요. 나사못으로 스터드에 고정해요.","그림에 나사 간격이 가로 450mm(600mm), 세로 600mm로 표시돼 있어요.","보드를 붙일 때 스터드와 **스틸런너(Steel Runner)**의 접합부에는 나사못 고정을 하지 않아요.","보드는 벽체 높이보다 10~20mm 정도 짧게 잘라요.","바닥과 천장 접합면에서 각각 5~10mm 정도 띄워 나사못으로 고정해요."]},{"kind":"points","head":"7. **단열재(INSULATION)** 고정","items":["**C-스터드(C-Stud)** 사이사이를 노란 단열재로 채워요.","이때 전기, 통신, 방송 케이블 위치를 함께 확인해요(16쪽 원문).","단열재가 들어가면 열도 막고 소리도 어느 정도 잡아 줘요.","반대쪽 보드를 붙이기 전이라 속이 훤히 보이는 마지막 순간이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**석고보드(Gypsum Board)**를 붙일 때 옳지 않은 것은?","choices":["바닥에서 5~10mm 띄운다","바닥에 밀착시켜 틈이 없게 한다","벽체 높이보다 10~20mm 짧게 자른다","스터드와 런너 접합부에는 나사못 고정을 하지 않는다"],"a":1,"why":"보드는 바닥과 천장에서 각각 5~10mm 띄워요. 밀착시키면 건물이 움직일 때 보드가 눌려 깨져요."},{"kind":"check","q":"**단열재(INSULATION)**를 충진하는 시점은?","choices":["양쪽 보드를 모두 붙인 뒤","한쪽 보드를 붙인 뒤","스터드를 세우기 전","조인트 처리 뒤"],"a":1,"why":"한 면 붙이기가 끝나면 스터드 사이사이에 충진하고, 그다음 반대쪽을 막아요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1253,0.0551],"c":[0,0.0208,0.2,0.0871],"r":4.0822,"img":"img/L3/walk/p020_h.jpg"},"parts":[{"b":[0.23,0.125,0.12,0.05],"c":[0.19,0.095,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p020_22_01.jpg","say":"왼쪽 라벨: 6. 바탕 석고보드 시공."},{"b":[0.365,0.29,0.13,0.17],"c":[0.33,0.274,0.2,0.202],"r":1.7602,"img":"img/L3/walk/p020_22_02.jpg","say":"치수: 나사 간격 가로 450mm(600mm), 세로 600mm."},{"b":[0.215,0.715,0.32,0.2],"c":[0.199,0.699,0.352,0.232],"r":2.6973,"img":"img/L3/walk/p020_22_03.jpg","say":"아래 설명: 스터드와 런너 접합부에는 나사못 고정을 하지 않아요. 보드는 10~20mm 짧게, 5~10mm 띄워요."},{"b":[0.575,0.1,0.4,0.6],"c":[0.555,0.07,0.44,0.66],"r":1.1852,"img":"img/L3/walk/p020_22_04.jpg","say":"오른쪽 그림: 스터드 사이에 노란 단열재를 채운 모습이에요."},{"b":[0.865,0.63,0.1,0.05],"c":[0.8,0.6,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p020_22_05.jpg","say":"오른쪽 라벨: 7. 단열재 고정."}]}},{"p":21,"title":"상세 순서 8: 반대쪽 바탕 석고보드 (1ply)","terms":["Gypsum Board","1ply","2ply","INSULATION"],"pass1":[{"kind":"say","lines":["여덟 번째는 반대쪽에 바탕 **석고보드(Gypsum Board)** 한 겹, 즉 **1ply**를 붙이는 일이에요.","이제 **단열재(INSULATION)**가 보이지 않게 벽이 닫혀요.","이때 이음매를 앞면과 엇갈리게 놓는 것이 핵심이에요."]}],"pass2":[{"kind":"points","head":"엇갈리게 붙이는 규칙 세 가지","items":["반대쪽 **석고보드(Gypsum Board)**를 한쪽 석고보드와 이음매가 엇갈리도록 나사못으로 고정해요.","반대쪽 보드의 가로 조인트는 앞면 보드의 가로 조인트와 엇갈리게 시공해요.","스터드 양쪽의 세로 조인트도 서로 엇갈리게 시공해요.","가로든 세로든 앞뒤 이음매가 한 줄로 겹치면 그 선을 따라 갈라지기 때문이에요."]},{"kind":"points","head":"그림 속 숫자","items":["나사 간격은 앞면과 같아요. 가로 450mm(600mm), 세로 600mm예요.","왼쪽 그림에서 아직 노란 **단열재(INSULATION)**가 보이는 칸이 남아 있어요.","이 단계가 끝나면 남은 것은 마감 **2ply**뿐이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"반대쪽 바탕 **석고보드(Gypsum Board)**를 붙일 때 이음매 처리는?","choices":["앞면 이음매와 같은 줄에 맞춘다","앞면 이음매와 엇갈리게 한다","이음매를 일부러 벌려 둔다","이음매 위에 스터드를 하나 더 세운다"],"a":1,"why":"앞뒤 이음매가 한 줄로 겹치면 그 선을 따라 갈라지기 쉬워요."}],"walk":{"head":null,"parts":[{"b":[0.175,0.25,0.17,0.05],"c":[0.16,0.22,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p021_22_01.jpg","say":"라벨: 8. 반대쪽 바탕 석고보드 시공 (1ply)."},{"b":[0.34,0.39,0.11,0.17],"c":[0.295,0.374,0.2,0.202],"r":1.7602,"img":"img/L3/walk/p021_22_02.jpg","say":"치수: 450mm(600mm)와 600mm 나사 간격."},{"b":[0.165,0.835,0.32,0.1],"c":[0.149,0.819,0.352,0.132],"r":4.7407,"img":"img/L3/walk/p021_22_03.jpg","say":"아래 설명: 가로 조인트는 반대쪽과 엇갈리게, 스터드 양쪽 세로 조인트도 서로 엇갈리게."},{"b":[0.53,0.03,0.45,0.4],"c":[0.505,0.01,0.495,0.44],"r":2.0,"img":"img/L3/walk/p021_22_04.jpg","say":"오른쪽 위: 반대쪽 석고보드를 한쪽 석고보드와 이음매가 엇갈리도록 고정."},{"b":[0.53,0.44,0.45,0.52],"c":[0.505,0.414,0.495,0.572],"r":1.5385,"img":"img/L3/walk/p021_22_05.jpg","say":"오른쪽 아래: 스터드 양면의 석고보드 가로 조인트는 상하를 엇갈리게 시공."}]}},{"p":22,"title":"상세 순서 9: 마감 석고보드 (2ply)","terms":["Gypsum Board","2ply","1ply","조인트 테이프","조인트 컴파운드"],"pass1":[{"kind":"say","lines":["마지막 아홉 번째는 마감 **석고보드(Gypsum Board)**, 즉 **2ply**를 붙이는 일이에요.","그림에 1과 2 숫자가 붙어 있어요. 1이 바탕, 2가 마감이에요.","여기까지 붙이면 뼈대에 살이 다 붙은 거예요."]}],"pass2":[{"kind":"points","head":"**2ply** 시공 규칙","items":["마감석고보드와 바탕석고보드의 가로 조인트는 서로 엇갈리게 시공해요.","그림의 1번 자리와 2번 자리가 서로 어긋나 있는 것이 그 표시예요.","**석고보드(Gypsum Board)**는 벽체 높이보다 10~20mm 정도 짧게 잘라요.","바닥과 천장 접합면에서 각각 5~10mm 정도 띄워 나사못으로 고정해요."]},{"kind":"points","head":"그림 속 숫자","items":["가로 나사 간격 450mm(600mm), 세로 300mm로 표시돼 있어요.","마감 보드는 바탕 보드보다 나사를 더 촘촘히 박는다는 뜻이에요.","16쪽 원문에서는 2겹을 치장보드라 부르고, 나사못 또는 타카핀으로 시공하며 본드를 충분히 도포한다고 했어요."]},{"kind":"points","head":"그다음에 오는 것","items":["보드가 다 붙으면 이음매에 **조인트 테이프**를 붙여요.","그 위를 **조인트 컴파운드**로 메우고 24시간 정도 경화시켜요.","그다음이 퍼티, 도장이나 도배 같은 마감이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"마감 **석고보드(Gypsum Board)** 시공에 대한 설명으로 옳은 것은?","choices":["바탕 보드와 가로 조인트를 맞춘다","바탕 보드와 가로 조인트를 엇갈리게 한다","바탕 보드 없이 바로 마감만 한다","나사 없이 본드로만 붙인다"],"a":1,"why":"**1ply**와 **2ply**의 경계선은 엇갈리게 시공해요. 2겹째는 본드를 충분히 도포하고 나사못이나 타카핀으로 고정해요."},{"kind":"english","head":"단답 답안: 1ply와 2ply 경계선 처리","en":"석고보드는 1ply와 2ply의 경계선이 서로 엇갈리게 시공하여야 하며, 이는 같은 위치에 이음매가 겹치면 균열이 생기기 쉽기 때문이다.","ko":"벽돌 쌓기처럼 줄눈을 어긋나게.","tip":"엇갈리게 라는 단어를 꼭 넣어 쓰세요."}],"walk":{"head":{"b":[0.0092,0.0368,0.2104,0.1898],"c":[0,0.0208,0.2344,0.2218],"r":1.8788,"img":"img/L3/walk/p022_h.jpg"},"parts":[{"b":[0.075,0.255,0.16,0.05],"c":[0.055,0.225,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p022_23_01.jpg","say":"라벨: 9. 마감 석고보드 시공 (2ply)."},{"b":[0.195,0.44,0.12,0.24],"c":[0.155,0.424,0.2,0.272],"r":1.3072,"img":"img/L3/walk/p022_23_02.jpg","say":"치수: 가로 450mm(600mm), 세로 300mm 나사 간격."},{"b":[0.21,0.28,0.3,0.22],"c":[0.195,0.264,0.33,0.252],"r":2.328,"img":"img/L3/walk/p022_23_03.jpg","say":"1번과 2번 사각 표시: 1이 바탕 1ply, 2가 마감 2ply예요. 경계선이 어긋나 있어요."},{"b":[0.56,0.39,0.42,0.08],"c":[0.538,0.374,0.462,0.112],"r":7.3333,"img":"img/L3/walk/p022_23_04.jpg","say":"오른쪽 위 설명: 보드는 벽체 높이보다 10~20mm 짧게, 접합면에서 5~10mm 띄워요."},{"b":[0.56,0.905,0.36,0.075],"c":[0.542,0.8875,0.396,0.11],"r":6.4,"img":"img/L3/walk/p022_23_05.jpg","say":"오른쪽 아래 설명: 마감석고보드와 바탕석고보드의 가로 조인트는 서로 엇갈리게."}]}},{"p":23,"title":"참고: 석고보드 사이즈에 따른 스터드 배열","terms":["Gypsum Board","C-Stud","Dry-Wall"],"pass1":[{"kind":"say","lines":["**석고보드(Gypsum Board)**가 몇 mm짜리냐에 따라 스터드 간격이 달라진다는 참고 쪽이에요.","보드 가장자리가 반드시 스터드 위에 놓여야 하기 때문이에요.","그래서 보드 폭을 반으로 나눈 값이 스터드 간격이 돼요."]}],"pass2":[{"kind":"compare","head":"보드 규격과 **C-스터드(C-Stud)** 간격","cols":["석고보드 규격","그림에 적힌 치수","스터드 간격"],"rows":[["900 x 1,800","900mm, 900mm, 450mm","450mm"],["1,200 x 2,400","1,200mm, 1,200mm, 600mm","600mm"]]},{"kind":"points","head":"그림 읽는 법","items":["위 그림은 900 x 1,800 보드예요. 위 치수줄이 900, 900이고 아래 치수줄이 450, 900이에요.","보드 한 장 폭 900 안에 스터드가 양 끝과 가운데, 모두 세 군데 걸려요.","아래 그림은 1,200 x 2,400 보드예요. 위가 1,200, 아래가 600, 1,200이에요.","보드가 커지면 스터드 개수는 줄지만 간격은 넓어져요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**석고보드(Gypsum Board)** 규격이 900 x 1,800일 때 스터드 간격은?","choices":["300mm","450mm","600mm","900mm"],"a":1,"why":"보드 폭 900을 반으로 나눈 450mm예요. 1,200 폭이면 600mm예요."},{"kind":"warn","head":"숫자 정리","items":["석고보드 규격 두 가지: 900 x 1,800과 1,200 x 2,400이에요.","짝지어 외우세요. 900이면 450, 1,200이면 600이에요.","**C-스터드(C-Stud)** 기본 간격 300mm와 450mm 중 450이 자주 쓰이는 이유가 여기 있어요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.2104,0.1898],"c":[0,0.0208,0.2344,0.2218],"r":1.8788,"img":"img/L3/walk/p023_h.jpg"},"parts":[{"b":[0.05,0.27,0.29,0.05],"c":[0.0355,0.24,0.319,0.11],"r":5.1556,"img":"img/L3/walk/p023_22_01.jpg","say":"제목 박스: 참고, 석고보드 사이즈에 따른 석고보드와 스터드 배열 방법."},{"b":[0.105,0.37,0.44,0.22],"c":[0.083,0.354,0.484,0.252],"r":3.4145,"img":"img/L3/walk/p023_22_02.jpg","say":"위 그림: 900mm, 900mm 위 치수와 450mm, 900mm 아래 치수."},{"b":[0.56,0.475,0.16,0.05],"c":[0.54,0.445,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p023_22_03.jpg","say":"라벨: 석고보드 사이즈 900 곱하기 1,800."},{"b":[0.1,0.61,0.46,0.25],"c":[0.077,0.594,0.506,0.282],"r":3.1899,"img":"img/L3/walk/p023_22_04.jpg","say":"아래 그림: 1,200mm 위 치수와 600mm, 1,200mm 아래 치수."},{"b":[0.56,0.72,0.17,0.05],"c":[0.545,0.69,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p023_22_05.jpg","say":"라벨: 석고보드 사이즈 1,200 곱하기 2,400."}]}},{"p":24,"title":"참고: 퍼티 작업과 시공 영상","terms":["조인트 테이프","조인트 컴파운드","Gypsum Board","Dry-Wall"],"pass1":[{"kind":"say","lines":["이음매와 나사 자국을 메워 면을 고르게 만드는 퍼티 작업 사진 한 장이에요.","**건식벽체(Dry-Wall)** 공사의 마지막 손질이에요.","여기까지 끝나야 도장이나 도배로 넘어가요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것","items":["세로로 긴 흰 줄이 보드와 보드 사이의 이음매예요. **조인트 테이프** 위를 메운 자리예요.","동글동글한 흰 점들이 나사못 자국을 메운 자리예요.","**조인트 컴파운드**로 이음매를 메우고 24시간 정도 경화시킨 뒤에 하는 작업이에요.","면이 고르지 않으면 도장이나 도배를 해도 빛에 이음매가 그대로 비쳐요."]},{"kind":"bg","src":"배경 지식","lines":["퍼티는 벽면의 파이거나 튀어나온 곳을 메워 평평하게 만드는 반죽 재료예요.","**석고보드(Gypsum Board)** 면이 평평해야 페인트나 벽지가 깨끗하게 붙어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"퍼티 작업을 하는 시점으로 옳은 것은?","choices":["스터드를 세우기 전","**단열재(INSULATION)** 충진 직후","조인트 처리가 끝난 뒤, 도장이나 도배 전","도배를 한 뒤"],"a":2,"why":"**조인트 테이프**와 **조인트 컴파운드**로 이음매를 처리하고 24시간 경화시킨 뒤에 퍼티로 면을 고르게 해요."}],"walk":{"head":{"b":[0.0092,0.0368,0.2104,0.1898],"c":[0,0.0208,0.2344,0.2218],"r":1.8788,"img":"img/L3/walk/p024_h.jpg"},"parts":[{"b":[0.06,0.255,0.12,0.05],"c":[0.02,0.225,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p024_22_01.jpg","say":"제목 박스: 참고, 퍼티 작업."},{"b":[0.06,0.33,0.62,0.585],"c":[0.029,0.3008,0.682,0.6435],"r":1.8841,"img":"img/L3/walk/p024_22_02.jpg","say":"사진: 이음매를 따라 흰 띠가, 나사 자리마다 흰 점이 찍혀 있어요."},{"b":[0.69,0.355,0.29,0.045],"c":[0.6755,0.3225,0.319,0.11],"r":5.1556,"img":"img/L3/walk/p024_22_03.jpg","say":"오른쪽: 경량철골 벽체 시공영상 주소가 적혀 있어요."}]}},{"p":25,"title":"방음 공사: 흡음, 차음, 그리고 슬라브까지","terms":["흡음충진재","흡음 마감재","방진고무","경량철골","Dry-Wall","Gypsum Board"],"pass1":[{"kind":"say","lines":["기본 스터드 벽은 소리를 잘 못 막아요. 그래서 따로 방음 공사를 해요.","소리를 빨아들이는 재료와 튕겨 내는 재료를 겹겹이 넣어요.","그리고 벽을 천장 마감재 위, 보나 슬라브까지 올려요."]},{"kind":"analogy","head":"칸막이 위가 뚫린 화장실","scene":"화장실 칸막이는 위가 뚫려 있어 옆 칸 소리가 다 넘어오죠. 천장 마감재까지만 세운 벽이 딱 그래요.","map":[["뚫린 칸막이 위","천장 마감재까지만 세운 **경량철골** 벽"],["천장까지 막은 벽","보 또는 슬라브까지 올린 벽"],["소리가 넘어가는 길","천장 속 빈 공간"]]}],"pass2":[{"kind":"points","head":"슬라이드 본문 네 줄","items":["기본 스터드 벽체는 소음을 차단하는 기능이 미흡해요.","방음을 위해서는 기본 벽체에 **흡음충진재**와 차음재의 사용을 반복하여 시공하고 **흡음 마감재**로 시공해요.","벽체는 텍스 등 천장마감재 위의 천장까지 설치해요. 천장 마감재까지만 하면 천장을 통해 소리가 전달돼요.","**방진고무**를 사용하면 저음을 제어할 수 있어요.","벽체 중간에 공간을 50mm 정도 두면 방음효과를 볼 수 있어요. 단, 충진재가 없으면 그 공간이 울림통이 돼요."]},{"kind":"compare","head":"흡음과 차음, 무엇이 다를까","cols":["구분","하는 일","이 쪽의 예"],"rows":[["흡음","소리를 빨아들여 없앤다","**흡음충진재**, **흡음 마감재**"],["차음","소리를 튕겨 내 막는다","차음재, 차음시트(26쪽)"],["방진","진동을 끊어 저음을 잡는다","**방진고무**"]]},{"kind":"points","head":"**흡음 마감재** 세 가지 (오른쪽 사진)","items":["목모보드: 나무를 실처럼 뽑아 굳힌 거친 표면의 보드예요.","타공보드: 구멍을 뚫어 소리가 들어가게 만든 보드예요.","아트보드: 부드러운 섬유질 표면의 보드예요.","세 가지 모두 표면이 거칠거나 구멍이 있어서 소리를 빨아들여요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"방음 공사에 대한 설명으로 옳지 않은 것은?","choices":["**방진고무**로 저음을 제어할 수 있다","충진재가 없으면 공간이 울림통이 될 수 있다","벽체 중간 50mm 정도 공간을 두면 방음효과가 있다","벽체는 텍스 천장 마감재 높이까지만 세우면 충분하다"],"a":3,"why":"벽체는 천장마감재 위의 천장, 즉 보나 슬라브까지 설치해야 천장을 통한 소리 전달을 막아요."},{"kind":"exam","src":"문제은행 l23","q":"방음 공사에서 저음을 제어하기 위해 사용하는 재료는?","qko":"낮고 웅웅거리는 소리를 잡는 재료 이름을 묻는 단답이에요.","solve":["흡음과 차음 재료는 보통 높은 소리에 효과가 커요.","저음은 진동으로 전해지기 때문에 진동을 끊어야 해요.","슬라이드에는 **방진고무**를 사용하면 저음을 제어할 수 있다고 적혀 있어요."],"answer":"방진고무"},{"kind":"warn","head":"시험에서 잘 걸리는 함정","items":["방음벽은 텍스 천장이 아니라 보, 슬라브까지 올려요.","50mm 공기층은 충진재가 함께 있어야 효과가 있어요. 비어 있으면 울림통이 돼요.","**흡음충진재**는 빨아들이고 차음재는 막아요. 둘을 반복해서 겹쳐 시공해요."]},{"kind":"english","head":"서술 답안: 경량 벽체의 방음 공사 방법","en":"기본 스터드 벽체는 차음이 미흡하므로 흡음충진재와 차음재를 반복 시공하고 흡음 마감재로 마감한다. 벽체는 보 또는 슬라브까지 올리고, 방진고무로 저음을 제어하며, 중간에 50mm 공기층을 두되 충진재를 채운다.","ko":"재료 겹치기, 슬라브까지 올리기, 방진고무, 50mm 공기층 네 가지를 쓰면 돼요.","tip":"겹치고, 올리고, 끊고, 띄운다 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.225,0.8,0.17],"c":[0,0.209,0.88,0.202],"r":7.7448,"img":"img/L3/walk/p025_23_01.jpg","say":"본문 네 줄: 미흡한 차단 성능, 천장까지 설치, 방진고무, 50mm 공기층."},{"b":[0.038,0.51,0.44,0.33],"c":[0.016,0.4935,0.484,0.363],"r":2.3704,"img":"img/L3/walk/p025_23_02.jpg","say":"왼쪽 사진 두 장: 천장 끝까지 벽체 작업이라고 표시돼 있어요."},{"b":[0.565,0.45,0.17,0.05],"c":[0.55,0.42,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p025_23_03.jpg","say":"가운데 라벨: 보 또는 슬라브 까지 올려서 벽체 설치!"},{"b":[0.5,0.5,0.31,0.43],"c":[0.4845,0.4785,0.341,0.473],"r":1.2817,"img":"img/L3/walk/p025_23_04.jpg","say":"가운데 그림: 왼쪽은 슬라브까지 올려 O, 오른쪽은 천장 마감재까지만 해서 X."},{"b":[0.83,0.02,0.16,0.7],"c":[0.7005,0,0.2995,0.77],"r":0.6915,"img":"img/L3/walk/p025_23_05.jpg","say":"오른쪽 사진 세 장: 목모보드, 타공보드, 아트보드."}]}},{"p":26,"title":"방음 공사 시공 사진: 충진재와 차음시트","terms":["흡음충진재","차음시트","Gypsum Board","1ply"],"pass1":[{"kind":"say","lines":["방음 벽체를 실제로 어떻게 만드는지 보여 주는 사진 네 장이에요.","솜을 채우고, 틈을 막고, 검은 **차음시트**를 대고, 차음 보드를 붙여요.","순서대로 겹겹이 쌓는다는 점만 기억하면 돼요."]}],"pass2":[{"kind":"points","head":"사진 네 장이 말하는 것","items":["충진재 설치 작업: 스터드 사이에 **흡음충진재**를 끼워 넣고 있어요.","전선 배관 등 빈틈은 폼으로 충진: 구멍이 하나라도 있으면 소리가 그리로 새요.","**차음시트** 시공: 검은 고무 같은 시트를 보드 사이에 넣어요.","오른쪽 아래는 실제로 벽에 차음 석고보드를 붙이는 장면이에요."]},{"kind":"steps","head":"슬라이드가 적어 둔 방음 벽체 구성","steps":["일반 **석고보드(Gypsum Board)** **1ply**","+ **차음시트**","+ 차음 석고보드"],"answer":"일반 보드 1겹, 차음시트, 차음 보드 순서로 겹쳐요."},{"kind":"points","head":"왜 틈을 폼으로 막을까","items":["소리는 아주 작은 틈으로도 잘 빠져나가요.","전선관이나 배관이 벽을 통과하는 자리가 가장 흔한 구멍이에요.","**흡음충진재**를 아무리 채워도 구멍 하나면 효과가 크게 떨어져요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"방음을 위한 벽체 구성 예로 슬라이드에 제시된 것은?","choices":["방수보드 + 방화보드","합판 12T + **석고보드(Gypsum Board)** 9.5T","일반 석고보드 **1ply** + **차음시트** + 차음 석고보드","HPL + 코어재"],"a":2,"why":"슬라이드 오른쪽 아래 박스에 그대로 적혀 있어요."},{"kind":"check","q":"전선 배관이 지나가는 빈틈은 무엇으로 막는가?","choices":["폼","실리콘 테이프","석고 가루","본드"],"a":0,"why":"사진 설명에 전선 배관 등 빈틈은 폼으로 충진이라고 적혀 있어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1477,0.1898],"c":[0,0.0208,0.2,0.2218],"r":1.603,"img":"img/L3/walk/p026_h.jpg"},"parts":[{"b":[0.165,0.245,0.26,0.32],"c":[0.152,0.229,0.286,0.352],"r":1.4444,"img":"img/L3/walk/p026_23_01.jpg","say":"왼쪽 위: 충진재 설치 작업. 노란 흡음충진재를 스터드 사이에 넣어요."},{"b":[0.165,0.59,0.26,0.325],"c":[0.152,0.5737,0.286,0.3575],"r":1.4222,"img":"img/L3/walk/p026_23_02.jpg","say":"왼쪽 아래: 전선 배관 등 빈틈은 폼으로 충진. 흰 폼이 보여요."},{"b":[0.53,0.255,0.25,0.32],"c":[0.5175,0.239,0.275,0.352],"r":1.3889,"img":"img/L3/walk/p026_23_03.jpg","say":"오른쪽 위: 차음시트 시공. 검은 면과 갈색 면이 있는 시트예요."},{"b":[0.53,0.59,0.25,0.325],"c":[0.5175,0.5737,0.275,0.3575],"r":1.3675,"img":"img/L3/walk/p026_23_04.jpg","say":"오른쪽 아래: 일반 석고보드 1ply, 차음 시트, 차음 석고보드 이름표가 붙어 있어요."},{"b":[0.815,0.79,0.11,0.115],"c":[0.77,0.774,0.2,0.147],"r":2.4187,"img":"img/L3/walk/p026_23_05.jpg","say":"오른쪽 박스: 일반 석고보드 1ply + 차음 시트 + 차음 석고보드."}]}},{"p":27,"title":"천장틀의 기본 구성 1: 달대와 달대 볼트","terms":["달대","달대 볼트","스트롱 앵커","인서트","양날 브라켓","행거 클립","경량철골"],"pass1":[{"kind":"say","lines":["여기부터는 벽이 아니라 천장 이야기예요. 천장틀은 위에서 아래로 매달아요.","**달대**는 천장틀을 구조체에 매달아 지지하는 부재예요.","**달대 볼트**는 달대로 쓰는 긴 나사 막대(전산볼트)예요."]},{"kind":"analogy","head":"천장에 매다는 옷걸이","scene":"천장에 고리를 박고 줄을 내린 뒤, 줄 끝에 막대를 걸고 그 막대에 옷을 거는 모습이에요.","map":[["천장에 박는 고리","**스트롱 앵커**나 **인서트**"],["내려오는 줄","**달대 볼트**"],["줄 끝의 걸쇠","**행거 클립**"],["걸린 막대","캐링 채널"]]}],"pass2":[{"kind":"points","head":"천장틀이 무엇인지 먼저","items":["천장을 덮을 때 구성되는 기본적인 골격이에요.","목구조로 하던 천장틀을 금속성 소재로 바꾼 것이 **경량철골** 천장틀이에요.","목구조에 비하여 내구성이 뛰어나며 구조적으로 튼튼한 이점이 있어요.","슬라이드 각주: **달대**는 천장틀을 구조체에 매달아 지지하는 부재예요.","달대볼트(행거볼트, 행어볼트)는 달대로 사용하는 전산볼트 형태의 부재예요."]},{"kind":"points","head":"**달대 볼트**의 숫자와 고정 방법","items":["직경 9mm 이상의 철물로, 볼트를 꽂을 수 있도록 전체에 나선형의 홈이 있어요.","상부는 천장에 **스트롱 앵커**나 **인서트**, **양날 브라켓**을 이용해 고정해요.","하부는 **행거 클립** 및 볼트, 너트로 고정해요.","설치는 약 900mm 정도의 간격을 유지해야 하며, 초과할 때에는 보강을 해야 해요."]},{"kind":"compare","head":"상부 고정 철물 세 가지","cols":["철물","슬라이드 설명"],"rows":[["**스트롱 앵커**","망치로 두들겨 천장에 설치하면 머리 부분이 벌어지면서 고정 됨"],["**인서트**","볼트 등을 부착하기 위해 미리 콘크리트에 매입된 철물"],["**양날 브라켓**","콘크리트나 스트롱 앵커 설치가 어려운 각 파이프 등에 사용"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"문제은행 l23","q":"달대 볼트에 대한 설명으로 옳은 것은?","qko":"달대 볼트의 굵기와 간격, 고정 방법을 묻는 문제예요.","solve":["직경은 9mm 이상이에요.","간격은 약 900mm 정도를 유지하고, 초과하면 보강해요.","상부는 **스트롱 앵커**나 **인서트**, **양날 브라켓**, 하부는 **행거 클립**과 볼트, 너트예요.","상하를 바꿔 적은 보기가 대표적인 오답이에요."],"answer":"직경 9mm 이상, 약 900mm 간격으로 설치한다"},{"kind":"check","q":"망치로 두들겨 천장에 설치하면 머리 부분이 벌어지면서 고정되는 철물은?","choices":["행거 핀","**인서트**","**양날 브라켓**","**스트롱 앵커**"],"a":3,"why":"**인서트**는 콘크리트에 미리 매입된 철물, **양날 브라켓**은 각 파이프 등에 써요."},{"kind":"warn","head":"9와 900 헷갈리지 않기","items":["9mm는 **달대 볼트**의 직경(굵기)이에요.","900mm는 **달대 볼트**를 세우는 간격이에요.","뒤에 나오는 캐링 채널 간격도 약 900mm라 함께 외우면 편해요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1507,0.1012],"c":[0,0.0208,0.2,0.1332],"r":2.6693,"img":"img/L3/walk/p027_h.jpg"},"parts":[{"b":[0.03,0.14,0.72,0.09],"c":[0,0.105,0.792,0.16],"r":8.8,"img":"img/L3/walk/p027_23_01.jpg","say":"위 본문 두 줄: 천장틀의 정의와, 목구조보다 내구성이 뛰어나다는 장점."},{"b":[0.285,0.275,0.3,0.06],"c":[0.27,0.25,0.33,0.11],"r":5.3333,"img":"img/L3/walk/p027_23_02.jpg","say":"각주 두 줄: 달대와 달대볼트(행거볼트, 행어볼트)의 뜻이에요."},{"b":[0.03,0.35,0.55,0.19],"c":[0.0025,0.334,0.605,0.222],"r":4.8448,"img":"img/L3/walk/p027_23_03.jpg","say":"본문 네 줄: 직경 9mm 이상, 상부 고정, 하부 고정, 약 900mm 간격."},{"b":[0.61,0.275,0.38,0.21],"c":[0.582,0.259,0.418,0.242],"r":3.0707,"img":"img/L3/walk/p027_23_04.jpg","say":"오른쪽 [전산볼트] 사진: 전체에 나선형 홈이 파인 긴 막대예요."},{"b":[0.025,0.57,0.65,0.35],"c":[0,0.5525,0.715,0.385],"r":3.3016,"img":"img/L3/walk/p027_23_05.jpg","say":"아래 사진 세 장: 스트롱 앵커, 인서트, 양날 브라켓과 각각의 설명이에요."}]}},{"p":28,"title":"천장틀 부속: 행거 클립, 행거 핀, M-Bar 클립","terms":["행거 클립","M-Bar","M-Bar 클립","캐링 채널","달대 볼트","인서트"],"pass1":[{"kind":"say","lines":["천장틀을 이어 주는 작은 부속 사진들이에요.","**행거 클립**, 행거 핀, **M-Bar 클립** 세 가지가 이름표와 함께 나와요.","큰 부재를 잇는 것은 늘 이런 작은 쇳조각이에요."]}],"pass2":[{"kind":"points","head":"부속 세 가지","items":["**행거 클립**: **달대 볼트**와 **캐링 채널**을 고정하는 부속이에요.","행거 핀: 슬라이드에 사진으로 소개된 갈고리 모양 부속이에요.","**M-Bar 클립**: **M-Bar**를 캐링채널에 고정하는 클립이에요.","왼쪽 아래 사진은 볼트와 너트로 높이를 조절하는 조절행거예요."]},{"kind":"points","head":"오른쪽 천장틀 그림의 이름표","items":["위에서부터 **인서트**(콘크리트 매입), 달대볼트(달볼트), 조절행거예요.","그다음 **캐링 채널**이 가로로 지나가고, 클립으로 아래 부재가 붙어요.","아래쪽에 싱글 M-바와 더블 M-바가, 벽 쪽에는 벽 반자돌림대가 표시돼 있어요.","가장 아래가 천장판(텍스)이에요. 위에서 아래로 매달기 순서가 그림 한 장에 다 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**M-Bar**를 캐링채널에 고정하는 부속은?","choices":["**행거 클립**","행거 핀","**M-Bar 클립**","채널 조인트"],"a":2,"why":"**행거 클립**은 **달대 볼트**와 **캐링 채널**을 고정하는 부속이에요."}],"walk":{"head":null,"parts":[{"b":[0.035,0.27,0.14,0.26],"c":[0.005,0.254,0.2,0.292],"r":1.2177,"img":"img/L3/walk/p028_22_01.jpg","say":"[행거 클립]: 납작한 ㄷ자 쇳조각 두 종류예요."},{"b":[0.19,0.27,0.1,0.26],"c":[0.14,0.254,0.2,0.292],"r":1.2177,"img":"img/L3/walk/p028_22_02.jpg","say":"[행거 핀]: 갈고리처럼 구부러진 핀이에요."},{"b":[0.315,0.255,0.15,0.27],"c":[0.29,0.239,0.2,0.302],"r":1.1773,"img":"img/L3/walk/p028_22_03.jpg","say":"[M-Bar 클립]: M-Bar를 캐링채널에 물리는 클립이에요."},{"b":[0.09,0.55,0.16,0.4],"c":[0.07,0.53,0.2,0.44],"r":0.8081,"img":"img/L3/walk/p028_22_04.jpg","say":"왼쪽 아래: 볼트와 너트로 높이를 조절하는 조절행거 실물이에요."},{"b":[0.63,0.03,0.36,0.44],"c":[0.604,0.008,0.396,0.484],"r":1.4545,"img":"img/L3/walk/p028_22_05.jpg","say":"오른쪽 그림: 인서트, 달대볼트, 조절행거, 캐링채널, M-바, 천장판까지 이름표가 다 붙어 있어요."}]}},{"p":29,"title":"달대 볼트 조합: 전산볼트 + 앵커 + 행거클립","terms":["달대 볼트","스트롱 앵커","행거 클립","달대"],"pass1":[{"kind":"say","lines":["**달대 볼트** 한 벌이 어떤 부품으로 조립되는지 보여 주는 쪽이에요.","위쪽은 천장에 박는 부분, 아래쪽은 채널을 거는 부분이에요.","더하기 표시와 등호 표시로 조립 과정을 보여 줘요."]}],"pass2":[{"kind":"points","head":"조합 읽기","items":["왼쪽: 전산볼트 + **스트롱 앵커**. 이쪽이 천장 슬라브 쪽이에요.","가운데: 전산볼트 + **행거 클립** + 볼트 2개(위, 아래). 이쪽이 천장 마감재 쪽이에요.","오른쪽: 둘을 합치면 완성된 **달대** 한 벌이 돼요.","볼트가 위아래 두 개인 이유는 높이를 조절하고 다시 조여 고정하기 위해서예요."]},{"kind":"points","head":"다시 확인하는 숫자","items":["**달대 볼트**의 직경은 9mm 이상이에요.","설치 간격은 약 900mm이고, 초과하면 보강해요.","상부는 **스트롱 앵커**나 인서트, 양날 브라켓, 하부는 **행거 클립**과 볼트, 너트예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**달대 볼트** 조합에서 천장 슬라브 쪽에 오는 것은?","choices":["전산볼트 + **스트롱 앵커**","전산볼트 + **행거 클립**","캐링 채널","M-Bar 클립"],"a":0,"why":"슬라브 쪽은 앵커로 박고, 마감재 쪽은 **행거 클립**과 볼트 2개로 채널을 걸어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1253,0.0551],"c":[0,0.0208,0.2,0.0871],"r":4.0822,"img":"img/L3/walk/p029_h.jpg"},"parts":[{"b":[0.09,0.29,0.18,0.55],"c":[0.0624,0.2625,0.2353,0.605],"r":0.6914,"img":"img/L3/walk/p029_22_01.jpg","say":"왼쪽 사진: 전산볼트와 스트롱 앵커 묶음이에요."},{"b":[0.31,0.29,0.31,0.55],"c":[0.2945,0.2625,0.341,0.605],"r":1.002,"img":"img/L3/walk/p029_22_02.jpg","say":"가운데 사진: 전산볼트에 행거클립과 볼트 2개(위, 아래)가 달려 있어요."},{"b":[0.755,0.1,0.12,0.045],"c":[0.715,0.0675,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p029_22_03.jpg","say":"오른쪽 위 라벨: 천장 슬라브 쪽."},{"b":[0.66,0.13,0.29,0.8],"c":[0.6339,0.09,0.3422,0.88],"r":0.6913,"img":"img/L3/walk/p029_22_04.jpg","say":"오른쪽 사진: 조립이 끝난 달대 볼트가 줄줄이 서 있는 모습이에요."},{"b":[0.755,0.925,0.12,0.045],"c":[0.715,0.89,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p029_22_05.jpg","say":"오른쪽 아래 라벨: 천장 마감재 쪽."}]}},{"p":30,"title":"현장 사진: 앵커, 전산볼트, 행거클립, 캐링채널","terms":["스트롱 앵커","달대 볼트","행거 클립","캐링 채널"],"pass1":[{"kind":"say","lines":["지금까지 배운 부재가 실제 현장에서 어떻게 보이는지 한 장에 모은 사진이에요.","위에서 아래로 앵커, 볼트, 클립, 채널 순서로 이름표가 붙어 있어요.","주문으로 외워요. 위에서 아래로 매달기."]}],"pass2":[{"kind":"steps","head":"사진 속 위에서 아래로","steps":["**스트롱 앵커** (천장 속): 콘크리트 슬라브 안에 박혀 있어 밖에서는 잘 안 보여요.","전산볼트(**달대 볼트**): 앵커에서 아래로 내려오는 긴 나사 막대예요.","**행거 클립**: 볼트 끝에 달려 채널을 물어 주는 부속이에요.","**캐링 채널**: 클립에 걸려 가로로 길게 지나가는 굵은 뼈대예요."],"answer":"슬라브에 박고, 내리고, 물고, 건다"},{"kind":"points","head":"사진에서 더 볼 것","items":["천장 속에 배관과 전선이 같이 지나가는 것이 보여요.","그래서 **달대 볼트** 자리에 큰 환기통이 지나가면 별도의 보강틀이 필요해요(31쪽).","**캐링 채널**이 여러 줄 나란히 가는데, 이 줄 간격이 약 900mm예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"천장틀에서 위에서 아래로 가는 순서로 옳은 것은?","choices":["**캐링 채널** → **행거 클립** → 전산볼트 → **스트롱 앵커**","**스트롱 앵커** → 전산볼트 → **행거 클립** → **캐링 채널**","전산볼트 → **스트롱 앵커** → **캐링 채널** → **행거 클립**","**행거 클립** → **캐링 채널** → 전산볼트 → **스트롱 앵커**"],"a":1,"why":"슬라브에 박고(앵커), 내리고(볼트), 물고(클립), 건다(채널) 순서예요."}],"walk":{"head":{"b":[0.0092,0.0368,0.2759,0.1863],"c":[0,0.0208,0.3035,0.2183],"r":2.4716,"img":"img/L3/walk/p030_h.jpg"},"parts":[{"b":[0.16,0.27,0.5,0.63],"c":[0.135,0.2385,0.55,0.693],"r":1.4109,"img":"img/L3/walk/p030_22_01.jpg","say":"사진: 천장 슬라브 아래에 볼트가 내려오고 채널이 가로지르는 현장이에요."},{"b":[0.725,0.28,0.14,0.045],"c":[0.695,0.2475,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p030_22_02.jpg","say":"이름표 1: 스트롱 앵커 (천장 속)."},{"b":[0.725,0.37,0.11,0.045],"c":[0.68,0.3375,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p030_22_03.jpg","say":"이름표 2: 전산볼트."},{"b":[0.725,0.46,0.11,0.045],"c":[0.68,0.4275,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p030_22_04.jpg","say":"이름표 3: 행거클립."},{"b":[0.725,0.55,0.11,0.045],"c":[0.68,0.5175,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p030_22_05.jpg","say":"이름표 4: 캐링채널."}]}},{"p":31,"title":"달대가 길어질 때: 1.5M 이상이면 보강틀","terms":["달대","달대 볼트","경량철골"],"pass1":[{"kind":"say","lines":["**달대**가 너무 길면 천장 전체가 흔들려요. 긴 줄에 매단 그네처럼요.","그래서 1.5M 이상이면 따로 보강틀을 만들어 거기에 매달아요.","공장처럼 천장이 아주 높은 곳에서 하는 일이에요."]}],"pass2":[{"kind":"points","head":"슬라이드 본문 세 줄","items":["**달대 볼트**의 높이가 1.5M 이상일 때 C-형강과 같은 것으로 보강 틀을 만들어 그것에 달대 볼트를 고정시켜요(주로 공장).","달대의 길이가 너무 길어지면 천장틀이 충격을 받거나 자연재해가 발생했을 때 전체가 울렁이는 현상이 발생하기 때문이에요.","달대 위치에 대형 환기통이 지나가거나 천장고가 너무 높은 경우, 별도의 보강틀을 만들 수도 있어요.","왼쪽 사진에 보강틀에 용접이라고 표시돼 있어요."]},{"kind":"points","head":"왜 길면 흔들릴까","items":["줄이 길수록 같은 힘에도 더 크게 흔들려요. 진자와 같은 원리예요.","천장은 아래에서 받쳐 주는 것이 없어서 흔들림이 그대로 남아요.","그래서 아예 위에서 짧게 잡아 주는 C-형강 틀을 먼저 만들어요.","**경량철골** 천장틀은 가볍지만, 길게 매달면 그 장점이 약점이 돼요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**달대 볼트** 높이가 1.5M 이상일 때 C-형강 등으로 보강틀을 만드는 이유는?","choices":["텍스가 떨어지기 때문","달대가 길면 충격이나 자연재해 시 천장 전체가 울렁이기 때문","달대 볼트 직경이 부족하기 때문","**캐링 채널**이 녹슬기 때문"],"a":1,"why":"주로 공장처럼 천장고가 높은 곳에서 보강틀에 용접해 고정해요."},{"kind":"warn","head":"1.5M 과 9mm, 900mm 정리","items":["9mm는 **달대 볼트** 직경이에요.","900mm는 달대 볼트 설치 간격이에요.","1.5M는 보강틀이 필요해지는 달대 높이예요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.2759,0.1876],"c":[0,0.0208,0.3035,0.2196],"r":2.457,"img":"img/L3/walk/p031_h.jpg"},"parts":[{"b":[0.03,0.235,0.64,0.13],"c":[0,0.219,0.704,0.162],"r":7.7257,"img":"img/L3/walk/p031_22_01.jpg","say":"본문 세 줄: 1.5M 이상이면 C-형강 보강틀, 울렁임 이유, 환기통이 지날 때."},{"b":[0.06,0.45,0.375,0.43],"c":[0.0413,0.4285,0.4125,0.473],"r":1.5504,"img":"img/L3/walk/p031_22_02.jpg","say":"왼쪽 사진: 붉은 C-형강 보강틀에 달대 볼트를 용접한 자리예요."},{"b":[0.445,0.45,0.33,0.43],"c":[0.4285,0.4285,0.363,0.473],"r":1.3643,"img":"img/L3/walk/p031_22_03.jpg","say":"가운데 사진: 천장이 높은 공간에 보강틀을 짠 모습이에요."},{"b":[0.775,0.45,0.22,0.43],"c":[0.756,0.4285,0.244,0.473],"r":0.9171,"img":"img/L3/walk/p031_22_04.jpg","say":"오른쪽 사진: 사다리를 놓고 높은 천장에서 작업하는 현장이에요."}]}},{"p":32,"title":"천장틀의 기본 구성 2: 캐링 채널","terms":["캐링 채널","달대","M-Bar","행거 클립"],"pass1":[{"kind":"say","lines":["**캐링 채널**은 천장틀의 굵은 뼈예요. 천장의 무게를 받는 주 골조예요.","이름 그대로 나르는(carry) 채널이에요.","옷걸이 봉을 떠올리면 돼요. 줄에 걸린 굵은 막대예요."]}],"pass2":[{"kind":"points","head":"**캐링 채널**의 정체와 자리","items":["천장틀의 주 골조 역할을 하는 채널형 부재로, 일반적으로 아연도금 강판을 성형하여 사용해요.","행거에 고정하여 설치하며, 일반적으로 약 900mm 이내 간격으로 배치해요.","이음부는 전용 채널 조인트를 사용하여 견고하게 연결하고 수평을 유지해요.","**M-Bar** 등 하부 천장틀을 지지하며 천장 하중을 행거를 통해 구조체로 전달해요.","공사 순서로는 **행거 클립**을 단 다음, 하부 천장틀을 걸기 전에 설치해요."]},{"kind":"compare","head":"슬라이드 규격표","cols":["부재","치수","그 밖에"],"rows":[["캐링찬넬","높이 38, 폭 12","두께 1.0, 1.2(K.S), 1.6 / 길이 4,000, 주문치수 / 배치 900 곱하기 1200"],["캐링찬넬조인트","폭 7, 높이 35, 길이 90","두께 1.0"]]},{"kind":"points","head":"하중이 전달되는 길","items":["천장 마감재의 무게가 먼저 **M-Bar** 같은 하부 천장틀에 걸려요.","그 무게를 **캐링 채널**이 받아요.","**캐링 채널**은 **달대**를 통해 위 구조체(슬라브)로 무게를 넘겨요.","그래서 캐링 채널 간격과 달대 간격이 둘 다 약 900mm로 맞춰져 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"천장틀의 주 골조로 행거에 고정하며 약 900mm 이내 간격으로 배치하는 부재는?","choices":["마이너 채널","**캐링 채널**","**M-Bar**","크로스 T-Bar"],"a":1,"why":"천장 하중을 행거를 통해 구조체로 전달하는 주 골조예요."},{"kind":"english","head":"서술 답안: 캐링 채널의 역할과 설치 기준","en":"캐링 채널은 아연도금 강판을 성형한 천장틀의 주 골조로, 행거에 고정해 약 900mm 이내 간격으로 배치하고, 이음부는 전용 채널 조인트로 연결해 수평을 유지하며, 천장 하중을 행거를 통해 구조체로 전달한다.","ko":"역할, 간격, 이음, 하중 전달 네 칸으로 적으면 돼요.","tip":"캐링은 나른다(carry), 그래서 하중 전달이 핵심이에요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1584,0.1362],"c":[0,0.0208,0.2,0.1682],"r":2.1139,"img":"img/L3/walk/p032_h.jpg"},"parts":[{"b":[0.03,0.235,0.52,0.18],"c":[0.004,0.219,0.572,0.212],"r":4.7966,"img":"img/L3/walk/p032_23_01.jpg","say":"본문 네 줄: 주 골조, 약 900mm 이내 간격, 채널 조인트, 하중 전달."},{"b":[0.04,0.48,0.31,0.4],"c":[0.0245,0.46,0.341,0.44],"r":1.3778,"img":"img/L3/walk/p032_23_02.jpg","say":"왼쪽 사진: 노란 표시 안이 캐링 채널이에요. 가는 볼트에 걸려 있어요."},{"b":[0.61,0.175,0.31,0.31],"c":[0.5945,0.159,0.341,0.342],"r":1.7726,"img":"img/L3/walk/p032_23_03.jpg","say":"오른쪽 위 규격: 높이 38, 폭 12, 두께 1.0과 1.2(K.S)와 1.6, 길이 4,000."},{"b":[0.61,0.51,0.31,0.3],"c":[0.5945,0.494,0.341,0.332],"r":1.826,"img":"img/L3/walk/p032_23_04.jpg","say":"오른쪽 아래: 캐링찬넬조인트 7, 35, 90, 두께 1.0. 채널을 이을 때 쓰는 부속이에요."}]}},{"p":33,"title":"천장틀의 기본 구성 3: 마이너 채널","terms":["마이너 채널","캐링 채널","달대"],"pass1":[{"kind":"say","lines":["**마이너 채널**은 **캐링 채널**과 직각으로 걸쳐 묶어 주는 보강 막대예요.","굵은 뼈들이 따로 놀지 않게 가로로 한 번 꿰어 주는 셈이에요.","천장이 넓을수록 꼭 필요해요."]},{"kind":"compare","head":"굵은 뼈와 묶는 뼈","cols":["부재","하는 일"],"rows":[["**캐링 채널**","천장 무게를 받는 주 골조"],["**마이너 채널**","캐링 채널을 직교로 묶어 흔들림을 막는 보강"]]}],"pass2":[{"kind":"points","head":"**마이너 채널**의 정체와 자리","items":["**캐링 채널**과 직교하여 설치하는 보강용 채널 부재예요.","천장 면적이 넓은 경우 천장틀의 흔들림과 변형을 방지하고 강성을 보강하기 위해 설치해요.","일반적으로 약 3,000mm 간격으로 설치하며, 구체적인 간격은 설계도서 및 시방에 따라요.","캐링 채널과의 교차부는 채널 클립 등을 사용하여 견고하게 고정해요.","공사 순서로는 캐링 채널을 건 다음, 하부 천장틀(M-Bar, T-Bar)을 걸기 전에 설치해요."]},{"kind":"compare","head":"슬라이드 규격표","cols":["부재","치수","재질"],"rows":[["마이너 찬넬","높이 19mm, 폭 10mm, 길이 4,000mm","1.2mm 아연도금 강판"],["마이너 찬넬 클립","높이 37mm, 폭 13mm","교차부 고정용"]]},{"kind":"points","head":"천장 간격 세 가지 정리","items":["**달대** 볼트 약 900mm","**캐링 채널** 약 900mm 이내","**마이너 채널** 약 3,000mm","굵고 무게를 받는 것일수록 촘촘하고, 묶어 주기만 하는 것은 성글어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"문제은행 l23","q":"마이너 채널에 대한 설명으로 옳지 않은 것은?","qko":"마이너 채널의 방향과 역할, 간격 중 틀린 설명을 고르는 문제예요.","solve":["**마이너 채널**은 **캐링 채널**과 직교해요. 평행이 아니에요.","주 골조는 캐링 채널이고, 마이너 채널은 보강용이에요.","간격은 약 3,000mm, 교차부는 채널 클립으로 고정해요.","그래서 캐링 채널과 평행하게 설치하는 주 골조라는 설명이 틀려요."],"answer":"캐링 채널과 평행하게 설치하는 주 골조이다 (틀린 설명)"},{"kind":"check","q":"**마이너 채널**의 일반적인 설치 간격은?","choices":["약 300mm","약 900mm","약 3,000mm","약 610mm"],"a":2,"why":"**캐링 채널**은 약 900mm, **마이너 채널**은 약 3,000mm예요."},{"kind":"warn","head":"캐링과 마이너 구별","items":["캐링은 주 골조, 약 900mm. 마이너는 보강, 약 3,000mm예요.","둘은 직교해요. 평행이라고 하면 틀려요.","교차부는 채널 클립으로 고정해요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.2496,0.1876],"c":[0,0.0208,0.2746,0.2196],"r":2.223,"img":"img/L3/walk/p033_h.jpg"},"parts":[{"b":[0.03,0.235,0.5,0.18],"c":[0.005,0.219,0.55,0.212],"r":4.6122,"img":"img/L3/walk/p033_23_01.jpg","say":"본문 네 줄: 직교 설치, 흔들림과 변형 방지, 약 3,000mm, 채널 클립 고정."},{"b":[0.07,0.49,0.18,0.39],"c":[0.058,0.4705,0.204,0.429],"r":0.8454,"img":"img/L3/walk/p033_23_02.jpg","say":"왼쪽 사진: 마이너 찬넬 실물과 치수(높이 19, 폭 10, 길이 4,000)."},{"b":[0.26,0.49,0.18,0.36],"c":[0.248,0.472,0.204,0.396],"r":0.9158,"img":"img/L3/walk/p033_23_03.jpg","say":"가운데 사진: 마이너 찬넬 클립. 높이 37, 폭 13이에요."},{"b":[0.5,0.255,0.49,0.56],"c":[0.461,0.227,0.539,0.616],"r":1.5556,"img":"img/L3/walk/p033_23_04.jpg","say":"오른쪽 현장 사진: 노란 마이너 채널과 주황 캐링 채널이 직각으로 만나요."}]}},{"p":34,"title":"M-Bar 시스템: 천장틀에 보드를 나사로 박는 방식","terms":["M-Bar","M-Bar 클립","캐링 채널","1ply","2ply"],"pass1":[{"kind":"say","lines":["천장을 매다는 뼈대 이야기의 주인공, **M-Bar**가 나왔어요.","**캐링 채널(carrying channel)** 이라는 굵은 뼈 아래에 가는 뼈를 거는 거예요.","그 가는 뼈가 **M-Bar**이고, 여기에 보드를 나사로 박아요.","슬라이드에 별표가 붙은 쪽이에요. 시험에 나올 확률이 높아요."]},{"kind":"analogy","head":"천장은 옷걸이다","scene":"천장 속에 옷걸이를 매달아 두고, 그 위에 판을 얹어 아래에서 안 보이게 덮는다고 생각해요.","map":[["옷걸이의 굵은 막대","**캐링 채널(carrying channel)**"],["거기 거는 가는 막대","**M-Bar**"],["막대를 물어 주는 집게","**M-Bar 클립**"],["덮는 판","석고보드와 텍스"]]}],"pass2":[{"kind":"steps","head":"이 쪽이 말하는 M-Bar 시공의 흐름","steps":["**캐링 채널(carrying channel)** 을 먼저 달고, 레이저 레벨기로 기준 수평을 확인해요.","행거볼트와 너트를 돌려 천장틀 전체의 수평을 맞춰요.","**M-Bar** 를 **캐링 채널(carrying channel)** 과 직교하게 놓고 **M-Bar 클립** 으로 고정해요.","바탕보드 **1ply** 를 나사못으로 **M-Bar** 에 박아요.","마감재 **2ply** 는 배면에 본드를 완전히 바르고 빈틈 없이 붙여요."],"answer":"수평 먼저, 그다음 M-Bar, 그다음 보드 두 겹이에요."},{"kind":"points","head":"이 쪽의 숫자와 규칙","items":["**M-Bar** 는 용도에 따라 싱글 M-Bar, 더블 M-Bar를 써요.","설치 간격은 천장 마감재 규격과 설계도서, 시방서에 따라요.","예: 300x600mm 텍스를 쓰는 일부 시스템은 약 300mm 간격이에요.","**2ply** 로 할 때 보드 이음부가 겹치지 않게 엇갈려 배치해요.","마감재는 파손, 변형, 오염이 없는 제품을 쓰고 이음부에 단차가 없게 해요."]},{"kind":"compare","head":"슬라이드 아래 제품표: 엠바 규격 (단위 mm)","cols":["제품","T(두께)","W(너비)","H(높이)"],"rows":[["더블 엠바 DOUBLE M-BAR(MW)","0.45, 0.5, 0.4","45, 50","19, 25"],["싱글 엠바 SINGLE M-BAR(MS)","0.45, 0.5, 0.4","25","19, 25"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"M-Bar는 무엇과 직교하도록 배치하고 무엇으로 고정하나요?","choices":["마이너 채널, 행거 클립","캐링 채널, M-Bar 클립","테두리 몰딩, C/T 클립","달대 볼트, 너트"],"a":1,"why":"**M-Bar** 는 **캐링 채널(carrying channel)** 과 직교하게 놓고 **M-Bar 클립** 으로 물려요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**M-Bar** 의 설치 간격은 고정값이 아니라 마감재 규격을 따라요.","300mm는 300x600mm 텍스를 쓰는 일부 시스템의 예시로 적혀 있어요.","**2ply** 는 겹치는 게 아니라 이음부를 엇갈리게 놓는 거예요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1975,0.1412],"c":[0,0.0208,0.2215,0.1732],"r":2.2735,"img":"img/L3/walk/p034_h.jpg"},"parts":[{"b":[0.03,0.18,0.13,0.04],"c":[0,0.145,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p034_23_01.jpg","say":"별표가 붙어 있어요. 시험에 나오기 쉬운 쪽이라는 표시예요."},{"b":[0.03,0.23,0.67,0.05],"c":[0,0.1806,0.737,0.1489],"r":8.7993,"img":"img/L3/walk/p034_23_02.jpg","say":"레이저 레벨기로 기준 수평을 확인하고 행거볼트와 너트로 수평을 맞춘다는 문장이에요."},{"b":[0.03,0.28,0.6,0.05],"c":[0.0,0.2383,0.66,0.1333],"r":8.8022,"img":"img/L3/walk/p034_23_03.jpg","say":"M-Bar는 캐링 채널과 직교하게 놓고 M-Bar 클립으로 고정한다는 핵심 문장이에요."},{"b":[0.03,0.37,0.55,0.09],"c":[0.0025,0.3539,0.605,0.1222],"r":8.8016,"img":"img/L3/walk/p034_23_04.jpg","say":"설치 간격은 마감재 규격을 따르고, 300x600 텍스면 약 300mm라는 예시예요."},{"b":[0.04,0.65,0.47,0.33],"c":[0.0165,0.6335,0.517,0.363],"r":2.532,"img":"img/L3/walk/p034_23_05.jpg","say":"엠바 제품 규격표예요. 더블은 너비 45, 50, 싱글은 25로 더 좁아요."}]}},{"p":35,"title":"M-Bar 천장 상세도: 부재마다 붙은 숫자 읽기","terms":["M-Bar","캐링 채널","마이너 채널","달대 볼트","M-Bar 클립","1ply"],"pass1":[{"kind":"say","lines":["이 쪽은 **M-Bar** 천장을 잘라 본 그림이에요.","부재마다 크기와 간격이 숫자로 적혀 있어요.","가장 기본이고 실무에서 가장 많이 쓰는 시스템이라고 적혀 있어요."]}],"pass2":[{"kind":"compare","head":"상세도에 적힌 부재와 숫자","cols":["부재","규격","간격"],"rows":[["**달대 볼트(hanger bolt)** (행거볼트)","지름 9mm","900~1,200mm"],["**캐링 채널(carrying channel)**","38x12x1.2T","900~1,200mm"],["**마이너 채널(Minor Channel)**","19x10x1.2T","2,000~3,000mm"],["**M-Bar**","50x19x0.5t","300mm"],["석고보드","900x1,800x9.5T","지정 천장재로 마감"],["시스톤 텍스","300x600","지정 텍스 마감"]]},{"kind":"points","head":"그림에서 챙길 것","items":["위에서 아래로 **달대 볼트(hanger bolt)** → **캐링 채널(carrying channel)** → **M-Bar** → 보드 순서예요.","**마이너 채널(Minor Channel)** 은 **캐링 채널(carrying channel)** 위에 직교로 얹혀 있어요.","**M-Bar 클립** 이 **M-Bar** 와 **캐링 채널(carrying channel)** 이 만나는 곳마다 붙어요.","더블 몰딩 규격은 15x15x15x15x1.2T로 적혀 있어요.","텍스 마감 천장은 실무에서 석고보드 없이 텍스 **1ply** 만 설치하기도 해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"english","head":"답안에 쓸 문장: M-Bar 천장의 구성","en":"M-Bar 천장은 달대 볼트, 캐링 채널, 마이너 채널, M-Bar, 천장 마감재로 구성된다.","ko":"위에서 아래로 매다는 순서 그대로 적으면 돼요.","tip":"볼트, 캐링, 마이너, M-Bar, 판. 다섯 개를 손가락으로 세면서 외워요."},{"kind":"check","q":"상세도에서 M-Bar의 간격으로 적힌 숫자는?","choices":["@300","@610","@900","@2,000"],"a":0,"why":"**M-Bar** 는 @300, **캐링 채널(carrying channel)** 은 @900~1,200, **마이너 채널(Minor Channel)** 은 @2,000~3,000이에요."}],"walk":{"head":null,"parts":[{"b":[0.24,0.06,0.35,0.06],"c":[0.2225,0.035,0.385,0.11],"r":6.2222,"img":"img/L3/walk/p035_22_01.jpg","say":"Ø9 행거볼트 @900~1,200. 지름 9mm 볼트를 900~1,200mm 간격으로 단다는 뜻이에요."},{"b":[0.33,0.12,0.3,0.09],"c":[0.315,0.104,0.33,0.122],"r":4.8087,"img":"img/L3/walk/p035_22_02.jpg","say":"마이너찬넬 19X10X1.2T @2,000~3,000. 굵은 뼈를 가로로 묶는 보강 채널이에요."},{"b":[0.33,0.17,0.28,0.05],"c":[0.316,0.14,0.308,0.11],"r":4.9778,"img":"img/L3/walk/p035_22_03.jpg","say":"캐링찬넬 38X12X1.2T. 천장틀의 주 골조예요."},{"b":[0.3,0.53,0.28,0.05],"c":[0.286,0.5,0.308,0.11],"r":4.9778,"img":"img/L3/walk/p035_22_04.jpg","say":"M-Bar 50X19X0.5t @300. 가는 뼈를 300mm 간격으로 건다는 표시예요."},{"b":[0.58,0.62,0.3,0.1],"c":[0.565,0.604,0.33,0.132],"r":4.4444,"img":"img/L3/walk/p035_22_05.jpg","say":"오른쪽 영어 그림에도 같은 부재 이름이 있어요. Hanger Bolt, Carrying Channel, Minor Channel."}]}},{"p":36,"title":"M-Bar 천장 사진: 아래에서 나사못이 보인다","terms":["M-Bar","T-Bar"],"pass1":[{"kind":"say","lines":["완성된 **M-Bar** 천장을 아래에서 찍은 사진이에요.","텍스를 **M-Bar** 에 나사못으로 바로 박기 때문에 점 같은 나사못 자국이 보여요.","이 자국이 **M-Bar** 천장인지 아닌지 알아보는 표시예요."]}],"pass2":[{"kind":"points","head":"사진에서 볼 것","items":["왼쪽 사진은 텍스로 마감한 천장 전체 모습이에요.","오른쪽 확대 사진에 보라색 동그라미로 나사못 자국을 표시해 놨어요.","**M-Bar** 에 텍스를 나사못으로 직접 고정하기 때문에 아래에서 나사못이 보여요.","반대로 **T-Bar** 천장은 패널을 얹기만 해서 나사못이 안 보여요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"천장을 아래에서 봤을 때 나사못 자국이 보이는 시스템은?","choices":["T-Bar 시스템","M-Bar 시스템","T&H-Bar 시스템","SGP 칸막이"],"a":1,"why":"**M-Bar** 는 보드와 텍스를 나사로 박는 폐쇄형이라 자국이 보여요. **T-Bar** 는 얹는 방식이라 안 보여요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1975,0.1812],"c":[0,0.0208,0.2215,0.2132],"r":1.847,"img":"img/L3/walk/p036_h.jpg"},"parts":[{"b":[0.04,0.22,0.44,0.73],"c":[0.018,0.1835,0.484,0.803],"r":1.0715,"img":"img/L3/walk/p036_21_01.jpg","say":"텍스 판이 줄줄이 붙어 있어요. 줄눈이 아주 가늘어요."},{"b":[0.5,0.28,0.46,0.06],"c":[0.477,0.255,0.506,0.11],"r":8.1778,"img":"img/L3/walk/p036_21_02.jpg","say":"나사못으로 직접 고정해서 아래에서 나사못이 보인다는 설명이에요."},{"b":[0.53,0.58,0.13,0.1],"c":[0.495,0.564,0.2,0.132],"r":2.6936,"img":"img/L3/walk/p036_21_03.jpg","say":"보라색 동그라미 안에 작은 점이 나사못 자국이에요."}]}},{"p":37,"title":"M-Bar 시스템의 구성 요소 한 장에 모으기","terms":["M-Bar","M-Bar 클립","캐링 채널","마이너 채널","스트롱 앵커","행거 클립"],"pass1":[{"kind":"say","lines":["**M-Bar** 천장을 만드는 부품을 그림 하나에 모아 놓은 쪽이에요.","동그라미 안에 부품 사진이 하나씩 들어 있어요.","이름과 생김새를 짝지어 외우면 돼요."]}],"pass2":[{"kind":"compare","head":"그림에 표시된 여섯 가지 부품","cols":["부품","생김새","하는 일"],"rows":[["**스트롱 앵커**","끝이 벌어지는 짧은 금속 못","콘크리트 천장에 박혀 모든 무게를 받아요"],["행거","ㄱ자 꺾인 금속 조각","**달대 볼트(hanger bolt)** 와 **캐링 채널(carrying channel)** 을 이어요"],["**캐링 채널(carrying channel)**","긴 ㄷ자 막대","천장틀의 주 골조예요"],["**마이너 채널(Minor Channel)**","가는 ㄷ자 막대","**캐링 채널(carrying channel)** 과 직교해 묶어요"],["**M-Bar** (엠바)","바닥이 납작한 가는 막대","보드와 텍스를 나사로 받아요"],["**M-Bar 클립**","작은 ㄷ자 집게","**M-Bar** 를 **캐링 채널(carrying channel)** 에 물려요"]]},{"kind":"points","head":"그림 안의 숫자","items":["오른쪽 아래 상자에 300*600 텍스라고 적혀 있어요.","**M-Bar** 간격 300mm가 이 텍스 규격에서 나온 숫자예요.","마이너 채널 클립은 **마이너 채널(Minor Channel)** 을 **캐링 채널(carrying channel)** 에 고정해요.","**행거 클립** 은 그림에서 행거라고 적힌 ㄱ자 부품이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"M-Bar를 캐링 채널에 물려 고정하는 부품의 이름은?","choices":["C/T 클립","행거 클립","M-Bar 클립","마이너 채널 클립"],"a":2,"why":"**M-Bar 클립** 이에요. **행거 클립** 은 볼트와 **캐링 채널(carrying channel)** 을, C/T 클립은 **캐링 채널(carrying channel)** 과 **메인 T-Bar** 를 이어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1253,0.0512],"c":[0,0.0208,0.2,0.0832],"r":4.2735,"img":"img/L3/walk/p037_h.jpg"},"parts":[{"b":[0.26,0.14,0.09,0.05],"c":[0.205,0.11,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p037_22_01.jpg","say":"앵커. 천장 콘크리트에 박는 스트롱 앵커예요."},{"b":[0.39,0.25,0.09,0.05],"c":[0.335,0.22,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p037_22_02.jpg","say":"캐링채널. 천장틀의 굵은 주 골조예요."},{"b":[0.56,0.18,0.06,0.05],"c":[0.49,0.15,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p037_22_03.jpg","say":"엠바. 보드를 받는 가는 막대예요."},{"b":[0.66,0.09,0.09,0.05],"c":[0.605,0.06,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p037_22_04.jpg","say":"엠바 클립. 엠바를 캐링채널에 물려 줘요."},{"b":[0.2,0.43,0.11,0.05],"c":[0.155,0.4,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p037_22_05.jpg","say":"마이너 채널. 캐링채널과 직교로 얹혀요."},{"b":[0.59,0.69,0.11,0.05],"c":[0.545,0.66,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p037_22_06.jpg","say":"300*600 텍스. 이 규격이 M-Bar 간격 300mm의 근거예요."}]}},{"p":38,"title":"M-Bar 시공 방법 8컷으로 한눈에","terms":["M-Bar","캐링 채널","마이너 채널","스트롱 앵커","테두리 몰딩","달대 볼트"],"pass1":[{"kind":"say","lines":["**M-Bar** 천장을 만드는 순서를 그림 8컷으로 보여 줘요.","주문으로 외워요. 위에서 아래로 매달기.","박고, 두르고, 내리고, 굵은 뼈, 가로 보강, 가는 뼈, 판, 완성이에요."]}],"pass2":[{"kind":"steps","head":"그림 8컷의 순서","steps":["1 중심선 설정 및 앵커 시공. **스트롱 앵커** 를 천장에 박아요.","2 **테두리 몰딩** 시공. 벽 둘레에 천장 높이를 그려 줘요.","3 행거볼트 및 행거 시공. **달대 볼트(hanger bolt)** 를 내려요.","4 **캐링 채널(carrying channel)** 시공. 굵은 뼈를 걸어요.","5 **마이너 채널(Minor Channel)** 시공. 가로로 묶어 줘요.","6 엠바 **M-Bar** 시공. 가는 뼈를 걸어요.","7 집텍스(천장재) 시공. 판을 붙여요.","8 집텍스 시공 완료."],"answer":"앵커, 몰딩, 행거, 캐링, 마이너, M-Bar, 텍스 순서예요."},{"kind":"look","walked":1}],"pass3":[{"kind":"english","head":"답안에 쓸 문장: M-Bar 시공 순서","en":"스트롱 앵커, 테두리 몰딩, 행거볼트와 행거, 캐링 채널, 마이너 채널, M-Bar, 수평 맞추기, 석고보드 1ply, 2ply 순으로 시공한다.","ko":"그림 8컷에 수평 맞추기와 보드 두 겹을 더하면 9단계가 돼요.","tip":"주문: 박고, 두르고, 내리고, 굵은 뼈, 묶고, 가는 뼈, 수평, 판, 판."}],"walk":{"head":{"b":[0.0092,0.0368,0.1975,0.2342],"c":[0,0.0208,0.2215,0.2662],"r":1.4793,"img":"img/L3/walk/p038_h.jpg"},"parts":[{"b":[0.07,0.28,0.21,0.28],"c":[0.058,0.264,0.234,0.312],"r":1.3333,"img":"img/L3/walk/p038_21_01.jpg","say":"1번과 2번. 앵커를 박고 벽에 테두리 몰딩을 둘러요."},{"b":[0.5,0.28,0.21,0.28],"c":[0.488,0.264,0.234,0.312],"r":1.3333,"img":"img/L3/walk/p038_21_02.jpg","say":"3번과 4번. 행거볼트를 내리고 캐링 채널을 걸어요."},{"b":[0.07,0.66,0.21,0.28],"c":[0.058,0.644,0.234,0.312],"r":1.3333,"img":"img/L3/walk/p038_21_03.jpg","say":"5번과 6번. 마이너 채널로 묶고 엠바를 걸어요."},{"b":[0.5,0.66,0.21,0.28],"c":[0.488,0.644,0.234,0.312],"r":1.3333,"img":"img/L3/walk/p038_21_04.jpg","say":"7번과 8번. 집텍스를 붙이면 끝이에요."}]}},{"p":39,"title":"M-Bar 시공 1~3단계: 앵커, 테두리 몰딩, 행거볼트","terms":["스트롱 앵커","테두리 몰딩","달대 볼트","행거 클립"],"pass1":[{"kind":"say","lines":["천장 공사의 처음 세 단계를 자세히 보는 쪽이에요.","천장에 박고, 벽에 두르고, 아래로 내리는 순서예요.","여기서 숫자가 세 개 나와요. 900~1,200mm, 1/3 이하, 600mm 이하."]}],"pass2":[{"kind":"steps","head":"1~3단계와 숫자","steps":["1 **스트롱 앵커** 시공. 중심선을 먼저 긋고 앵커를 900~1,200mm 간격으로 박아요.","가장자리 앵커의 최소 간격은 앵커 설치 간격의 1/3 이하로 해요.","중심선을 잡을 때 등라인, 덕트 디퓨저 위치를 미리 고려해요.","2 벽체에 **테두리 몰딩** 시공. 고정못 간격은 600mm 이하예요.","600mm를 넘으면 몰딩이 처져서 수평이 안 맞아요.","3 행거볼트 및 행거 시공. **달대 볼트(hanger bolt)** 를 내리고 **행거 클립** 을 달아요."],"answer":"앵커 900~1,200mm, 가장자리 1/3 이하, 몰딩 고정못 600mm 이하예요."},{"kind":"points","head":"그림 속 작은 글씨까지","items":["몰딩 상부에는 먹매김을 해야 마감이 깨끗해져요.","몰딩 설치가 마감면 높이와 수평을 정확히 맞춰 줘요.","필요하면 창문 위치에 커튼박스를 같이 설치해요.","**달대 볼트(hanger bolt)** 의 너트는 살짝 풀어 두어 높이를 조절할 수 있게 해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"테두리 몰딩의 고정못 간격 기준은?","choices":["300mm 이하","600mm 이하","900mm 이하","1,200mm 이하"],"a":1,"why":"600mm를 넘으면 **테두리 몰딩** 이 처져 수평을 이루지 못해요."},{"kind":"warn","head":"숫자 헷갈리지 않기","items":["900~1,200mm는 **스트롱 앵커** 와 **달대 볼트(hanger bolt)** 간격이에요.","600mm 이하는 **테두리 몰딩** 고정못 간격이에요.","1/3 이하는 가장자리 앵커의 최소 간격이에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1975,0.2342],"c":[0,0.0208,0.2215,0.2662],"r":1.4793,"img":"img/L3/walk/p039_h.jpg"},"parts":[{"b":[0.12,0.35,0.13,0.05],"c":[0.085,0.32,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p039_22_01.jpg","say":"900~1200mm. 앵커 사이 간격이에요."},{"b":[0.24,0.52,0.09,0.05],"c":[0.185,0.49,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p039_22_02.jpg","say":"앵커 설치 간격의 1/3 이하. 가장자리 최소 간격이에요."},{"b":[0.53,0.42,0.09,0.04],"c":[0.475,0.385,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p039_22_03.jpg","say":"600mm 이하. 테두리 몰딩 고정못 간격이에요."},{"b":[0.68,0.56,0.13,0.05],"c":[0.645,0.53,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p039_22_04.jpg","say":"3. 행거볼트 및 행거 시공. 여기까지가 매다는 준비예요."}]}},{"p":40,"title":"M-Bar 시공 4~5단계: 캐링 채널과 마이너 채널","terms":["캐링 채널","마이너 채널","행거 클립"],"pass1":[{"kind":"say","lines":["이제 굵은 뼈와 가로 보강을 거는 단계예요.","4단계는 **캐링 채널(carrying channel)**, 5단계는 **마이너 채널(Minor Channel)** 이에요.","벽체 스터드 방향과 헷갈리지 말라는 주의가 붙어 있어요."]}],"pass2":[{"kind":"steps","head":"4~5단계와 숫자","steps":["4 **캐링 채널(carrying channel)** 을 행거에 걸고 행거핀으로 고정해요.","벽에서 50mm 이하로 띄워서 시작해요.","**캐링 채널(carrying channel)** 은 엇갈리게 시공해야 구조상 튼튼하고 횡력에 안정적이에요.","연결할 때는 반드시 전용 조인트를 써요. 조인트 연결 위치도 엇갈리게 해요.","5 **마이너 채널(Minor Channel)** 을 **캐링 채널(carrying channel)** 상부에 2,000~3,000mm 간격으로 설치해요.","교차부는 마이너 채널 클립으로 고정해요."],"answer":"캐링은 벽에서 50mm 이하, 마이너는 2,000~3,000mm 간격이에요."},{"kind":"bg","src":"배경 지식","lines":["엇갈리게 시공한다는 말은 이음매가 한 줄로 나란히 오지 않게 한다는 뜻이에요.","이음매가 한 줄로 모이면 그 줄이 약한 선이 되어 잘 휘어요.","석고보드 1ply와 2ply를 엇갈리게 붙이는 이유도 같아요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"캐링 채널을 벽에서 띄우는 거리 기준은?","choices":["50mm 이하","300mm 이하","600mm 이하","900mm 이하"],"a":0,"why":"그림에 50mm 이하로 적혀 있어요. 방음 공사의 벽체 중간 공간 50mm와 숫자가 같으니 헷갈리지 않게 해요."},{"kind":"warn","head":"시험에 잘 걸리는 함정","items":["**캐링 채널(carrying channel)** 방향을 벽체 스터드 방향과 헷갈리지 않게 해요.","**마이너 채널(Minor Channel)** 은 본문에서는 약 3,000mm, 시공 그림에서는 2,000~3,000mm예요.","**마이너 채널(Minor Channel)** 은 **캐링 채널(carrying channel)** 위에 올라가요. 아래가 아니에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.7791,0.1412],"c":[0,0.0208,0.857,0.1732],"r":8.7965,"img":"img/L3/walk/p040_h.jpg"},"parts":[{"b":[0.37,0.18,0.28,0.04],"c":[0.356,0.145,0.308,0.11],"r":4.9778,"img":"img/L3/walk/p040_22_01.jpg","say":"벽체 스터드 방향과 헷갈리지 않게 주의하라는 빨간 글씨예요."},{"b":[0.08,0.62,0.13,0.05],"c":[0.045,0.59,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p040_22_02.jpg","say":"50mm 이하. 캐링 채널을 벽에서 띄우는 거리예요."},{"b":[0.77,0.19,0.13,0.05],"c":[0.735,0.16,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p040_22_03.jpg","say":"마이너 채널 설치 간격 2,000~3,000mm 라고 적혀 있어요."},{"b":[0.38,0.42,0.28,0.05],"c":[0.366,0.39,0.308,0.11],"r":4.9778,"img":"img/L3/walk/p040_22_04.jpg","say":"캐링채널은 엇갈리게 시공해야 구조상 튼튼하다는 설명이에요."}]}},{"p":41,"title":"M-Bar 시공 6단계: 엠바 걸기, 간격 300mm","terms":["M-Bar","M-Bar 클립","캐링 채널","테두리 몰딩"],"pass1":[{"kind":"say","lines":["드디어 가는 뼈, **M-Bar** 를 거는 단계예요.","간격은 300mm예요. 이 숫자를 꼭 외워요.","**M-Bar 클립** 으로 **캐링 채널(carrying channel)** 에 물려요."]}],"pass2":[{"kind":"points","head":"6단계에서 지켜야 할 것","items":["**M-Bar** 는 300mm 간격으로 설치하고 **M-Bar 클립** 으로 **캐링 채널(carrying channel)** 에 고정해요.","**M-Bar 클립** 을 한쪽 방향으로만 고정하면 횡력에 뒤틀릴 수 있어요. 그래서 엇갈림 시공을 해요.","**M-Bar** 를 이어 갈 때는 연결 부분이 서로 엇갈리게 해요.","이을 때는 반드시 엠바 조인트를 써요.","**M-Bar 클립** 이 **캐링 채널(carrying channel)** 과 꽉 물리도록 고정해야 해요.","그림 왼쪽 아래 확대에 9.5mm(집텍스 두께)가 적혀 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"M-Bar의 설치 간격으로 그림에 적힌 숫자는?","choices":["300mm","450mm","610mm","900mm"],"a":0,"why":"**M-Bar** 는 300mm예요. 450mm는 벽체 스터드, 610mm는 **메인 T-Bar** 와 퍼링 채널이에요."}],"walk":{"head":{"b":[0.0092,0.0368,0.2158,0.252],"c":[0,0.0208,0.2398,0.284],"r":1.5011,"img":"img/L3/walk/p041_h.jpg"},"parts":[{"b":[0.17,0.45,0.16,0.05],"c":[0.15,0.42,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p041_21_01.jpg","say":"300mm, 300mm, 300mm. 엠바 간격이 반복해서 적혀 있어요."},{"b":[0.39,0.51,0.16,0.06],"c":[0.37,0.485,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p041_21_02.jpg","say":"엠바 클립 엇갈림 시공. 한쪽으로만 고정하면 뒤틀려요."},{"b":[0.85,0.58,0.11,0.06],"c":[0.8,0.555,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p041_21_03.jpg","say":"엠바 연결 시 반드시 엠바 조인트를 쓴다는 설명이에요."},{"b":[0.12,0.87,0.08,0.06],"c":[0.06,0.845,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p041_21_04.jpg","say":"9.5mm. 집텍스(천장재) 두께예요."},{"b":[0.12,0.68,0.06,0.04],"c":[0.05,0.645,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p041_21_05.jpg","say":"몰딩. 벽 둘레에 미리 둘러 둔 테두리 몰딩이에요."}]}},{"p":42,"title":"M-Bar 시공 7~9단계: 수평 맞추기와 석고보드 두 겹","terms":["M-Bar","1ply","2ply","캐링 채널"],"pass1":[{"kind":"say","lines":["마지막 세 단계예요. 수평을 맞추고 보드를 두 겹 붙여요.","여기서 나오는 숫자는 300mm 이상과 3mm예요.","그리고 아주 중요한 금지 사항이 하나 있어요. 타카 사용 금지."]}],"pass2":[{"kind":"steps","head":"7~9단계","steps":["7 천장틀 수평 맞추기. 레이저 수평기로 확인한 뒤 행거와 너트를 채결해 고정해요.","8 석고보드 **1ply** 시공. 바탕이 되는 첫 겹이에요.","9 석고보드 **2ply** 시공. 마감이 되는 둘째 겹이에요.","**1ply** 와 **2ply** 의 경계면은 300mm 이상 엇갈리게 시공해요."],"answer":"수평 먼저, 그다음 1ply, 그다음 2ply예요."},{"kind":"warn","head":"그림의 빨간 X 표시 세 가지","items":["나사못 고정은 O, 타카 사용은 절대 금지예요. 석고보드가 떨어질 수 있어요.","석고보드 조인트 부위를 3mm 이상 벌리는 것은 금지예요.","**1ply** 와 **2ply** 경계면이 겹치는 것도 금지예요. 300mm 이상 엇갈려요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"문제은행 l23","q":"천장 석고보드 1ply와 2ply를 시공할 때 경계면은 몇 mm 이상 엇갈리게 해야 하는가?","qko":"보드 두 겹의 이음선이 얼마나 떨어져야 하는지 묻는 문제예요.","solve":["**1ply** 와 **2ply** 의 이음선이 한 줄로 겹치면 그 줄이 약해져요.","슬라이드 그림에 300mm 이상 엇갈리게 하라고 적혀 있어요.","고정은 나사못으로 하고 타카는 쓰지 않아요."],"answer":"300mm 이상"},{"kind":"check","q":"천장 석고보드를 고정할 때 절대 쓰면 안 되는 것은?","choices":["나사못","타카","본드","조인트 컴파운드"],"a":1,"why":"그림에 타카 사용 절대 금지라고 적혀 있어요. 석고보드가 떨어질 수 있어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1507,0.0912],"c":[0,0.0208,0.2,0.1232],"r":2.886,"img":"img/L3/walk/p042_h.jpg"},"parts":[{"b":[0.04,0.25,0.13,0.05],"c":[0.005,0.22,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p042_22_01.jpg","say":"7. 천장틀 수평 맞추기. 레이저 수평기를 써요."},{"b":[0.36,0.13,0.13,0.05],"c":[0.325,0.1,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p042_22_02.jpg","say":"8. 석고보드 1ply 시공이에요."},{"b":[0.72,0.13,0.13,0.05],"c":[0.685,0.1,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p042_22_03.jpg","say":"9. 석고보드 2ply 시공이에요."},{"b":[0.68,0.42,0.24,0.07],"c":[0.668,0.4,0.264,0.11],"r":4.2667,"img":"img/L3/walk/p042_22_04.jpg","say":"1ply와 2ply 경계면은 300mm 이상 엇갈리게 하라는 주의예요."},{"b":[0.83,0.62,0.13,0.06],"c":[0.795,0.595,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p042_22_05.jpg","say":"타카 사용 절대 금지. 석고보드가 떨어질 수 있어요."},{"b":[0.68,0.86,0.28,0.06],"c":[0.666,0.835,0.308,0.11],"r":4.9778,"img":"img/L3/walk/p042_22_06.jpg","say":"석고보드 조인트 부위 3mm 이상 이격 금지예요."}]}},{"p":43,"title":"M-Bar 참고 영상 안내","terms":["M-Bar"],"pass1":[{"kind":"say","lines":["**M-Bar** 시스템을 눈으로 볼 수 있는 영상 링크만 있는 쪽이에요.","천장 구조, 천장 석고텍스 종류, 설치 과정 세 가지예요.","외울 내용은 없어요. 앞 쪽들의 순서를 다시 떠올리고 넘어가요."]}],"pass2":[{"kind":"points","head":"이 쪽에 있는 것","items":["경량 철골 천장 **M-Bar** 시스템 참고 영상 링크 세 개예요.","천장 구조 영상, 천장 석고텍스 종류 영상, 설치 과정 영상이에요.","시험에 나올 내용은 없지만 순서가 머리에 안 그려지면 보면 좋아요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":{"b":[0.0092,0.0368,0.1975,0.1412],"c":[0,0.0208,0.2215,0.1732],"r":2.2735,"img":"img/L3/walk/p043_h.jpg"},"parts":[{"b":[0.03,0.18,0.13,0.05],"c":[0,0.15,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p043_21_01.jpg","say":"1) M-Bar 시스템, 별표가 붙어 있어요. 여기까지가 M-Bar 단원이에요."},{"b":[0.03,0.23,0.09,0.04],"c":[0,0.195,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p043_21_02.jpg","say":"시공 방법. 앞 여섯 쪽에서 본 9단계를 말해요."},{"b":[0.04,0.3,0.22,0.05],"c":[0.028,0.27,0.244,0.11],"r":3.9434,"img":"img/L3/walk/p043_21_03.jpg","say":"경량 철골 천장 M-Bar 시스템 참고 영상이라는 안내예요."},{"b":[0.04,0.35,0.44,0.14],"c":[0.018,0.334,0.484,0.172],"r":5.0026,"img":"img/L3/walk/p043_21_04.jpg","say":"링크 세 개예요. 천장 구조, 천장 석고텍스 종류, 설치 과정 영상이에요."}]}},{"p":44,"title":"T-Bar 시스템: 격자 틀 위에 패널을 얹는 천장","terms":["T-Bar","메인 T-Bar","C/T 클립","캐링 채널","마이톤","M-Bar"],"pass1":[{"kind":"say","lines":["이번에는 **T-Bar** 시스템이에요.","T자 모양 막대를 격자로 짜고, 그 날개 위에 판을 얹어요.","**M-Bar** 는 박는 천장, **T-Bar** 는 얹는 천장이에요."]},{"kind":"analogy","head":"얹는 천장은 서랍장 위 쟁반","scene":"격자 모양 선반을 만들어 두고 그 위에 쟁반을 하나씩 올려 놓는다고 생각해요.","map":[["격자 선반","**T-Bar**"],["올려 놓는 쟁반","규격 천장 패널"],["쟁반 하나를 들어 올리기","천장 속 설비 점검"]]}],"pass2":[{"kind":"points","head":"T-Bar 시스템의 특징","items":["**T-Bar** 형태의 천장틀 위에 규격화된 천장 패널을 얹어 설치해요.","모듈화된 부재와 패널이라 시공이 빠르고 천장 내부 설비 점검과 유지관리가 쉬워요.","패널을 개별로 들어 올려 탈착할 수 있어 별도의 점검구를 최소화할 수 있어요.","천장 디자인과 노출 형태에 따라 일반형, 라인형 등 여러 형태가 있어요."]},{"kind":"steps","head":"이 쪽이 말하는 시공 방법","steps":["시공 기준선을 먼저 설정해요.","**메인 T-Bar** 를 천장 패널 규격에 맞추어 배치해요.","**캐링 채널(carrying channel)** 과 직교하도록 설치한 뒤 **C/T 클립** 으로 고정해요.","설치 간격은 일반 T-bar용이 610mm예요.","천장틀 설치 후 수평과 직각을 확인해요.","흡음텍스, 미네랄울 패널 등 규격에 맞는 천장재를 올려 마감해요."],"answer":"기준선, 메인 T-Bar 610mm, C/T 클립, 수평 확인, 패널 얹기예요."},{"kind":"compare","head":"M-Bar와 T-Bar 한 줄 비교","cols":["","**M-Bar**","**T-Bar**"],"rows":[["고정 방법","나사로 박는다","격자 위에 올려놓는다"],["천장 종류","폐쇄형","탈착형"],["간격","300mm","610mm (일반 T-bar용)"],["점검구","따로 필요","패널을 들면 되어 최소화"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"문제은행 l23","q":"일반 T-bar용 T-Bar의 설치 간격은?","qko":"T-Bar를 몇 mm 간격으로 다는지 묻는 문제예요.","solve":["**T-Bar** 는 천장재 크기에 맞춰 간격을 정해요.","가장 많이 쓰는 **마이톤** 이 600x600mm예요.","그래서 일반 T-bar용은 610mm 간격으로 설치해요."],"answer":"610mm"},{"kind":"warn","head":"헷갈리는 짝","items":["**M-Bar** 는 박는다, 300 간격, 폐쇄형이에요.","**T-Bar** 는 얹는다, 610 간격, 탈착형이에요.","610mm는 퍼링 채널 간격과 같은 숫자예요. 같이 외우면 편해요.","**마이톤** 은 600x600, 집톤은 603x603이에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.5579,0.2812],"c":[0,0.0208,0.6137,0.3132],"r":3.4835,"img":"img/L3/walk/p044_h.jpg"},"parts":[{"b":[0.03,0.32,0.42,0.05],"c":[0.009,0.29,0.462,0.11],"r":7.4667,"img":"img/L3/walk/p044_23_01.jpg","say":"T-Bar 틀 위에 규격화된 천장 패널을 얹는다는 정의예요."},{"b":[0.03,0.45,0.55,0.05],"c":[0.0025,0.4139,0.605,0.1222],"r":8.8016,"img":"img/L3/walk/p044_23_02.jpg","say":"패널을 들어 올려 탈착할 수 있어 점검구를 최소화한다는 장점이에요."},{"b":[0.03,0.55,0.72,0.05],"c":[0,0.495,0.792,0.16],"r":8.8,"img":"img/L3/walk/p044_23_03.jpg","say":"캐링채널과 직교하게 설치한 뒤 C/T 클립으로 고정한다는 문장이에요."},{"b":[0.18,0.62,0.13,0.05],"c":[0.145,0.59,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p044_23_04.jpg","say":"610mm 간격. 일반 T-bar용 설치 간격이에요."},{"b":[0.33,0.61,0.3,0.05],"c":[0.315,0.58,0.33,0.11],"r":5.3333,"img":"img/L3/walk/p044_23_05.jpg","say":"마이톤 사이즈가 600*600이라 간격이 610mm가 된다는 설명이에요."},{"b":[0.63,0.7,0.3,0.09],"c":[0.615,0.684,0.33,0.122],"r":4.8087,"img":"img/L3/walk/p044_23_06.jpg","say":"M-Bar는 나사로 고정하는 폐쇄형, T-Bar는 올려놓는 탈착형이라는 정리 상자예요."}]}},{"p":45,"title":"T-Bar 상세도와 T-Bar 부재 네 가지","terms":["T-Bar","메인 T-Bar","크로스 T-Bar","C/T 클립","캐링 채널","마이너 채널","달대 볼트"],"pass1":[{"kind":"say","lines":["**T-Bar** 천장을 잘라 본 그림과 **T-Bar** 제품 사진이 있는 쪽이에요.","부재마다 규격이 괄호 안에 적혀 있어요.","**T-Bar** 에는 높이가 다른 네 가지 제품이 있어요."]}],"pass2":[{"kind":"compare","head":"상세도에 적힌 부재 규격","cols":["부재","규격 또는 간격"],"rows":[["행어볼트 (**달대 볼트(hanger bolt)**)","9mm, @900"],["**마이너 채널(Minor Channel)**","19x10x1.2T"],["**캐링 채널(carrying channel)**","38X12X1.2T"],["**메인 T-Bar** (메인 티바)","25x38x0.4T"],["**크로스 T-Bar** (크로스 티바)","25x25x0.4T"],["**C/T 클립**","캐링채널과 메인 티바를 체결"]]},{"kind":"points","head":"티바(T-bar)의 종류 네 가지","items":["25mm 스틸 티바. 날개 보이는 면이 25mm로 가장 넓어요.","15mm 스틸 티바. 날개가 15mm로 좁아요.","15mm 오메가 티바.","15mm 울트라 티바.","아래에서 보이는 줄눈 폭이 달라져서 천장 인상이 달라져요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"캐링 채널과 메인 T-Bar를 체결하는 부속은?","choices":["M-Bar 클립","행거 클립","C/T 클립","마이너 채널 클립"],"a":2,"why":"**C/T 클립** 이에요. Carrying 과 T-Bar 의 머리글자를 딴 이름이에요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1975,0.143],"c":[0,0.0208,0.2215,0.175],"r":2.2502,"img":"img/L3/walk/p045_h.jpg"},"parts":[{"b":[0.31,0.2,0.13,0.05],"c":[0.275,0.17,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p045_22_01.jpg","say":"9mm 행어볼트 @900. 매다는 볼트예요."},{"b":[0.13,0.24,0.11,0.06],"c":[0.085,0.215,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p045_22_02.jpg","say":"마이너 채널 19x10x1.2T예요."},{"b":[0.23,0.65,0.11,0.06],"c":[0.185,0.625,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p045_22_03.jpg","say":"캐링채널 38X12X1.2T예요."},{"b":[0.36,0.65,0.09,0.05],"c":[0.305,0.62,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p045_22_04.jpg","say":"C/T 클립. 캐링채널과 메인 티바를 물려 줘요."},{"b":[0.42,0.65,0.13,0.06],"c":[0.385,0.625,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p045_22_05.jpg","say":"메인 티바 25x38x0.4T예요."},{"b":[0.14,0.65,0.09,0.05],"c":[0.085,0.62,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p045_22_06.jpg","say":"크로스 티바 25x25x0.4T예요."}]}},{"p":46,"title":"25mm T-bar와 오메가 T-bar 천장 사진","terms":["T-Bar"],"pass1":[{"kind":"say","lines":["**T-Bar** 두 종류로 마감한 천장을 아래에서 찍은 사진이에요.","왼쪽은 25mm T-bar 시스템, 오른쪽은 오메가 T-bar 시스템이에요.","격자 줄눈이 보이는 폭과 느낌이 다른 것을 보면 돼요."]}],"pass2":[{"kind":"points","head":"두 사진 비교","items":["25mm T-bar 시스템은 격자 줄이 조금 더 굵게 보여요.","오메가 T-bar 시스템은 줄이 더 가늘고 단정해 보여요.","둘 다 판을 얹는 **T-Bar** 방식이라 아래에서 나사못이 안 보여요.","천장 등기구도 같은 격자 규격에 맞춰 들어가 있어요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":{"b":[0.0092,0.0368,0.1975,0.1876],"c":[0,0.0208,0.2215,0.2196],"r":1.7932,"img":"img/L3/walk/p046_h.jpg"},"parts":[{"b":[0.12,0.3,0.37,0.44],"c":[0.1015,0.278,0.407,0.484],"r":1.4949,"img":"img/L3/walk/p046_21_01.jpg","say":"25mm T-bar 시스템 천장이에요. 줄눈이 또렷해요."},{"b":[0.5,0.3,0.37,0.44],"c":[0.4815,0.278,0.407,0.484],"r":1.4949,"img":"img/L3/walk/p046_21_02.jpg","say":"오메가 T-bar 시스템 천장이에요. 줄눈이 더 가늘어요."}]}},{"p":47,"title":"T-Bar 시스템의 구성 요소와 집톤 규격","terms":["T-Bar","메인 T-Bar","크로스 T-Bar","C/T 클립","캐링 채널","집톤","스트롱 앵커"],"pass1":[{"kind":"say","lines":["**T-Bar** 천장을 만드는 부품을 모아 놓은 쪽이에요.","앵커, 행거, **캐링 채널(carrying channel)**, **메인 T-Bar**, **크로스 T-Bar**, **C/T 클립** 이에요.","오른쪽 아래에는 **집톤(Gyptone)** 천장재 규격표가 있어요."]}],"pass2":[{"kind":"compare","head":"그림에 표시된 부품","cols":["부품","하는 일"],"rows":[["앵커 (**스트롱 앵커**)","콘크리트 천장에 박혀 무게를 받아요"],["행거","볼트와 **캐링 채널(carrying channel)** 을 이어요"],["**캐링 채널(carrying channel)**","천장틀의 주 골조예요"],["**메인 T-Bar** (메인티바)","610mm 간격의 큰 줄기예요"],["**크로스 T-Bar** (크로스 티바)","메인 사이에 끼워 격자를 만들어요"],["**C/T 클립**","**캐링 채널(carrying channel)** 과 **메인 T-Bar** 를 물려요"],["보랄 **집톤(Gyptone)**","격자 위에 얹는 천장재예요"]]},{"kind":"points","head":"집톤(Gyptone) 규격표","items":["제품군은 페인티드 미나톤, 어쿠스틱 페인티드, 비닐껠레포일 세 가지예요.","세 제품 모두 두께 9mm예요.","세 제품 모두 규격 603 X 603(mm)예요.","**마이톤** 600x600과 **집톤(Gyptone)** 603x603을 짝으로 외워요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"T-Bar용 천장재 집톤의 규격은?","choices":["600 X 600mm, 두께 12mm","603 X 603mm, 두께 9mm","300 X 600mm, 두께 9.5mm","900 X 1,800mm, 두께 9.5mm"],"a":1,"why":"**집톤(Gyptone)** 은 603 X 603mm, 두께 9mm예요. 600x600은 **마이톤**, 300x600은 M-Bar용 텍스, 900x1,800은 석고보드예요."}],"walk":{"head":null,"parts":[{"b":[0.28,0.09,0.06,0.05],"c":[0.21,0.06,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p047_22_01.jpg","say":"앵커. 천장에 박는 스트롱 앵커예요."},{"b":[0.85,0.05,0.06,0.05],"c":[0.78,0.02,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p047_22_02.jpg","say":"행거. 볼트와 캐링채널을 이어요."},{"b":[0.69,0.21,0.06,0.05],"c":[0.62,0.18,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p047_22_03.jpg","say":"캐링채널. 굵은 주 골조예요."},{"b":[0.82,0.5,0.06,0.05],"c":[0.75,0.47,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p047_22_04.jpg","say":"메인티바. 610mm 간격의 큰 줄기예요."},{"b":[0.73,0.57,0.06,0.05],"c":[0.66,0.54,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p047_22_05.jpg","say":"크로스 티바. 메인 사이에 끼워요."},{"b":[0.28,0.78,0.06,0.05],"c":[0.21,0.75,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p047_22_06.jpg","say":"C/T 클립. 캐링채널과 메인티바를 물려 줘요."}]}},{"p":48,"title":"T-Bar 시공 방법 8컷: 3번까지는 M-Bar와 같다","terms":["T-Bar","메인 T-Bar","크로스 T-Bar","캐링 채널","스트롱 앵커","테두리 몰딩","집톤"],"pass1":[{"kind":"say","lines":["**T-Bar** 천장 시공 순서를 그림 8컷으로 보여 줘요.","앞의 세 컷은 **M-Bar** 와 똑같아요.","달라지는 것은 4번부터예요."]}],"pass2":[{"kind":"steps","head":"그림 8컷의 순서","steps":["1 중심선 설정 및 앵커 시공. **스트롱 앵커** 예요.","2 **테두리 몰딩** 시공.","3 행거볼트 및 행거 시공. 여기까지 **M-Bar** 와 같아요.","4 **캐링 채널(carrying channel)** 시공.","5 메인 티바(**메인 T-Bar**) 시공.","6 크로스 티바(**크로스 T-Bar**) 시공.","7 **집톤(Gyptone)** (천장재) 시공.","8 **집톤(Gyptone)** 시공 완료."],"answer":"앵커, 몰딩, 행거, 캐링, 메인 T-Bar, 크로스 T-Bar, 천장재 순서예요."},{"kind":"compare","head":"M-Bar 순서와 T-Bar 순서 나란히 보기","cols":["단계","**M-Bar**","**T-Bar**"],"rows":[["1~3","앵커, 몰딩, 행거","앵커, 몰딩, 행거 (같음)"],["4","**캐링 채널(carrying channel)**","**캐링 채널(carrying channel)** 과 **메인 T-Bar**"],["5","**마이너 채널(Minor Channel)**","**크로스 T-Bar** 끼우기"],["6~7","**M-Bar**, 수평","수평 맞추기"],["마감","석고보드 1ply, 2ply","텍스 천장재 얹기"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"english","head":"답안에 쓸 문장: T-Bar 시공 순서","en":"스트롱 앵커, 테두리 몰딩, 행거볼트와 행거, 캐링 채널과 메인 T-Bar, 크로스 T-Bar, 수평 맞추기, 텍스 천장재 순으로 시공한다.","ko":"3번까지는 M-Bar와 같고, 4번부터 T-Bar로 갈라져요.","tip":"M-Bar는 9단계, **T-Bar** 는 7단계로 기억해요."},{"kind":"check","q":"T-Bar 시공에서 M-Bar와 순서가 같은 구간은?","choices":["1번부터 3번까지","1번부터 5번까지","4번부터 6번까지","처음부터 끝까지 다르다"],"a":0,"why":"슬라이드에 3번까지는 M-bar 설치 방법과 동일하다고 적혀 있어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1975,0.2342],"c":[0,0.0208,0.2215,0.2662],"r":1.4793,"img":"img/L3/walk/p048_h.jpg"},"parts":[{"b":[0.07,0.28,0.21,0.28],"c":[0.058,0.264,0.234,0.312],"r":1.3333,"img":"img/L3/walk/p048_22_01.jpg","say":"1번과 2번. 앵커와 테두리 몰딩. M-Bar와 같아요."},{"b":[0.5,0.28,0.21,0.28],"c":[0.488,0.264,0.234,0.312],"r":1.3333,"img":"img/L3/walk/p048_22_02.jpg","say":"3번과 4번. 행거와 캐링채널이에요."},{"b":[0.07,0.66,0.21,0.28],"c":[0.058,0.644,0.234,0.312],"r":1.3333,"img":"img/L3/walk/p048_22_03.jpg","say":"5번과 6번. 메인 티바와 크로스 티바예요."},{"b":[0.5,0.66,0.21,0.28],"c":[0.488,0.644,0.234,0.312],"r":1.3333,"img":"img/L3/walk/p048_22_04.jpg","say":"7번과 8번. 집톤을 얹으면 완성이에요."}]}},{"p":49,"title":"T-Bar 시공 1~3단계: M-Bar와 똑같은 구간","terms":["T-Bar","M-Bar","스트롱 앵커","테두리 몰딩","달대 볼트"],"pass1":[{"kind":"say","lines":["**T-Bar** 시공을 자세히 보는 첫 쪽이에요.","1번부터 3번까지는 **M-Bar** 설치 방법과 완전히 같아요.","천장에 박고, 벽에 두르고, 아래로 내리는 순서예요."]}],"pass2":[{"kind":"steps","head":"1~3단계와 숫자","steps":["1 **스트롱 앵커** 시공. 중심선을 긋고 900~1,200mm 간격으로 박아요.","가장자리 최소 간격은 앵커 설치 간격의 1/3 이하예요.","중심선을 잡을 때 등라인, 덕트 디퓨저 위치를 고려해요.","2 벽체에 **테두리 몰딩** 시공. 고정못 간격 600mm 이하예요.","3 행거볼트 및 행거 시공. **달대 볼트(hanger bolt)** 를 내려요.","볼트를 살짝 풀어 두어 나중에 높이를 조절할 수 있게 해요."],"answer":"여기까지는 M-Bar와 T-Bar가 똑같아요."},{"kind":"points","head":"T-Bar 쪽에만 더 적힌 주의","items":["고온다습한 조건에서는 습기에 대한 환기나 공조로 변색과 변형의 원인을 예방해요.","천장재를 얹는 **T-Bar** 는 패널이 습기를 먹으면 처질 수 있어서 이 주의가 붙어요.","**테두리 몰딩** 상부에는 먹매김을 해야 마감이 깨끗해져요.","필요하면 창문 위치에 커튼박스를 같이 설치해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"M-Bar와 T-Bar의 시공 순서가 같은 구간은 몇 번까지인가요?","choices":["1번까지","3번까지","5번까지","7번까지"],"a":1,"why":"슬라이드에 3번까지는 **M-Bar** 설치 방법과 동일하다고 적혀 있어요. 앵커, 몰딩, 행거까지예요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1975,0.2112],"c":[0,0.0208,0.2215,0.2432],"r":1.6192,"img":"img/L3/walk/p049_h.jpg"},"parts":[{"b":[0.12,0.35,0.13,0.05],"c":[0.085,0.32,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p049_22_01.jpg","say":"900~1200mm. 앵커 사이 간격이에요."},{"b":[0.26,0.51,0.09,0.06],"c":[0.205,0.485,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p049_22_02.jpg","say":"앵커 설치 간격의 1/3 이하. 가장자리 최소 간격이에요."},{"b":[0.55,0.42,0.09,0.04],"c":[0.495,0.385,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p049_22_03.jpg","say":"600mm 이하. 테두리 몰딩 고정못 간격이에요."},{"b":[0.68,0.25,0.19,0.05],"c":[0.668,0.22,0.214,0.11],"r":3.4586,"img":"img/L3/walk/p049_22_04.jpg","say":"3번까지는 M-bar 설치 방법과 동일하다는 안내 상자예요."},{"b":[0.09,0.73,0.28,0.09],"c":[0.076,0.714,0.308,0.122],"r":4.4882,"img":"img/L3/walk/p049_22_05.jpg","say":"고온다습한 조건에서 환기와 공조로 변색, 변형을 예방하라는 설명이에요."}]}},{"p":50,"title":"T-Bar 시공 4~6단계: 메인, 크로스, 수평","terms":["T-Bar","메인 T-Bar","크로스 T-Bar","C/T 클립","캐링 채널"],"pass1":[{"kind":"say","lines":["여기서부터 **T-Bar** 만의 순서가 시작돼요.","굵은 뼈를 달고, 큰 줄기를 놓고, 짧은 줄기를 끼워 격자를 만들어요.","외울 숫자는 610mm예요."]}],"pass2":[{"kind":"steps","head":"4~6단계","steps":["4 **캐링 채널(carrying channel)** 및 **메인 T-Bar** 시공. **C/T 클립** 으로 체결해요.","5 **크로스 T-Bar** 를 끼워서 시공해요. 간격은 610mm x 610mm 격자가 돼요.","**크로스 T-Bar** 는 한쪽을 먼저 넣고 비스듬히 돌려 나머지를 **메인 T-Bar** 에 끼워요.","6 천장틀 수평 맞추기. 수평을 맞춘 뒤 행거와 너트를 채결해 고정해요."],"answer":"캐링과 메인, 크로스 끼우기, 수평 순서예요."},{"kind":"compare","head":"그림 왼쪽 아래: 티바(T-bar)의 종류","cols":["이름","보이는 면 폭"],"rows":[["스틸 티바","25mm"],["스틸 티바","15mm"],["오메가 티바","15mm"],["울트라 티바","15mm"]]},{"kind":"bg","src":"배경 지식","lines":["아래에서 보이는 T자 날개 폭이 25mm냐 15mm냐에 따라 천장 줄눈의 굵기가 달라져요.","줄눈이 가늘수록 천장이 더 깔끔하고 넓어 보여요.","그래서 같은 **T-Bar** 라도 제품을 고르는 일이 디자인 결정이 돼요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"크로스 T-Bar를 끼웠을 때 만들어지는 격자 한 칸의 크기는?","choices":["300mm x 300mm","450mm x 450mm","610mm x 610mm","900mm x 900mm"],"a":2,"why":"**메인 T-Bar** 가 610mm 간격이라 **크로스 T-Bar** 를 끼우면 610mm x 610mm 격자가 돼요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**C/T 클립** 은 **캐링 채널(carrying channel)** 과 **메인 T-Bar** 를 잇는 부속이에요.","M-Bar 클립과 이름이 비슷하니 짝을 정확히 외워요.","**크로스 T-Bar** 는 캐링 채널이 아니라 **메인 T-Bar** 에 끼워요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1253,0.0551],"c":[0,0.0208,0.2,0.0871],"r":4.0822,"img":"img/L3/walk/p050_h.jpg"},"parts":[{"b":[0.03,0.34,0.11,0.09],"c":[0,0.324,0.2,0.122],"r":2.9144,"img":"img/L3/walk/p050_23_01.jpg","say":"4. 캐링 채널 및 메인 T-bar 시공이에요."},{"b":[0.12,0.46,0.22,0.04],"c":[0.108,0.425,0.244,0.11],"r":3.9434,"img":"img/L3/walk/p050_23_02.jpg","say":"캐링채널과 메인 티바를 C/T 클립을 이용해 체결한다는 설명이에요."},{"b":[0.41,0.1,0.16,0.05],"c":[0.39,0.07,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p050_23_03.jpg","say":"5. 크로스 T-bar 끼워서 시공이에요."},{"b":[0.41,0.44,0.09,0.04],"c":[0.355,0.405,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p050_23_04.jpg","say":"610mm, 610mm. 격자 한 칸의 크기예요."},{"b":[0.72,0.16,0.13,0.05],"c":[0.685,0.13,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p050_23_05.jpg","say":"6. 천장틀 수평 맞추기예요."},{"b":[0.13,0.57,0.12,0.04],"c":[0.09,0.535,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p050_23_06.jpg","say":"티바(T-bar)의 종류. 25mm와 15mm 제품이 있어요."}]}},{"p":51,"title":"T-Bar 시공 7단계: 텍스 천장재 얹기","terms":["T-Bar","메인 T-Bar","크로스 T-Bar","집톤"],"pass1":[{"kind":"say","lines":["마지막 단계, 판을 얹는 순서예요.","**집톤(Gyptone)** 같은 천장재를 격자 위에 올려요.","여기서 중요한 규칙이 하나 있어요. 전기와 설비가 다 끝난 뒤에 얹어요."]}],"pass2":[{"kind":"points","head":"7단계에서 지킬 것","items":["천장재는 **메인 T-Bar** 와 **크로스 T-Bar** 사이로 비스듬히 집어 넣어요.","그다음 티바(T-bar) 날개면에 걸치도록 내려놓아요.","**집톤(Gyptone)** 시공 시 배면의 화살표 방향을 지켜야 해요.","티바 설치 후 천장재의 오염을 막으려고 전기 설비 등 모든 공정이 완료된 뒤에 얹어요."]},{"kind":"compare","head":"오른쪽 위 그림: 천장재 크기와 메인 티바 간격","cols":["치수","무엇"],"rows":[["603mm","**집톤(Gyptone)** 판 한 장의 크기"],["610mm","**메인 T-Bar** 의 중심 사이 간격"],["25mm","티바 날개의 폭"],["38mm","티바의 높이"],["9mm","천장재 두께"],["6.5mm","티바 기둥의 두께 표시"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"문제은행 l23","q":"T-Bar 천장에서 천장재(텍스)는 언제 설치하는가?","qko":"판을 언제 올리는지 묻는 문제예요.","solve":["천장 속에는 전기 배선, 설비 배관, 등기구가 들어가요.","판을 먼저 얹으면 그 위 작업을 하려고 다시 다 걷어내야 해요.","슬라이드는 전기 설비 등 모든 공정이 완료된 후에 시공한다고 적어요."],"answer":"전기와 설비 등 모든 공정이 끝난 뒤에 설치한다"},{"kind":"check","q":"집톤 판 한 장의 크기와 메인 T-Bar 간격으로 맞는 짝은?","choices":["600mm와 610mm","603mm와 610mm","603mm와 600mm","610mm와 610mm"],"a":1,"why":"판은 603mm, **메인 T-Bar** 중심 간격은 610mm예요. 틈이 있어야 판이 들어가요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1975,0.1812],"c":[0,0.0208,0.2215,0.2132],"r":1.847,"img":"img/L3/walk/p051_h.jpg"},"parts":[{"b":[0.16,0.22,0.13,0.05],"c":[0.125,0.19,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p051_22_01.jpg","say":"7. 텍스 천장재 설치 단계 이름이에요."},{"b":[0.16,0.6,0.3,0.06],"c":[0.145,0.575,0.33,0.11],"r":5.3333,"img":"img/L3/walk/p051_22_02.jpg","say":"메인 티바와 크로스 티바 사이로 비스듬히 넣어 날개면에 걸치게 하라는 설명이에요."},{"b":[0.63,0.39,0.13,0.05],"c":[0.595,0.36,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p051_22_03.jpg","say":"603mm. 집톤 판 한 장의 크기예요."},{"b":[0.63,0.42,0.13,0.05],"c":[0.595,0.39,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p051_22_04.jpg","say":"610mm. 메인 티바 사이 간격이에요."},{"b":[0.22,0.83,0.19,0.05],"c":[0.208,0.8,0.214,0.11],"r":3.4586,"img":"img/L3/walk/p051_22_05.jpg","say":"집톤 시공 시 배면 화살표 방향을 지키라는 주의예요."},{"b":[0.53,0.86,0.35,0.06],"c":[0.5125,0.835,0.385,0.11],"r":6.2222,"img":"img/L3/walk/p051_22_06.jpg","say":"전기 설비 등 모든 공정이 완료된 후 집톤을 시공한다는 문장이에요."}]}},{"p":52,"title":"T&H-Bar 시스템: 판 옆면에 H-Bar를 끼운다","terms":["T&H-Bar","T-Bar","메인 T-Bar","캐링 채널","마이너 채널","달대 볼트","C/T 클립"],"pass1":[{"kind":"say","lines":["**T&H-Bar** 는 **T-Bar** 에 H-Bar를 더한 시스템이에요.","판과 판 사이를 H자 막대가 물어 줘요.","그래서 아래에서 줄눈과 피스가 잘 안 보이고 깔끔해요."]},{"kind":"analogy","head":"H-Bar는 판을 잇는 지퍼","scene":"두 장의 판 옆면 틈에 H자 막대를 끼워 서로 붙잡게 한다고 생각해요.","map":[["H자 막대","H-Bar"],["판 옆면의 틈","천장재 두께 면"],["붙잡아 주는 효과","천장면의 일체성과 안정성"]]}],"pass2":[{"kind":"points","head":"T&H-Bar 시스템의 내용","items":["**T-Bar** 와 H-Bar를 함께 써서 규격화된 천장 패널을 지지해요.","**메인 T-Bar** 사이에 천장재를 설치하고 천장재의 측면을 H-Bar로 연결해 마감해요.","**T-Bar** 단독 시스템보다 천장면의 일체성과 안정성이 높아요.","등기구, 디퓨저, 스피커, 스프링클러 등 천장설비 위치를 천장 모듈과 함께 계획해요.","전기와 설비 배관, 배선은 천장틀과 간섭이 없도록 사전에 조정해요."]},{"kind":"compare","head":"상세도에 적힌 부재 규격","cols":["부재","규격 또는 간격"],"rows":[["행어볼트 (**달대 볼트(hanger bolt)**)","9mm, @900"],["**마이너 채널(Minor Channel)**","19x10x1.2T"],["**캐링 채널(carrying channel)**","38X12X1.2T"],["**메인 T-Bar** (메인 티바)","25x38x0.4T"],["H-바","20X20X0.45T"],["**C/T 클립**","캐링채널과 메인 티바 체결"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"T&H-Bar 시스템에서 H-Bar가 하는 일은?","choices":["천장재를 캐링 채널에 매단다","천장재의 측면을 연결하고 지지한다","천장재를 나사로 고정한다","천장 속 배관을 지지한다"],"a":1,"why":"**T&H-Bar** 의 H-Bar는 패널 가장자리를 연결하고 지지해서 천장면의 일체성과 안정성을 높여요."}],"walk":{"head":{"b":[0.0092,0.0368,0.4507,0.2405],"c":[0,0.0208,0.4957,0.2725],"r":3.2339,"img":"img/L3/walk/p052_h.jpg"},"parts":[{"b":[0.03,0.28,0.55,0.05],"c":[0.0025,0.2439,0.605,0.1222],"r":8.8016,"img":"img/L3/walk/p052_22_01.jpg","say":"T-Bar와 H-Bar를 함께 사용하는 천장 시스템이라는 정의예요."},{"b":[0.03,0.33,0.45,0.05],"c":[0.0075,0.3,0.495,0.11],"r":8.0,"img":"img/L3/walk/p052_22_02.jpg","say":"메인 T-Bar 사이에 천장재를 두고 측면을 H-Bar로 연결한다는 문장이에요."},{"b":[0.03,0.49,0.55,0.1],"c":[0.0025,0.474,0.605,0.132],"r":8.1481,"img":"img/L3/walk/p052_22_03.jpg","say":"T-Bar와 T&H-Bar의 차이를 한 줄씩 정리한 파란 상자예요."},{"b":[0.62,0.45,0.09,0.05],"c":[0.565,0.42,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p052_22_04.jpg","say":"H-바 20X20X0.45T 라고 적힌 이름표예요."},{"b":[0.88,0.45,0.09,0.05],"c":[0.8,0.42,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p052_22_05.jpg","say":"메인 티바 25x38x0.4T 예요."},{"b":[0.71,0.72,0.22,0.15],"c":[0.698,0.704,0.244,0.182],"r":2.3834,"img":"img/L3/walk/p052_22_06.jpg","say":"오른쪽 아래 단면 그림. 메인 티바는 25 폭에 38 높이, H-바는 20x20이에요."}]}},{"p":53,"title":"T&H-Bar 천장 사진과 천장재 규격","terms":["T&H-Bar","T-Bar"],"pass1":[{"kind":"say","lines":["완성된 **T&H-Bar** 천장 사진이에요.","T-bar 줄은 보이는데 H-bar 자리는 선이 거의 안 보여요.","그래서 천장이 한 장처럼 이어져 보여요."]}],"pass2":[{"kind":"points","head":"사진과 제품표에서 볼 것","items":["H-bar 설치 부분은 아래에서 줄눈이나 피스가 보이지 않아 깔끔해요.","같은 천장에서 T-bar 줄만 길게 보이고 짧은 방향 줄은 사라져 보여요.","오른쪽 제품표: 무늬는 Rococo, 색상은 White예요.","규격은 15 x 300(395) x 1,210 mm, 포장 수량은 10매/1Box예요.","Edge 형태는 Kerfed 또는 Beveled 예요. 옆면에 홈을 파거나 모서리를 깎은 모양이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"T&H-Bar 천장을 아래에서 봤을 때 나타나는 특징은?","choices":["H-bar 자리의 줄눈과 피스가 보이지 않는다","모든 줄눈이 굵게 보인다","나사못 자국이 줄지어 보인다","판을 들어 올릴 수 없다"],"a":0,"why":"H-bar가 판 옆면 안으로 들어가서 줄눈과 피스가 안 보여요. 이것이 **T-Bar** 단독과 다른 점이에요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1975,0.1412],"c":[0,0.0208,0.2215,0.1732],"r":2.2735,"img":"img/L3/walk/p053_h.jpg"},"parts":[{"b":[0.28,0.18,0.09,0.05],"c":[0.225,0.15,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p053_21_01.jpg","say":"T-bar. 길게 보이는 줄이에요."},{"b":[0.46,0.18,0.28,0.06],"c":[0.446,0.155,0.308,0.11],"r":4.9778,"img":"img/L3/walk/p053_21_02.jpg","say":"H-bar는 아래에서 줄눈이나 피스가 보이지 않아 깔끔하다는 설명이에요."},{"b":[0.19,0.4,0.18,0.03],"c":[0.178,0.36,0.204,0.11],"r":3.297,"img":"img/L3/walk/p053_21_03.jpg","say":"주황 점선이 H-bar가 들어간 자리예요. 선이 거의 안 보여요."},{"b":[0.6,0.68,0.28,0.14],"c":[0.586,0.664,0.308,0.172],"r":3.1835,"img":"img/L3/walk/p053_21_04.jpg","say":"제품표. 규격 15x300(395)x1,210mm, 10매 1박스, Kerfed 또는 Beveled 엣지예요."}]}},{"p":54,"title":"현장 사진: 천장 속에 캐링 채널과 T-bar가 이렇게 있다","terms":["T&H-Bar","T-Bar","캐링 채널"],"pass1":[{"kind":"say","lines":["천장 마감재를 아직 다 얹지 않은 현장 사진이에요.","천장 속에 배관, 덕트, 스프링클러가 지나가는 것이 보여요.","그 아래로 **캐링 채널(carrying channel)** 과 T-bar가 격자로 깔려 있어요."]}],"pass2":[{"kind":"points","head":"사진에서 볼 것","items":["파란 선으로 표시된 세로 줄이 T-bar예요.","주황 선으로 표시된 가로 줄이 **캐링 채널(carrying channel)** 이에요.","빨간 관은 소방 배관, 은색 통은 공조 덕트예요.","이렇게 설비가 많아서 **T&H-Bar** 나 **T-Bar** 처럼 판을 들어 올릴 수 있는 천장이 유리해요.","천장 속 설비가 다 끝난 다음에 판을 얹어요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.57,0.05,0.09,0.05],"c":[0.515,0.02,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p054_21_01.jpg","say":"T-bar 이름표예요. 파란 선이 가리키는 줄이에요."},{"b":[0.68,0.45,0.09,0.05],"c":[0.625,0.42,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p054_21_02.jpg","say":"캐링 채널 이름표예요. 주황 선이 가리키는 줄이에요."},{"b":[0.21,0.25,0.3,0.3],"c":[0.195,0.234,0.33,0.332],"r":1.7671,"img":"img/L3/walk/p054_21_03.jpg","say":"천장 속 소방 배관과 공조 덕트가 지나가는 모습이에요."},{"b":[0.6,0.62,0.3,0.25],"c":[0.585,0.604,0.33,0.282],"r":2.0804,"img":"img/L3/walk/p054_21_04.jpg","say":"이미 판을 얹어 마감한 부분이에요. 격자가 또렷해요."}]}},{"p":55,"title":"SGP 칸막이: 강판과 석고보드를 합친 조립식 패널","terms":["SGP 칸막이","시스템 칸막이"],"pass1":[{"kind":"say","lines":["여기부터는 천장이 아니라 칸막이 이야기예요.","**SGP 칸막이(Steel Gypsum Panel)** 는 강판과 석고보드를 합친 패널이에요.","이름 그대로 Steel 강판 + Gypsum 석고 + Panel 판이에요."]}],"pass2":[{"kind":"points","head":"SGP 칸막이의 특징","items":["도장 또는 표면 처리된 강판과 석고보드를 결합해 만든 조립식 패널형 칸막이예요.","공장에서 규격화된 패널을 만들어 현장에서 조립하므로 시공이 빠르고 마감 품질이 고르게 나와요.","패널 조인트 방식이라 해체와 재설치가 쉬워 공간 변경에 유연해요.","표면 강판에 도장 등의 마감처리를 해 내구성과 유지관리성이 우수해요.","패널의 구성과 두께에 따라 차음, 내화 성능이 달라져요.","사무실, 업무공간처럼 빨리 세우고 자주 바꾸는 칸막이에 많이 써요."]},{"kind":"bg","src":"배경 지식","lines":["석고보드는 불에 잘 안 타지만 부딪히면 잘 깨져요.","강판은 튼튼하지만 소리를 잘 전달해요.","둘을 겹치면 단단하면서 불과 소리에도 어느 정도 버티는 판이 돼요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"english","head":"답안에 쓸 문장: SGP 칸막이","en":"SGP 칸막이는 도장 강판과 석고보드를 결합한 조립식 패널형 칸막이로, 공장 제작과 현장 조립으로 시공이 빠르고 해체와 재설치가 용이하다.","ko":"재료, 만드는 방식, 장점 세 가지를 한 문장에 담았어요.","tip":"강판 + 석고, 공장에서 만들어 현장에서 조립, 뜯어서 다시 쓴다."},{"kind":"warn","head":"헷갈리는 짝","items":["**SGP 칸막이(Steel Gypsum Panel)** 는 강판 + 석고보드예요.","**시스템 칸막이** 는 유리, 패널, 도어를 조합해서 디자인이 더 다양해요.","큐비클은 화장실용이고 HPL 표면이에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.2686,0.143],"c":[0,0.0208,0.2954,0.175],"r":3.0009,"img":"img/L3/walk/p055_h.jpg"},"parts":[{"b":[0.03,0.19,0.28,0.05],"c":[0.016,0.16,0.308,0.11],"r":4.9778,"img":"img/L3/walk/p055_22_01.jpg","say":"4.3.1 SGP 칸막이 (Steel Gypsum Panel). 영문 이름을 꼭 봐 두세요."},{"b":[0.03,0.25,0.52,0.05],"c":[0.004,0.2172,0.572,0.1156],"r":8.7966,"img":"img/L3/walk/p055_22_02.jpg","say":"강판과 석고보드를 결합한 조립식 패널형 칸막이라는 정의예요."},{"b":[0.03,0.34,0.55,0.05],"c":[0.0025,0.3039,0.605,0.1222],"r":8.8016,"img":"img/L3/walk/p055_22_03.jpg","say":"패널 조인트 방식이라 해체와 재설치가 쉽다는 장점이에요."},{"b":[0.03,0.49,0.45,0.05],"c":[0.0075,0.46,0.495,0.11],"r":8.0,"img":"img/L3/walk/p055_22_04.jpg","say":"사무실, 업무공간의 칸막이에 많이 쓴다는 문장이에요."},{"b":[0.07,0.66,0.28,0.28],"c":[0.056,0.644,0.308,0.312],"r":1.755,"img":"img/L3/walk/p055_22_05.jpg","say":"SGP 칸막이로 사무실을 나눈 사진이에요. 면이 매끈하고 줄눈이 일정해요."}]}},{"p":56,"title":"큐비클 칸막이: 화장실용 조립식 패널","terms":["큐비클","SGP 칸막이"],"pass1":[{"kind":"say","lines":["**큐비클(Cubicle)** 은 화장실 칸을 나누는 칸막이예요.","우리가 화장실에서 늘 보는 그 문과 벽이에요.","코어재 양면에 HPL 같은 표면 마감재를 붙인 패널을 써요."]}],"pass2":[{"kind":"points","head":"큐비클 칸막이의 특징","items":["화장실 등에서 쓰는 조립식 패널형 칸막이 시스템이에요.","코어재 양면에 HPL 등 표면 마감재를 접착한 패널을 주로 써요.","색상, 패턴, 패널 규격을 공간 디자인에 맞게 고르거나 주문 제작할 수 있어요.","스테인리스강, 알루미늄 등의 브래킷, 힌지, 받침대 같은 전용 부속철물로 조립해요.","공장 제작 패널을 현장에서 조립하는 건식공법이라 시공이 빠르고 유지, 교체가 쉬워요.","습기가 많은 곳이라 패널과 부속철물은 내수성, 내식성, 내오염성이 우수한 제품을 골라요.","패널과 바닥, 벽체의 고정 상태, 문짝의 개폐 상태, 부속철물의 견고성을 확인해요."]},{"kind":"bg","src":"배경 지식","lines":["HPL은 고압으로 눌러 붙인 단단한 표면 마감재예요.","물과 세제에 강해서 화장실 칸막이에 많이 써요.","슬라이드 사진 오른쪽의 잠금쇠, 경첩, 받침대, 보호대, 옷걸이, 브라켓이 전용 부속철물이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"큐비클 칸막이의 패널 표면에 주로 쓰는 마감재는?","choices":["도장 강판","HPL","석고보드","유리"],"a":1,"why":"**큐비클(Cubicle)** 은 코어재 양면에 HPL을 붙여요. 도장 강판은 **SGP 칸막이(Steel Gypsum Panel)** 예요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1956,0.143],"c":[0,0.0208,0.2196,0.175],"r":2.2309,"img":"img/L3/walk/p056_h.jpg"},"parts":[{"b":[0.03,0.19,0.24,0.05],"c":[0.018,0.16,0.264,0.11],"r":4.2667,"img":"img/L3/walk/p056_22_01.jpg","say":"4.3.2 큐비클 칸막이 (Cubicle). 영문 이름을 봐 두세요."},{"b":[0.03,0.25,0.65,0.05],"c":[0,0.2028,0.715,0.1445],"r":8.7966,"img":"img/L3/walk/p056_22_02.jpg","say":"화장실 등에서 쓰며 코어재 양면에 HPL을 접착한다는 정의예요."},{"b":[0.03,0.42,0.62,0.05],"c":[0,0.3761,0.682,0.1378],"r":8.7986,"img":"img/L3/walk/p056_22_03.jpg","say":"내수성, 내식성, 내오염성이 우수한 제품을 선정한다는 핵심 문장이에요."},{"b":[0.55,0.52,0.35,0.42],"c":[0.5325,0.499,0.385,0.462],"r":1.4815,"img":"img/L3/walk/p056_22_04.jpg","say":"오른쪽 여섯 장이 전용 부속철물이에요. 잠금쇠, 경첩, 받침대, 보호대, 옷걸이, 브라켓."}]}},{"p":57,"title":"시스템 칸막이: 프레임, 패널, 유리, 도어를 조합","terms":["시스템 칸막이","SGP 칸막이"],"pass1":[{"kind":"say","lines":["**시스템 칸막이** 는 부품을 모아서 짜맞추는 칸막이예요.","프레임, 패널, 유리, 도어를 공장에서 규격으로 만들어 현장에서 조립해요.","레고 블록처럼 조합만 바꾸면 다른 벽이 돼요."]}],"pass2":[{"kind":"points","head":"시스템 칸막이의 특징","items":["공장에서 규격화된 프레임, 패널, 유리, 도어를 만들어 현장에서 조립하는 모듈형 칸막이예요.","건식공법이라 시공이 빠르고 해체, 재설치와 공간 변경이 쉬워요.","유리, 금속패널, 솔리드패널을 조합해 개방성, 프라이버시, 차음성능에 대응해요.","전기와 통신 설비를 시스템 내부에 통합할 수 있는 제품도 있어요.","부재가 모듈이라 유지관리와 부분 교체가 쉬워요.","사무실, 회의실, 업무시설처럼 공간 구성이 자주 바뀌는 곳에 주로 써요.","**SGP 칸막이(Steel Gypsum Panel)** 에 비해 디자인이 다양해요."]},{"kind":"compare","head":"칸막이 세 가지 정리","cols":["","**SGP 칸막이(Steel Gypsum Panel)**","**큐비클(Cubicle)**","**시스템 칸막이**"],"rows":[["주 재료","도장 강판 + 석고보드","코어재 + HPL","프레임 + 패널, 유리, 도어"],["주 용도","사무실, 업무공간","화장실","사무실, 회의실"],["특징","빠른 시공, 재설치 쉬움","내수, 내식, 내오염","디자인 다양, 개방성 조절"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"SGP 칸막이와 비교한 시스템 칸막이의 장점으로 슬라이드가 적은 것은?","choices":["더 저렴하다","디자인이 더 다양하다","더 무겁다","습기에 더 강하다"],"a":1,"why":"**시스템 칸막이** 는 **SGP 칸막이(Steel Gypsum Panel)** 에 비해 디자인이 다양하고 개방성과 프라이버시를 조절할 수 있어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1635,0.143],"c":[0,0.0208,0.2,0.175],"r":2.0317,"img":"img/L3/walk/p057_h.jpg"},"parts":[{"b":[0.03,0.19,0.16,0.05],"c":[0.01,0.16,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p057_22_01.jpg","say":"4.3.3 시스템 칸막이 제목이에요."},{"b":[0.03,0.25,0.6,0.05],"c":[0.0,0.2083,0.66,0.1333],"r":8.8022,"img":"img/L3/walk/p057_22_02.jpg","say":"규격화된 프레임, 패널, 유리, 도어를 현장에서 조립하는 모듈형이라는 정의예요."},{"b":[0.03,0.42,0.6,0.05],"c":[0.0,0.3783,0.66,0.1333],"r":8.8022,"img":"img/L3/walk/p057_22_03.jpg","say":"SGP에 비해 디자인이 다양하다는 비교 문장이에요."},{"b":[0.03,0.51,0.3,0.05],"c":[0.015,0.48,0.33,0.11],"r":5.3333,"img":"img/L3/walk/p057_22_04.jpg","say":"관련 업체 예시. 해외 클레스트라 하우저만, 국내 엑사이엔씨예요."},{"b":[0.26,0.68,0.26,0.26],"c":[0.247,0.664,0.286,0.292],"r":1.7412,"img":"img/L3/walk/p057_22_05.jpg","say":"유리와 패널을 섞어 짠 시스템 칸막이 사진이에요."}]}},{"p":58,"title":"노출 천장 조명 설치: 전산볼트와 레이스웨이","terms":["레이스웨이","달대 볼트"],"pass1":[{"kind":"say","lines":["요즘 많이 쓰는 노출 천장 이야기예요.","천장을 판으로 덮지 않고 콘크리트와 배관을 그대로 보여 주는 방식이에요.","이때 조명은 **레이스웨이** 라는 레일에 달아서 매달아요."]}],"pass2":[{"kind":"points","head":"사진에 이름표가 붙은 것들","items":["전산볼트: 3M 짜리를 1.5M로 절단하여 시공한다고 적혀 있어요.","**레이스웨이**: 조명을 붙이는 긴 금속 레일이에요.","레이스웨이 A행거 너트형: 전산볼트와 **레이스웨이** 를 잇는 부속이에요.","레이스웨이 엘보: **레이스웨이** 가 꺾이는 모서리 부속이에요.","드롭인앙카: 콘크리트 천장에 볼트를 걸려고 박아 둔 앵커예요. 천장틀의 **스트롱 앵커** 와 같은 역할이에요.","전산볼트는 천장틀에서 쓰는 **달대 볼트(hanger bolt)** 와 같은 나선형 볼트예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"노출 천장에서 조명을 매달 때 쓰는 전산볼트는 몇 M를 몇 M로 잘라 쓴다고 적혀 있나요?","choices":["1M를 0.5M로","3M를 1.5M로","5M를 2.5M로","2M를 1M로"],"a":1,"why":"사진 이름표에 3M를 1.5M 절단하여 시공한다고 적혀 있어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.3781,0.1967],"c":[0,0.0208,0.4159,0.2287],"r":3.233,"img":"img/L3/walk/p058_h.jpg"},"parts":[{"b":[0.26,0.32,0.14,0.06],"c":[0.23,0.295,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p058_21_01.jpg","say":"전산볼트. 3M를 1.5M로 절단하여 시공한다고 적혀 있어요."},{"b":[0.25,0.45,0.13,0.04],"c":[0.215,0.415,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p058_21_02.jpg","say":"레이스웨이 A행거 너트형이에요."},{"b":[0.46,0.42,0.09,0.04],"c":[0.405,0.385,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p058_21_03.jpg","say":"레이스웨이 엘보. 꺾이는 모서리 부속이에요."},{"b":[0.46,0.58,0.09,0.04],"c":[0.405,0.545,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p058_21_04.jpg","say":"레이스웨이 본체예요. 여기에 조명을 붙여요."},{"b":[0.66,0.39,0.09,0.04],"c":[0.605,0.355,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p058_21_05.jpg","say":"드롭인앙카. 콘크리트에 박아 둔 앵커예요."}]}},{"p":59,"title":"아파트 천장: 톱니형 경량철골","terms":["톱니형 경량철골","M-Bar"],"pass1":[{"kind":"say","lines":["아파트는 천장 속 공간이 아주 좁아요.","그래서 긴 볼트를 내릴 자리가 없어요.","대신 **톱니형 경량철골** 자재로 천장을 설치해요."]}],"pass2":[{"kind":"points","head":"사진에 이름표가 붙은 것들","items":["인서트(앙카): 콘크리트 슬라브에 미리 박아 둔 철물이에요.","결착볼트: 인서트와 톱니형 달대를 잇는 짧은 볼트예요.","톱니형 달대: 톱니가 있어 길이를 조금씩 조절하며 걸 수 있는 달대예요.","톱니형 케리어바(양날): **톱니형 경량철골** 의 주 골조 역할을 해요.","아파트 M-BAR: 일반 **M-Bar** 보다 낮게 만든 아파트용 바예요.","석고보드: 맨 아래에 붙는 마감 보드예요."]},{"kind":"bg","src":"배경 지식","lines":["일반 천장은 볼트 길이를 돌려서 높이를 맞춰요.","천장 속이 10cm도 안 되면 볼트를 돌릴 여유가 없어요.","톱니 모양은 한 칸씩 걸어 맞추는 방식이라 아주 얇은 공간에서도 높이를 잡을 수 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"아파트 천장에 톱니형 경량철골을 쓰는 이유는?","choices":["천장 속 공간이 매우 협소해서","화재에 더 강해서","값이 더 비싸서","소리를 더 잘 막아서"],"a":0,"why":"슬라이드에 아파트는 천장 속의 공간이 매우 협소하기 때문이라고 적혀 있어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.5433,0.1967],"c":[0,0.0208,0.5976,0.2287],"r":4.6454,"img":"img/L3/walk/p059_h.jpg"},"parts":[{"b":[0.25,0.28,0.09,0.04],"c":[0.195,0.245,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p059_22_01.jpg","say":"인서트(앙카). 슬라브에 미리 박아 둔 철물이에요."},{"b":[0.13,0.53,0.06,0.04],"c":[0.06,0.495,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p059_22_02.jpg","say":"결착볼트예요."},{"b":[0.28,0.57,0.07,0.04],"c":[0.215,0.535,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p059_22_03.jpg","say":"톱니형 달대. 톱니로 높이를 맞춰요."},{"b":[0.1,0.68,0.1,0.04],"c":[0.05,0.645,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p059_22_04.jpg","say":"톱니형 케리어바(양날)예요."},{"b":[0.12,0.88,0.08,0.04],"c":[0.06,0.845,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p059_22_05.jpg","say":"아파트 M-BAR예요."},{"b":[0.43,0.35,0.45,0.5],"c":[0.4075,0.325,0.495,0.55],"r":1.6,"img":"img/L3/walk/p059_22_06.jpg","say":"오른쪽은 조립한 모습이에요. 높이가 아주 낮아요."}]}},{"p":60,"title":"[실습] 상세도를 그리는 목적과 경량 벽체 두 방식","terms":["상세도","덧붙이는 벽"],"pass1":[{"kind":"say","lines":["마지막 실습이에요. **상세도** 를 그려 봐요.","**상세도** 는 한 부위를 어떻게 시공하는지 설명하는 도면이에요.","슬라이드는 상세도를 그린다는 말을 디테일을 푼다고 표현해요."]},{"kind":"analogy","head":"상세도는 조립 설명서의 확대 컷","scene":"가구 설명서에서 나사 하나를 확대해 어디에 어떻게 박는지 보여 주는 그림을 떠올려요.","map":[["전체 조립도","평면도, 입면도"],["확대 컷","**상세도**"],["나사 규격 표시","재료와 두께 표기"]]}],"pass2":[{"kind":"points","head":"1. 상세도를 그리는 목적","items":["디자인의 구체적인 실행 방식을 설명해 주는 도면이에요.","특정 부위의 시공을 어떻게 해야 하는지 설명하기 위한 목적이에요.","최종 공간디자인의 완성도를 끌어올리는 화룡점정의 도면이에요."]},{"kind":"compare","head":"2. 경량 벽체 상세도의 두 가지 방식","cols":["방식","무엇","그리는 모양"],"rows":[["**덧붙이는 벽**","기존 콘크리트나 조적 벽 위에 마감재를 적용하는 공사","단면만 있음"],["새로 세우는 벽","벽체가 없는 곳에 공간을 나누려고 새 벽을 세우는 공사","양면의 벽체"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"english","head":"답안에 쓸 문장: 상세도의 목적","en":"상세도는 디자인의 구체적인 실행 방식을 설명하고 특정 부위의 시공 방법을 보여 주어 공간디자인의 완성도를 끌어올리는 도면이다.","ko":"실행 방식, 시공 방법, 완성도 세 낱말을 넣으면 돼요.","tip":"상세도 = 디테일을 푼다."}],"walk":{"head":{"b":[0.0029,0.0136,0.2862,0.0591],"c":[0,0,0.3148,0.0911],"r":6.1432,"img":"img/L3/walk/p060_h.jpg"},"parts":[{"b":[0.12,0.11,0.13,0.05],"c":[0.085,0.08,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p060_22_01.jpg","say":"1. 상세도를 그리는 목적이에요."},{"b":[0.13,0.29,0.21,0.05],"c":[0.118,0.26,0.234,0.11],"r":3.7818,"img":"img/L3/walk/p060_22_02.jpg","say":"상세도를 그린다 = 디테일을 푼다. 이 한 줄을 외워요."},{"b":[0.15,0.44,0.21,0.05],"c":[0.138,0.41,0.234,0.11],"r":3.7818,"img":"img/L3/walk/p060_22_03.jpg","say":"기존 건축물 벽체의 위에 덧붙이는 방식이에요. 단면만 있어요."},{"b":[0.15,0.52,0.25,0.05],"c":[0.1375,0.49,0.275,0.11],"r":4.4444,"img":"img/L3/walk/p060_22_04.jpg","say":"벽체가 없는 공간에 새 벽체를 세우는 방식이에요. 양면이에요."},{"b":[0.18,0.6,0.68,0.33],"c":[0.146,0.5835,0.748,0.363],"r":3.6633,"img":"img/L3/walk/p060_22_05.jpg","say":"아래 사진 네 장은 실제 벽 단면이에요. 메탈스터드, 목구조틀, 조적벽체, 샌드위치패널."}]}},{"p":61,"title":"덧붙이는 벽 상세도: 단면만 있는 벽, 84mm","terms":["상세도","덧붙이는 벽","C-스터드","단열재","2ply","줄퍼티","올퍼티"],"pass1":[{"kind":"say","lines":["**덧붙이는 벽** 의 **상세도** 예요.","기존 콘크리트 벽 위에 한쪽만 마감하니 단면이 한 겹뿐이에요.","여기서 나오는 숫자는 65, 25, 90, 84예요."]}],"pass2":[{"kind":"steps","head":"도면 글씨를 위에서 아래로 읽기","steps":["철근 콘크리트 벽체 (건축). 원래 있던 벽이에요.","**C-스터드(C-Stud)** 65T / THK 50MM INSULATION. 65mm 스터드와 두께 50mm **단열재** 예요.","THK 12.5MM 석고보드 **2ply** / PUTTY / 지정 도장 마감.","그림 아래 치수는 65 와 25, 합해서 90이에요."],"answer":"기존 벽 위에 스터드를 세우고 보드 두 겹을 붙인 뒤 도장으로 마감해요."},{"kind":"points","head":"도면 옆 설명에 적힌 두께 이야기","items":["방화와 방음을 위해서는 THK 12.5MM를 시공해요.","일반적인 벽체를 세울 때는 THK 9.5MM를 사용해요.","THK 9.5MM 사용 시 총 단면 경량 벽체의 두께는 84MM예요.","12.5mm를 **2ply** 로 쓰면 12.5 x 2 = 25, 65 + 25 = 90mm가 돼요.","9.5mm를 **2ply** 로 쓰면 9.5 x 2 = 19, 65 + 19 = 84mm가 돼요.","바탕 **1ply** 를 먼저 박고 그 위에 마감 한 겹을 더 붙이는 순서는 벽이나 천장이나 같아요."]},{"kind":"compare","head":"PUTTY 두 단계와 상황별 추천 사양","cols":["구분","내용"],"rows":[["1차 **줄퍼티**","석고보드의 이음매 매움"],["2차 **올퍼티**","전체 도장면의 균질화 및 발색력 향상"],["일반 사무실, 상가 내부","9.5T x **2ply**"],["소음 차단 필요 공간 (회의실, 병원 등)","9.5T x **2ply** 또는 12.5T"],["방화구획, 화장실 파티션","12.5T 이상, 방화보드, 방수보드"],["보강 필요 (TV, 선반 부착 등)","합판 12T + 석고보드 9.5T 조합 사용"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"문제은행 l23","q":"C-스터드 65T에 9.5mm 석고보드를 2ply로 덧붙이는 벽의 총 두께는?","qko":"한쪽 면만 마감하는 벽의 두께를 계산하는 문제예요.","solve":["**덧붙이는 벽** 은 기존 벽 위에 한쪽만 마감해요.","보드는 9.5mm 짜리를 **2ply**, 즉 두 겹 붙여요. 9.5 x 2 = 19mm예요.","**C-스터드(C-Stud)** 는 65mm예요.","65 + 19 = 84mm예요."],"answer":"84mm"},{"kind":"warn","head":"숫자 헷갈리지 않기","items":["84mm는 **덧붙이는 벽** (한쪽 면), 103mm는 양면 벽이에요.","90mm는 같은 **덧붙이는 벽** 에 12.5mm 보드를 쓴 경우예요.","1차 **줄퍼티** 는 이음매만, 2차 **올퍼티** 는 전체 면이에요."]}],"walk":{"head":{"b":[0.0029,0.0136,0.2862,0.153],"c":[0,0,0.3148,0.185],"r":3.0251,"img":"img/L3/walk/p061_h.jpg"},"parts":[{"b":[0.1,0.2,0.21,0.05],"c":[0.088,0.17,0.234,0.11],"r":3.7818,"img":"img/L3/walk/p061_23_01.jpg","say":"기존 건축물 벽체의 위에 덧붙이는 방식. 단면만 있어요."},{"b":[0.32,0.34,0.24,0.17],"c":[0.308,0.324,0.264,0.202],"r":2.3234,"img":"img/L3/walk/p061_23_02.jpg","say":"INSULATION 설명. EPS, XPS, 폴리우레탄폼, 글라스울, 미네랄울 등 단열재 종류예요."},{"b":[0.32,0.66,0.24,0.09],"c":[0.308,0.644,0.264,0.122],"r":3.847,"img":"img/L3/walk/p061_23_03.jpg","say":"C-STUD 65T / THK 50MM INSULATION / 12.5MM 석고보드 2PLY 표기예요."},{"b":[0.2,0.85,0.09,0.05],"c":[0.145,0.82,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p061_23_04.jpg","say":"65 와 25, 합해서 90. 12.5mm 2겹일 때의 두께예요."},{"b":[0.3,0.77,0.24,0.14],"c":[0.288,0.754,0.264,0.172],"r":2.7287,"img":"img/L3/walk/p061_23_05.jpg","say":"9.5MM를 쓰면 총 두께가 84MM가 된다는 설명이에요."},{"b":[0.51,0.75,0.24,0.14],"c":[0.498,0.734,0.264,0.172],"r":2.7287,"img":"img/L3/walk/p061_23_06.jpg","say":"PUTTY 설명. 1차 줄퍼티는 이음매, 2차 올퍼티는 전체 면이에요."}]}},{"p":62,"title":"새로 세우는 벽 상세도: 양면 벽체, 103mm","terms":["상세도","덧붙이는 벽","C-스터드","단열재","2ply","1ply"],"pass1":[{"kind":"say","lines":["이번에는 벽이 없던 곳에 새로 세우는 벽의 **상세도** 예요.","양쪽에 다 보드를 붙이니 두께가 103mm가 돼요.","**덧붙이는 벽** 의 84mm와 짝으로 외워요."]}],"pass2":[{"kind":"steps","head":"도면 치수 읽기","steps":["가운데 **C-스터드(C-Stud)** 65T, 그 안에 THK 50MM **단열재** 예요.","양쪽에 THK 9.5MM 석고보드 **2ply** / PUTTY / 지정 도장 마감이에요.","한쪽 보드 두께는 9.5 x 2 = 19mm예요.","19 + 65 + 19 = 103mm가 벽 전체 두께예요.","스터드 간격은 @450, 즉 450mm예요.","바닥에는 BASE RUNNER (바닥러너)가 깔려요."],"answer":"19 + 65 + 19 = 103mm, 스터드 간격 450mm예요."},{"kind":"points","head":"오른쪽 그림에 적힌 시공 주의","items":["상부러너와 바닥러너는 600mm 간격으로 고정해요.","바탕 석고보드 **1ply** 를 먼저 붙이고 그 위에 마감 석고보드를 붙여요.","모든 마감면의 이음매는 조인트 테이프와 조인트 컴파운드로 마감해야 해요.","**단열재** 는 한쪽 보드를 붙인 뒤 스터드 사이에 넣어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"문제은행 l23","q":"C-스터드 65T 양면에 9.5mm 석고보드를 2ply로 시공한 벽체의 두께는?","qko":"양면 벽의 두께를 계산하는 문제예요.","solve":["한쪽 보드 두께는 9.5 x 2 = 19mm예요.","양쪽이니 19 + 19 = 38mm예요.","**C-스터드(C-Stud)** 65mm를 더하면 38 + 65 = 103mm예요."],"answer":"103mm"},{"kind":"warn","head":"짝으로 외울 숫자","items":["**덧붙이는 벽** (한쪽 면) 9.5mm 2겹: 65 + 19 = 84mm","새로 세우는 벽(양면) 9.5mm 2겹: 19 + 65 + 19 = 103mm","새로 세우는 벽(양면) 12.5mm 2겹: 25 + 65 + 25 = 115mm","도면에는 내벽 벽체 두께를 100mm로 그려요."]}],"walk":{"head":{"b":[0.0029,0.0136,0.683,0.2044],"c":[0,0,0.7513,0.2364],"r":5.6499,"img":"img/L3/walk/p062_h.jpg"},"parts":[{"b":[0.13,0.22,0.19,0.05],"c":[0.118,0.19,0.214,0.11],"r":3.4586,"img":"img/L3/walk/p062_22_01.jpg","say":"103 = 19 + 65 + 19. 양면 벽체의 총 두께예요."},{"b":[0.22,0.51,0.26,0.09],"c":[0.207,0.494,0.286,0.122],"r":4.1676,"img":"img/L3/walk/p062_22_02.jpg","say":"C-STUD 65T @450 / THK 50MM INSULATION 표기예요."},{"b":[0.22,0.79,0.19,0.05],"c":[0.208,0.76,0.214,0.11],"r":3.4586,"img":"img/L3/walk/p062_22_03.jpg","say":"BASE RUNNER. 바닥에 먼저 깔리는 런너예요."},{"b":[0.63,0.47,0.09,0.05],"c":[0.575,0.44,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p062_22_04.jpg","say":"450. 스터드 사이 간격이에요."},{"b":[0.86,0.35,0.09,0.09],"c":[0.8,0.334,0.2,0.122],"r":2.9144,"img":"img/L3/walk/p062_22_05.jpg","say":"오른쪽 세로 치수 19, 65, 19 와 합계 103이에요."},{"b":[0.52,0.9,0.24,0.07],"c":[0.508,0.88,0.264,0.11],"r":4.2667,"img":"img/L3/walk/p062_22_06.jpg","say":"바닥러너를 600mm 간격으로 고정한다는 설명이에요."}]}},{"p":63,"title":"경량 천장 상세도: M-Bar System 부재별 규격 총정리","terms":["상세도","M-Bar","캐링 채널","마이너 채널","달대 볼트","2ply"],"pass1":[{"kind":"say","lines":["마지막 쪽이에요. **M-Bar** 천장의 **상세도** 를 부재별로 정리해 놨어요.","이 쪽 하나에 천장 숫자가 다 모여 있어요.","시험 전날 이 쪽만 봐도 될 만큼 중요해요."]}],"pass2":[{"kind":"compare","head":"상세도에 적힌 부재별 규격과 간격","cols":["부재","규격","간격, 하는 일"],"rows":[["행거볼트 (**달대 볼트(hanger bolt)**)","지름 9MM","900MM 간격, 인서트나 앵커볼트에 삽입 후 고정"],["행거클립","20~30(W)x105~150(H)x2(T)","행거볼트와 **캐링 채널(carrying channel)** 고정"],["**마이너 채널(Minor Channel)**","10(W)x19(H)x1.2(T)","3,000MM 간격, 필요시 캐링채널 보강"],["마이너채널클립","","**마이너 채널(Minor Channel)** 과 **캐링 채널(carrying channel)** 고정"],["**캐링 채널(carrying channel)**","12(W)x38(H)x1.2(T)","900MM 간격, **M-Bar** 를 고정하기 위해 설치"],["엠바클립","50(W)x25(D)x50(H)x0.5(T)","캐링채널과 **M-Bar** 고정"],["**M-Bar** 싱글","25(W)x19~25(D)x0.4~0.5(T)","300MM 간격"],["**M-Bar** 더블","50(W)x19(D)x0.4~0.5(T)","300MM 간격"],["석고보드, 텍스","석고보드 9.5T **2ply** 기본","최종 마감에 따라 합판, MDF 등 적용"]]},{"kind":"points","head":"오른쪽 단면도에서 볼 것","items":["위에서 아래로 행거볼트, 행거클립, **캐링 채널(carrying channel)**, 엠바클립, **M-Bar**, 텍스 순서예요.","**M-Bar** 사이 간격에 300이라고 적혀 있어요.","맨 아래 마감은 300X600X6T 지정 텍스 마감이에요.","텍스는 텍스 고정용 나사못으로 **M-Bar** 에 박아요.","행거볼트 위쪽은 슬라브에 미리 넣은 인서트나 **스트롱 앵커** 볼트에 삽입해 고정해요.","석고보드는 바탕 **1ply** 를 먼저 박고 마감 한 겹을 더해 2겹으로 해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"english","head":"답안에 쓸 문장: M-Bar 천장 상세","en":"M-Bar 천장은 지름 9mm 행거볼트를 900mm 간격으로 설치하고, 캐링 채널을 900mm, 마이너 채널을 3,000mm, M-Bar를 300mm 간격으로 시공한 뒤 석고보드 9.5T 2겹을 기본으로 마감한다.","ko":"볼트 900, 캐링 900, 마이너 3,000, M-Bar 300. 이 네 숫자가 핵심이에요.","tip":"구백, 구백, 삼천, 삼백. 소리 내어 외워요."},{"kind":"check","q":"M-Bar 천장 상세도에서 마이너 채널의 간격은?","choices":["300MM","900MM","1,800MM","3,000MM"],"a":3,"why":"**마이너 채널(Minor Channel)** 은 3,000MM 간격이에요. 900MM는 행거볼트와 **캐링 채널(carrying channel)**, 300MM는 **M-Bar** 예요."},{"kind":"warn","head":"마지막 점검","items":["천장 숫자 네 개: 볼트 900, 캐링 900, 마이너 3,000, **M-Bar** 300.","벽체 숫자 세 개: 스터드 450, 보드 9.5 **2ply**, 양면 벽 103.","**T-Bar** 숫자 두 개: 메인 610, 집톤 603."]}],"walk":{"head":{"b":[0.0029,0.0136,0.2862,0.1644],"c":[0,0,0.3148,0.1964],"r":2.8495,"img":"img/L3/walk/p063_h.jpg"},"parts":[{"b":[0.13,0.18,0.15,0.09],"c":[0.105,0.164,0.2,0.122],"r":2.9144,"img":"img/L3/walk/p063_22_01.jpg","say":"행거볼트. 지름 9MM, 900MM 간격 설치라고 적혀 있어요."},{"b":[0.09,0.33,0.13,0.09],"c":[0.055,0.314,0.2,0.122],"r":2.9144,"img":"img/L3/walk/p063_22_02.jpg","say":"행거클립 20~30(W)X105~150(H)X2(T)예요."},{"b":[0.41,0.36,0.14,0.11],"c":[0.38,0.344,0.2,0.142],"r":2.5039,"img":"img/L3/walk/p063_22_03.jpg","say":"마이너채널 10(W)X19(H)X1.2(T), 3,000MM 간격이에요."},{"b":[0.41,0.61,0.14,0.11],"c":[0.38,0.594,0.2,0.142],"r":2.5039,"img":"img/L3/walk/p063_22_04.jpg","say":"캐링채널 12(W)X38(H)X1.2(T), 900MM 간격이에요."},{"b":[0.12,0.83,0.15,0.11],"c":[0.095,0.814,0.2,0.142],"r":2.5039,"img":"img/L3/walk/p063_22_05.jpg","say":"엠바 싱글과 더블 규격, 300MM 간격이에요."},{"b":[0.68,0.49,0.05,0.04],"c":[0.605,0.455,0.2,0.11],"r":3.2323,"img":"img/L3/walk/p063_22_06.jpg","say":"오른쪽 단면의 300. 엠바 사이 간격이에요."}]}}]};
